// ── Full-set aggregate ID card — same unified structure as the Sunder Charms card.
// Built ENTIRELY off the verified ITEM_CODEX set-cat entries (setName / setMembers
// {name,slot,reqLvl} / setBonuses) — zero fabrication, no parallel data. Routes the
// collective set name to a rich card listing every piece as a tile + the full set bonus.
function _setCodexByName(name){
  if (typeof ITEM_CODEX === 'undefined' || !name) return null;
  var q = _norm(String(name).replace(/\s*\([^)]*\)\s*$/, ''));   // strip trailing "(Class)"/"(slot)" BEFORE normalizing (_norm turns ()→space)
  for (var k in ITEM_CODEX){ var c = ITEM_CODEX[k];
    if (c && c.cat === 'set'){ if (_norm(k) === _norm(name) || (c.setName && _norm(c.setName) === q)) return c; } }
  return null;
}
window._setCodexByName = _setCodexByName;
function isSetAggregate(name){ return !!_setCodexByName(name); }
window.isSetAggregate = isSetAggregate;
// A set's collective name has no art sprite of its own, so the "set picture" is the
// first member piece that has a verified in-game logo (zero fabrication — real piece art).
function _setRepArtName(name){
  var c = _setCodexByName(name); if (!c) return null;
  if (typeof artUrl === 'function'){
    if (c.setName && artUrl(c.setName)) return c.setName;
    var mem = c.setMembers || [];
    for (var i=0;i<mem.length;i++){ if (mem[i] && artUrl(mem[i].name)) return mem[i].name; }
  }
  return null;
}
window._setRepArtName = _setRepArtName;
function setDetailHtml(name, opts){
  var c = _setCodexByName(name); if (!c) return '';
  opts = opts || {};
  var sn = c.setName || name;
  var mem = c.setMembers || [];
  var tiles = mem.map(function(m){
    var sub = m.slot ? ('<div class="ct-sub">'+m.slot+(m.reqLvl?(' · req lvl '+m.reqLvl):'')+'</div>') : '';
    // v341.19 — each piece's individual in-game affixes, shown right on the tile (+ in its hover card)
    var aff = (m.affixes && m.affixes.length) ? ('<ul class="ct-affixes">'+m.affixes.map(function(a){ return '<li>'+a+'</li>'; }).join('')+'</ul>') : '';
    return '<div class="colossal-tile set-piece-tile" data-arttip="'+_d2artEsc(m.name)+'" title="'+_d2artEsc(m.name)+(m.slot?(' — '+_d2artEsc(m.slot)):'')+'">'
      + '<span class="ct-art">'+artOr(m.name, '<span class="ct-emoji">💎</span>', 'lg')+'</span>'
      + '<div class="ct-body"><div class="ct-name">'+m.name+'</div>'+sub+aff+'</div></div>';
  }).join('');
  var bonuses = (c.setBonuses||[]).map(function(s){ return '<div class="zd-row set-bonus-row"><span class="zd-v">'+s+'</span></div>'; }).join('');
  // v341.19 — partial set bonuses (the famous "2-piece +30% IAS" etc.) rendered before the full bonus
  var partials = (c.setPartials||[]).map(function(s){ return '<div class="zd-row set-bonus-row set-partial-row"><span class="zd-v">'+s+'</span></div>'; }).join('');
  var note = c.note ? ('<div class="gic-subtitle">'+c.note+'</div>') : '';
  var headerArtName = _setRepArtName(name) || sn;
  return '<div class="gic-card material-card set-items-card">'
    + '<header class="gic-header">'
    +   artOr(headerArtName, '<span class="gic-emoji">\uD83D\uDC8E</span>', 'lg')
    +   '<div class="gic-id-block">'
    +     '<h2 class="gic-name">'+sn+' <span class="gic-grail-badge" style="background:linear-gradient(135deg,#2e7d4f,#16432a);color:#dfffe0">Set \u00b7 '+mem.length+' pieces</span></h2>'
    +     note
    +     '<div class="gic-meta-row"><span class="gic-meta-chip">equip all '+mem.length+' \u2192 full set bonus</span><span class="gic-meta-chip" style="color:#8fe3a8;border-color:rgba(143,227,168,.4)">pieces drop individually across the game</span></div>'
    +   '</div>'
    +   (opts.embed ? '' : '<div style="display:flex;flex-direction:column;gap:6px"><button class="gic-close-btn" onclick="window.closeDrop&&window.closeDrop()" title="press ESC">\u2715 close</button></div>')
    + '</header>'
    + '<section class="gic-section"><div class="gic-section-title">\uD83D\uDC8E The '+mem.length+' set items \u2014 hover any piece for its stats</div>'
    +   '<div class="zd-note" style="margin-bottom:8px">Each piece is a distinct unique-rarity drop; hover its art for the in-game stat card. Collect all '+mem.length+' to light up the full set bonus below (track them in the Tools \u2192 Item Set Tracker).</div>'
    +   '<div class="colossal-grid">'+tiles+'</div></section>'
    + (partials ? ('<section class="gic-section"><div class="gic-section-title">\u2696\uFE0F Partial set bonuses \u2014 kick in as you equip pieces</div>'+partials+'</section>') : '')
    + '<section class="gic-section"><div class="gic-section-title">\uD83E\uDDEC Full set bonus \u2014 all '+mem.length+' equipped</div>'
    +   (bonuses || '<div class="zd-note">\u2014</div>')+'</section>'
    + '<div class="zd-note">\u26a0 Full-set bonuses are the in-game green set-completion stats (diablo2.io / Arreat Summit). Individual per-piece affixes show on each tile\u2019s hover card.</div>'
    + '</div>';
}
window.setDetailHtml = setDetailHtml;
