function findRune(name){
  if (typeof RUNES === 'undefined' || !name) return null;
  const q = String(name).toLowerCase().replace(/#\d+/g,'').replace(/\brunes?\b/g,'').replace(/[^a-z]/g,'').trim();
  if (!q) return null;
  return RUNES.find(r => r.n.toLowerCase() === q) || null;
}
