  document.querySelectorAll('.tz-zone-card.zone-open').forEach(c => c.classList.remove('zone-open'));
  if (willOpen) { box.innerHTML = zoneDetailHtml(z); box.removeAttribute('hidden'); box.closest('.tz-zone-card')?.classList.add('zone-open'); }
  else { box.setAttribute('hidden',''); box.innerHTML = ''; }
