// Super-unique cross-link: find the TZ_ZONES entry whose `unique` string names
// this super-unique (no hardcoded join — the two lists stay in sync).
function suTzZone(su){
  if (typeof TZ_ZONES === 'undefined' || !su) return null;
  const needle = (su.tzMatch || su.name).toLowerCase();
  for (let i = 0; i < TZ_ZONES.length; i++){
    if ((TZ_ZONES[i].unique || '').toLowerCase().includes(needle)) return {z: TZ_ZONES[i], zi: i};
  }
  return null;
}
// Three super-uniques are also tracked bosses (full drop tables) — cross-link them.
