      h += `<div class="zd-row su-pool-intro"><span class="zd-k">drop pool</span><span class="zd-v"><div class="zd-drops-head">🏆 native area · ${su.act} · mlvl ${su.mlvl} — ${nn} TC-reachable grail / uber uniques (every grail whose qlvl &le; mlvl ${su.mlvl}). Every item below routes to its own golden card, exactly like the Baal &amp; terror-zone drop tables.</div></span></div>`;
