function renderSuperUniques(){
  const el = document.getElementById('superunique-container');
  if (!el || typeof SUPER_UNIQUES === 'undefined') return;
  el.innerHTML = SUPER_UNIQUES.map((su, si) => {
    const tz = suTzZone(su);
    const tags = [];
    if (su.dclone) tags.push('<span class="tz-zone-tag hot">🔱 DClone camp</span>');
    if (tz) tags.push(`<span class="tz-zone-tag tc${tz.z.tcMax >= 87 ? '87' : '85'}">in TZ rotation</span>`);
    if (su.immune && su.immune !== 'none' && su.immune !== 'random (Hell)') tags.push(`<span class="tz-zone-tag dense">${su.immune} immune</span>`);
    const immune = su.immune === 'none' ? 'no fixed immunity' : su.immune + ' immune';
    return `<div class="su-card" data-su-idx="${si}" onclick="window.toggleSuperUnique(${si})" style="cursor:pointer" title="click for super-unique detail">
      <div class="tz-zone-header">
        <span class="sec-h-art tz-zone-emblem">${artOr(su.name, su.emoji, 'sm')}</span>
        <div class="tz-zone-title-block">
          <p class="tz-zone-name sec-h-t">${su.name}</p>
          <p class="tz-zone-sub">🎯 ${su.role}</p>
          <p class="tz-zone-loc">${su.act} · ${immune}</p>
        </div>
        <span class="tz-zone-tier">mlvl ${su.mlvl}</span>
        <span class="tz-zone-chev sec-chev" aria-hidden="true">▾</span>
      </div>
      <div class="tz-zone-collapse">
        <div class="tz-zone-tags">${tags.join('')}</div>
      </div>
      <div class="su-detail" id="su-detail-${si}" hidden></div>
    </div>`;
  }).join('');
}
function toggleSuperUnique(si){
  const su = (typeof SUPER_UNIQUES !== 'undefined') ? SUPER_UNIQUES[si] : null;
  if (!su) return;
  const box = document.getElementById('su-detail-' + si);
  if (!box) return;
  const willOpen = box.hasAttribute('hidden');
  document.querySelectorAll('.su-detail').forEach(b => { if (b !== box) { b.setAttribute('hidden',''); b.innerHTML = ''; } });
  document.querySelectorAll('.su-card.zone-open').forEach(c => { if (c.getAttribute('data-su-idx') !== String(si)) c.classList.remove('zone-open'); });
  const card = box.closest('.su-card');
  if (willOpen) { box.innerHTML = superUniqueDetailHtml(su); box.removeAttribute('hidden'); if (card) card.classList.add('zone-open'); }
  else { box.setAttribute('hidden',''); box.innerHTML = ''; if (card) card.classList.remove('zone-open'); }
}
window.toggleSuperUnique = toggleSuperUnique;
function jumpToTzZone(zi){
  const box = document.getElementById('tz-zone-detail-' + zi);
  if (box && box.hasAttribute('hidden') && typeof toggleZoneDetail === 'function') toggleZoneDetail(zi);
  const card = document.querySelector('.tz-zone-card[data-zone-idx="' + zi + '"]');
  if (card) card.scrollIntoView({behavior: 'smooth', block: 'start'});
}
