// v73: verified diablo2.io area artwork for each terror zone (keyed by TZ_ZONES name →
// the primary area's scene graphic). Every slug was HEAD-probed live (HTTP 200 + image)
// before shipping — zero guessed paths. tzZoneCardHtml renders these as a banner, and a
// hard onerror keeps a 404 from ever showing a broken-image box (the banner just hides).
const TZ_ART_BASE = "art/";
const TZ_ZONE_ART = {
  "Flayer Dungeon L3": "act3-flayerdungeon",
  "Crystalline Passage + Frozen River": "act5-crystallinepassage",
  "Bloody Foothills + Frigid Highlands + Abaddon": "act5-bloodyfoothills",
  "Worldstone Keep L1-L3": "act5-worldstonekeep",
  "Halls of Anguish/Pain/Vaught": "act5-hallsofanguish",
  "Arcane Sanctuary": "act2-arcanesanctuary",
  "River of Flame": "act4-riverofflames",
  "Tristram (the town)": "act1-tristram",
  "Burial Grounds + Crypt + Mausoleum": "act1-burial",
  "Spider Forest + Cavern": "act3-spiderforest",
  "Catacombs L4": "act1-catacombs",
};
function _tzArtSrc(slug){
  return (slug.indexOf('data:')===0||slug.indexOf('http')===0||slug.charAt(0)==='/'||slug.indexOf('banners/')===0)?slug:TZ_ART_BASE+slug+'_graphic.png';
}
// v148 — Konyo: drop the big 132px area banner; fold the SAME verified area art into a
// small boss-header-style emblem box (.sec-h-art look) at the head of the title row, so the
// TZ titles read exactly like the Bosses-tab section headers (boxed emblem + serif glow +
// chevron). Verified diablo2.io art is preserved — just relocated, no fabrication, onerror-safe.
function tzZoneEmblem(z){
  const slug = (typeof TZ_ZONE_ART !== 'undefined') ? TZ_ZONE_ART[z.name] : null;
  if (slug){
    return `<span class="sec-h-art tz-zone-emblem"><span class="d2art-wrap sm"><img class="d2art-img" loading="lazy" alt="${z.name}" src="${_tzArtSrc(slug)}" onload="this.parentNode.classList.remove('d2art-failed')" onerror="this.parentNode.classList.add('d2art-failed')"><span class="d2art-fallback"><span class="tz-zone-emoji">${z.emoji}</span></span></span></span>`;
  }
  return `<span class="sec-h-art tz-zone-emblem"><span class="tz-zone-emoji">${z.emoji}</span></span>`;
}
window.TZ_ZONE_ART = TZ_ZONE_ART;

// TERROR_GROUPS — group the farmable terror zones by the act they terrorize in, so the
// TZ list reads as an organized act-by-act roster instead of a flat pile. Each group is a
// labelled region header; renderTzZones() buckets every TZ_ZONES entry into exactly one
// group via `match` (preserving each zone's original index for routing). No zone data is
// duplicated — this is a pure presentation grouping over the single TZ_ZONES source.
const TERROR_GROUPS = [
  {act:"Act 1", emoji:"🏰", label:"Rogue Encampment → Tristram", match:(z)=>/Act 1/.test(z.act)},
  {act:"Act 2", emoji:"🏜️", label:"Lut Gholein → Arcane Sanctuary", match:(z)=>/Act 2/.test(z.act)},
  {act:"Act 3", emoji:"🌴", label:"Kurast → Flayer Jungle", match:(z)=>/Act 3/.test(z.act)},
  {act:"Act 4", emoji:"🔥", label:"Pandemonium → River of Flame", match:(z)=>/Act 4/.test(z.act)},
  {act:"Act 5", emoji:"⛰️", label:"Harrogath → Worldstone Keep", match:(z)=>/Act 5/.test(z.act)},
];

// TZ_CROSSLINKS — permanent lvl-85 zones (e.g. The Pit) that DO fire TZ alerts but aren't in
// TZ_ZONES because they're catalogued as permanent farm targets in the Bosses tab (alvl 85 by
// default, no terror needed). Each cross-link is a pure router into an existing BOSSES card —
// every display field is read live from that boss entry, so there's zero fabricated data here.
// `act` slots the card into the matching TERROR_GROUPS storyline-act bucket in renderTzZones().
const TZ_CROSSLINKS = [
  {bossId:"pit", act:"Act 1"},   // 🕳️ The Pit · Tamoe Highland · alvl 85 · the user's S-TIER TZ alert
];

