const _RUNE_COUNTESS = (function(){
  const m = {};
  (typeof COUNTESS_RUNES !== 'undefined' ? COUNTESS_RUNES : []).forEach(r => {
    const base = (r.n.split('#')[0] || '').trim();
    if (base && !/[- ]/.test(base) && r.hell != null) m[base.toLowerCase()] = {hell:r.hell, hellTz:r.hellTz};
  });
  return m;
})();

