function _rwNorm(s){ return String(s==null?'':s).replace(/\([^)]*\)/g,'').toLowerCase().replace(/[^a-z0-9]/g,''); }
const _RW_TIP_INDEX = (function(){ var m={}; for (var k in RUNEWORD_TIP){ m[_rwNorm(k)] = k; } return m; })();
function findRuneword(name){
  if (!name || typeof RUNEWORD_TIP === 'undefined') return null;
  if (RUNEWORD_TIP[name]) return name;
  var k = _RW_TIP_INDEX[_rwNorm(name)];
  return k || null;
}
window.findRuneword = findRuneword;
// v418 — ROBUST runeword resolver. A runeword tooltip reads as the runeword name FOLLOWED (or preceded) by the
// base type — "Spirit Monarch", "Chains of Honor Dusk Shroud", "Crystal Sword 'Spirit'". findRuneword only
// strips "(4os)"-style suffixes, so those concatenated reads slip through to the THROW-OUT pile (Konyo's cousin:
// "Chains of Honor / Spirit are runewords, mule them"). This peels a leading/trailing KNOWN BASE TYPE (or a
// quoted segment) off the read and re-resolves the remainder, so the runeword is recognised + muled. Requires
// the non-runeword part to be a real base (BASE_CLASS/_baseCats) → can't false-match a rare like "Spirit Caller".
function _rwResolve(name){
  if (!name || typeof RUNEWORD_TIP === 'undefined') return null;
  var d = findRuneword(name); if (d) return d;                       // exact / normalized fast path
  var s = String(name).replace(/\s+/g, ' ').trim();
  // 1) a quoted runeword anywhere: Base 'Spirit'  ·  "Chains of Honor" Monarch
  var qm = s.match(/[‘’'"]\s*([A-Za-z][A-Za-z' ]*?)\s*[‘’'"]/);
  if (qm){ var q = findRuneword(qm[1].trim()); if (q) return q; }
  // 2) runeword name with a KNOWN BASE TYPE glued to either end
  if (typeof _baseCats === 'function'){
    var clean = s.replace(/\(.*?\)/g, ' ').replace(/[‘’'"]/g, ' ').replace(/\s+/g, ' ').trim();
    var cl = clean.toLowerCase(), best = null, bestLen = 0;
    Object.keys(RUNEWORD_TIP).forEach(function(k){
      var kl = k.toLowerCase();
      if (k.length <= bestLen) return;
      if (cl.indexOf(kl + ' ') === 0){                                // "<RW> <base>"  → tail must be a base
        var tail = clean.slice(k.length).trim();
        if (tail && Object.keys(_baseCats(tail)).length > 0){ best = k; bestLen = k.length; }
      } else if (cl.length > kl.length && cl.slice(cl.length - kl.length) === kl && cl.charAt(cl.length - kl.length - 1) === ' '){
        var head = clean.slice(0, clean.length - k.length).trim();   // "<base> <RW>" → head must be a base
        if (head && Object.keys(_baseCats(head)).length > 0){ best = k; bestLen = k.length; }
      }
    });
    if (best) return best;
  }
  return null;
}
