function _rwTipHtml(o){
  var head = 'Runeword' + (o.b ? ' &middot; ' + o.b : '');
  var rec = (o.rec && o.rec.length) ? '<div class="att-meta att-rwrec">' + o.rec.join(' + ') + '</div>' : '';
  var meta = (o.r != null) ? 'Req level: ' + o.r : '';
  var rows = o.l.map(function(l){ return '<div class="att-aff">' + _sunMarkup(l) + '</div>'; }).join('');
  return '<div class="att-type">' + head + '</div>' + rec + (meta ? '<div class="att-meta">' + meta + '</div>' : '') + rows;
}
window._rwTipHtml = _rwTipHtml;

function runewordDetailHtml(name){
  var key = findRuneword(name); if (!key) return '';
  var o = RUNEWORD_TIP[key];
  var recChips = (o.rec||[]).map(function(rn){
    var e = rn.replace(/'/g, "\\'");
    return '<span class="mw-rune-chip" data-arttip="'+rn+'" onclick="window.openDrop&&window.openDrop(\''+e+'\')" title="open the '+rn+' rune card">'+rn+'</span>';
  }).join('<span class="rwd-plus">+</span>');
  var rows = o.l.map(function(l){ return '<div class="zd-row rwd-stat"><span class="zd-v">'+_sunMarkup(l)+'</span></div>'; }).join('');
  return '<div class="gic-card runeword-card">'
    + '<header class="gic-header">'
    + '<span class="d2art-wrap lg"><span class="gic-emoji" style="font-family:serif;font-size:30px">⚒️</span></span>'
    + '<div class="gic-id-block">'
    + '<h2 class="gic-name">'+key+' <span class="gic-grail-badge" style="background:linear-gradient(135deg,#3a5a8a,#12243a);color:#bcd6ff">Runeword</span>'+( (typeof _RW_LADDER_ONLY!=='undefined' && _RW_LADDER_ONLY[key]) ? ' <span class="rw-ladder-stamp" title="Ladder-only runeword — only forms on a LADDER character">🪜 LADDER&nbsp;ONLY</span>' : '')+'</h2>'
    + '<div class="gic-subtitle">'+o.b+(o.r!=null?' · req level '+o.r:'')+'</div>'
    + '<div class="gic-meta-row"><span class="gic-meta-chip">'+(o.rec||[]).length+' runes</span><span class="gic-meta-chip" style="color:#bcd6ff;border-color:rgba(188,214,255,.4)">crafted</span></div>'
    + '</div>'
    + '<div style="display:flex;flex-direction:column;gap:6px"><button class="gic-close-btn" onclick="window.closeDrop&&window.closeDrop()" title="press ESC">✕ close</button></div>'
    + '</header>'
    + '<section class="gic-section"><div class="gic-section-title">🔤 Recipe (in order)</div><div class="rwd-recipe">'+recChips+'</div></section>'
    + '<section class="gic-section"><div class="gic-section-title">⚠️ Before you cube — or you waste the runes</div>'
    +   (function(){ var g = (typeof window._rwGuard==='function') ? window._rwGuard(key) : null; if(!g) return '';
         var bg = g.level==='block' ? 'linear-gradient(135deg,rgba(255,60,60,.18),rgba(120,0,0,.12))' : (g.level==='ok' ? 'linear-gradient(135deg,rgba(102,255,136,.15),rgba(0,80,30,.1))' : 'linear-gradient(135deg,rgba(240,192,96,.15),rgba(120,80,0,.1))');
         var bc = g.level==='block' ? 'rgba(255,80,80,.6)' : (g.level==='ok' ? 'rgba(102,255,136,.5)' : 'rgba(240,192,96,.5)');
         var ic = g.level==='block' ? '⛔' : (g.level==='ok' ? '✅' : '⚠️');
         var hd = g.level==='block' ? 'DO NOT CUBE — this will waste your runes' : (g.level==='ok' ? 'Confirmed working on your server' : 'Verify before you commit high runes');
         return '<div class="rw-guard" style="background:'+bg+';border:1px solid '+bc+';border-radius:8px;padding:10px 12px;margin-bottom:9px">'
           + '<div style="font-weight:700;color:#fff;margin-bottom:3px">'+ic+' '+hd+'</div>'
           + '<div style="font-size:12.5px;color:var(--text,#cfc4b0);line-height:1.5">'+g.why+'</div>'
           + '<div style="margin-top:8px;display:flex;gap:7px;flex-wrap:wrap;align-items:center"><span style="font-size:11px;color:var(--text-dim,#9a8c72)">From your game:</span>'
           +   '<button onclick="window.rwSetVerify&&window.rwSetVerify(\''+key.replace(/'/g,"\\'")+'\',\'ok\')" style="cursor:pointer;font-size:11px;padding:3px 9px;border-radius:5px;border:1px solid rgba(102,255,136,.5);background:rgba(102,255,136,.1);color:#9effb9">✅ it formed</button>'
           +   '<button onclick="window.rwSetVerify&&window.rwSetVerify(\''+key.replace(/'/g,"\\'")+'\',\'fail\')" style="cursor:pointer;font-size:11px;padding:3px 9px;border-radius:5px;border:1px solid rgba(255,80,80,.5);background:rgba(255,80,80,.1);color:#ff9b9b">❌ didn’t form</button>'
           +   '<button onclick="window.rwSetVerify&&window.rwSetVerify(\''+key.replace(/'/g,"\\'")+'\',null)" style="cursor:pointer;font-size:11px;padding:3px 9px;border-radius:5px;border:1px solid var(--border,#3a2f1e);background:none;color:var(--text-dim,#9a8c72)">clear</button>'
           + '</div></div>';
       })()
    +   '<div class="zd-row rwd-stat"><span class="zd-v"><b style="color:var(--hell,#ff5555)">The base must be a non-magical item</b> — <b>white/grey, low-quality, OR Superior</b> all work (a Superior base even keeps its bonus); only a <b>magic, rare, set, crafted or unique</b> base will <b>NOT</b> form a runeword (the runes just socket in as a "Gemmed" item and are wasted).</span></div>'
    +   '<div class="zd-row rwd-stat"><span class="zd-v">It must be a <b>'+_d2artEsc(o.b)+'</b> with <b>EXACTLY '+(o.rec||[]).length+' socket'+((o.rec||[]).length===1?'':'s')+'</b> — not more, not fewer.</span></div>'
    +   '<div class="zd-row rwd-stat"><span class="zd-v">Insert the runes <b>left-to-right in this EXACT order</b>: <b>'+(o.rec||[]).join(' → ')+'</b>.</span></div>'
    + '</section>'
    + '<section class="gic-section"><div class="gic-section-title">⚙️ In-game stats</div>'+rows+'</section>'
    + '<div class="zd-note">⚠ Stats transcribed verbatim from diablo2.io\'s Reign of the Warlock runeword tooltip for '+key+'. Variable ranges shown as [min–max]. Runewords are crafted (cube the runes into a socketed base), not dropped — they are not part of the 322-item grail count.</div>'
    + '</div>';
}
window.runewordDetailHtml = runewordDetailHtml;

