  var fcr     = num(/(\d+)\s*%?\s*Faster\s*Cast\s*Rate/i);
  var frw     = num(/(\d+)\s*%?\s*Faster\s*Run\/?Walk/i);
  var fhr     = num(/(\d+)\s*%?\s*Faster\s*Hit\s*Recovery/i);
  var ias     = num(/(\d+)\s*%?\s*(?:Increased\s*Attack\s*Speed)/i);
  var ed      = num(/(\d+)\s*%?\s*Enhanced\s*Damage/i);
  var ar      = num(/\+?\s*(\d+)\s*(?:to\s*)?Attack\s*Rating\b/i);   // v446 — key MELEE/bow ring stat (perfect ≈120 AR)
  var maxd    = num(/\+\s*(\d+)\s*to\s*Maximum\s*Damage\b/i);        // v446 — small but real melee ring roll (perfect 4)
  var life    = num(/\+\s*(\d+)\s*(?:to\s*)?Life\b/i);
  var mana    = num(/\+\s*(\d+)\s*(?:to\s*)?Mana\b/i);
  var allStat = num(/\+\s*(\d+)\s*to\s*All\s*Attributes/i);
  var str     = num(/\+\s*(\d+)\s*to\s*Strength/i);
  var dex     = num(/\+\s*(\d+)\s*to\s*Dexterity/i);
  var vit     = num(/\+\s*(\d+)\s*to\s*Vitality/i);
  var mf      = num(/(\d+)\s*%?\s*(?:Better Chance of Getting Magic Items|Magic Find)/i);
  var allRes  = num(/All\s*Resist\w*\s*\+?\s*(\d+)/i);
  var sr = /(?:Fire|Cold|Lightning|Poison)\s*Resist\w*\s*\+?\s*(\d+)/ig, sm, bestSr=0;
  while((sm=sr.exec(txt))) bestSr=Math.max(bestSr,+sm[1]);
  var goldSkill = _isSkillBonus(2);   // v445 — +2+ to a class skill/TAB (incl. Shadow Disciplines/Traps/etc.) or any +All Skills

  var strong = [], medium = [];
  if (dualLeech)      strong.push('dual leech');
  if (fcr >= 10)      strong.push(fcr+'% FCR');
  if (goldSkill)      strong.push('+skills');
  if (allRes >= 15)   strong.push('+'+allRes+' all res');
  if (mf >= 25)       strong.push(mf+'% MF');
  if (allStat >= 8)   strong.push('+'+allStat+' all stats');
  if (ed >= 30)       strong.push(ed+'% ED');

  if (!dualLeech && (lifeL||manaL)) medium.push(lifeL?'life leech':'mana leech');
  if (life >= 20)                medium.push('+'+life+' life');
  if (mana >= 40)                medium.push('+'+mana+' mana');
  if (allRes >= 8 && allRes < 15) medium.push('+'+allRes+' all res');
  if (bestSr >= 25)              medium.push('+'+bestSr+'% res');
  if (allStat >= 4 && allStat < 8) medium.push('+'+allStat+' all stats');
  if (str >= 15)                 medium.push('+'+str+' str');
  if (dex >= 15)                 medium.push('+'+dex+' dex');
  if (vit >= 15)                 medium.push('+'+vit+' vit');
  if (mf >= 12 && mf < 25)       medium.push(mf+'% MF');
  if (fcr >= 5 && fcr < 10)      medium.push(fcr+'% FCR');
  if (fhr >= 10)                 medium.push(fhr+'% FHR');
  if (frw >= 20)                 medium.push(frw+'% FRW');
  if (ias >= 15)                 medium.push(ias+'% IAS');
  if (ed >= 15 && ed < 30)       medium.push(ed+'% ED');
  if (ar >= 80)                  medium.push('+'+ar+' AR');         // v446 — melee/bow ring stat (diablo2.io "perfect" ≈120)
  if (maxd >= 3)                 medium.push('+'+maxd+' max dmg');  // v446 — small melee roll, completes a 3-suffix ring

