  ov.innerHTML = '<div class="ai-load"><div class="ai-load-orb">📸</div><div class="ai-load-body">'
    + '<div class="ai-load-title">' + esc(title) + '<span class="ai-load-dots"><i>.</i><i>.</i><i>.</i></span></div>'
