// v341.41 — themed replacement for the OS-native confirm() white box. Returns a Promise<bool>.
// Destructive by default (red OK). Esc/backdrop = cancel, Enter = OK.
window.uiConfirm = function(message, opts){
  opts = opts || {};
  return new Promise(function(resolve){
    var esc = function(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); };
    var ov = document.createElement('div');
    ov.className = 'ui-confirm-ov';
    var danger = opts.danger !== false;   // these confirms are destructive (clear/delete/erase)
    ov.innerHTML = '<div class="ui-confirm" role="alertdialog" aria-modal="true">'
      + '<div class="ui-confirm-ic">' + (opts.icon || '⚠️') + '</div>'
      + '<div class="ui-confirm-msg">' + esc(message).replace(/\n/g,'<br>') + '</div>'
      + '<div class="ui-confirm-row">'
      + '<button class="ui-confirm-btn ui-confirm-cancel">' + esc(opts.cancel || 'Cancel') + '</button>'
      + '<button class="ui-confirm-btn ui-confirm-ok' + (danger ? ' danger' : '') + '">' + esc(opts.ok || 'OK') + '</button>'
      + '</div></div>';
    var done = false;
    function close(val){ if(done) return; done = true; ov.classList.remove('on'); document.removeEventListener('keydown', onKey); setTimeout(function(){ try{ ov.remove(); }catch(e){} }, 180); resolve(val); }
    function onKey(e){ if(e.key === 'Escape'){ e.preventDefault(); close(false); } else if(e.key === 'Enter'){ e.preventDefault(); close(true); } }
    ov.addEventListener('click', function(e){ if(e.target === ov) close(false); });
    ov.querySelector('.ui-confirm-cancel').onclick = function(){ close(false); };
    ov.querySelector('.ui-confirm-ok').onclick = function(){ close(true); };
    document.addEventListener('keydown', onKey);
    document.body.appendChild(ov);
    requestAnimationFrame(function(){ ov.classList.add('on'); try{ ov.querySelector('.ui-confirm-ok').focus(); }catch(e){} });
  });
};

