// The Pandemonium keys, Uber organs, Sunder charms, Hellfire Torch, Annihilus and
// Colossal Jewels are the game's pinnacle "you came here for THIS" drops. The names
// below are the canonical in-game item names already used by openDrop()/SPECIAL_DROPS
// (nothing invented). markEndgameRelics() tags every element that routes to one — via
// its openDrop() target — with .endgame-relic, so the shared gold pulse lights them up
// wherever they render (boss cards, zone tables, the events tab, search) with zero
// per-site edits. A MutationObserver re-applies it as dynamic content mounts.
const ENDGAME_RELICS = new Set([
  'Key of Terror','Key of Hate','Key of Destruction',
  "Diablo's Horn","Mephisto's Brain","Baal's Eye",
  'Hellfire Torch','Annihilus','Colossal Ancient Jewels',
  'Bone Break','Black Cleft','Crack of the Heavens','Cold Rupture','Flame Rift','Rotting Fissure'
]);
window.ENDGAME_RELICS = ENDGAME_RELICS;
function isEndgameRelic(name){ return !!name && ENDGAME_RELICS.has(String(name).trim()); }
window.isEndgameRelic = isEndgameRelic;
function markEndgameRelics(root){
  const scope = (root && root.querySelectorAll) ? root : document;
  scope.querySelectorAll('[onclick*="openDrop"]').forEach(el => {
    if (el.classList.contains('endgame-relic')) return;
    const oc = (el.getAttribute('onclick') || '').replace(/\\/g, ''); // drop \' escaping
    for (const r of ENDGAME_RELICS){
      if (oc.indexOf("openDrop('" + r + "')") !== -1 || oc.indexOf('openDrop("' + r + '")') !== -1){ el.classList.add('endgame-relic'); break; }
    }
  });
}
window.markEndgameRelics = markEndgameRelics;
(function relicObserver(){
  let queued = false;
  const run = () => { queued = false; try { markEndgameRelics(document); } catch(e){} };
  const start = () => {
    markEndgameRelics(document);
    new MutationObserver(() => { if (queued) return; queued = true; requestAnimationFrame(run); })
      .observe(document.body, { childList:true, subtree:true });
  };
  if (document.body) start(); else document.addEventListener('DOMContentLoaded', start);
})();

// The Road to the Hellfire Torch — the endgame storyline tab. Every drop node is
// clickable and routes to its full card; data is cross-referenced with the events
// tables above (keys ~10% Hell /p3+, organs 100% per kill).
function renderEndgameRoad(){
  const box = document.getElementById('endgame-road');
  if (!box) return;
  const node = (item, emoji, src, rate) =>
    '<div class="road-node" role="button" tabindex="0" onclick="window.openDrop(\'' + item.replace(/'/g, "\\'") + '\')">'
    + '<div class="rn-art">' + artOr(item, emoji, 'lg') + '</div>'
    + '<div class="rn-name" style="color:var(--q-orange) !important">' + item + '</div>'
    + '<div class="rn-src">' + src + '</div>'
    + '<div class="rn-rate">' + rate + '</div></div>';
  // Branch-title emblems — the upgraded animated art logos (relicArtGlow runs on the
  // .d2art-img inside the .endgame-relic branch), matching the home-tab event-card
  // logos. branchEmblem uses a diablo2.io item file; branchEmblemRaw a raw data-URI.
  const branchEmblem = (file, emoji) =>
    '<span class="rb-art"><span class="d2art-wrap lg"><img class="d2art-img" src="art/' + file + '" alt="" loading="lazy" onerror="this.parentNode.classList.add(\'d2art-failed\')"><span class="d2art-fallback"><span class="gbc-emoji">' + emoji + '</span></span></span></span>';
  const branchEmblemRaw = (src, emoji) =>
    '<span class="rb-art"><span class="d2art-wrap lg"><img class="d2art-img" src="' + src + '" alt="" loading="lazy" onerror="this.parentNode.classList.add(\'d2art-failed\')"><span class="d2art-fallback"><span class="gbc-emoji">' + emoji + '</span></span></span></span>';
  const keys = node('Key of Terror','🔑','Hell Countess · Forgotten Tower L5','~10% · Hell · /p3+')
    + node('Key of Hate','🔑','Hell Summoner · Arcane Sanctuary','~10% · Hell · /p3+')
    + node('Key of Destruction','🔑','Hell Nihlathak · Halls of Vaught','~10% · Hell · /p3+');
  const organs = node("Diablo's Horn",'🩸',"Lilith · Matron's Den",'100% per kill')
    + node("Mephisto's Brain",'🩸','Uber Izual · Furnace of Pain','100% per kill')
    + node("Baal's Eye",'🩸','Uber Duriel · Forgotten Sands','100% per kill');
  box.innerHTML =
    '<div class="road-hero"><h1>⛓️ The Road to the Hellfire Torch</h1>'
    + '<p>The deepest endgame chain in the game, end to end. Three Pandemonium keys open the mini-uber portals; three organs open Uber Tristram; the trio drops the Torch. Two pinnacle side-paths — the Diablo Clone and the Colossal Ancients — branch off the same journey. Every drop below is clickable and routes to its full card.</p></div>'
    + '<div class="road-stage"><div class="road-step"><span class="road-n">1</span>Farm the three Pandemonium keys</div><div class="road-nodes">' + keys + '</div>'
    + '<div class="road-cube">cube <code>1× Key of Terror + 1× Key of Hate + 1× Key of Destruction</code> → one <strong>random</strong> mini-uber portal (run 3 full sets for all 3 organs)</div></div>'
    + '<div class="road-arrow">▼</div>'
    + '<div class="road-stage"><div class="road-step"><span class="road-n">2</span>Kill the mini-ubers for the three organs</div><div class="road-nodes">' + organs + '</div>'
    + '<div class="road-cube">cube <code>Diablo\'s Horn + Mephisto\'s Brain + Baal\'s Eye</code> → the <strong>Uber Tristram</strong> red portal</div></div>'
    + '<div class="road-arrow">▼</div>'
    + '<div class="road-final" role="button" tabindex="0" onclick="window.openDrop(\'Hellfire Torch\')"><div class="rf-art">' + artOr('Hellfire Torch','🔥','lg') + '</div>'
    + '<div><div class="rf-name" style="color:var(--gold-bright) !important">🔥 Hellfire Torch</div><div class="rf-sub">+3 random class skills · +10–20 all resist · +10 all stats — the Uber Tristram trio is the <strong>only</strong> source · 1 per character</div></div></div>'
    + '<div class="road-section-h">Pinnacle side-paths off the same road</div>'
    + '<div class="road-branches">'
    + '<div class="road-branch endgame-relic" role="button" tabindex="0" onclick="window.openDrop(\'Annihilus\')"><h3>' + branchEmblem('diablo_graphic.png','🌑') + '<span style="color:var(--q-unique)">Diablo Clone → Annihilus</span></h3><p>A world event triggered by mass Stone of Jordan sales. Über Diablo spawns; killing him drops the <strong>Annihilus</strong> — the only small charm with +1 all skills, +10-20 all attributes, +10-20 all resist and +5-10% experience. Every kill drops one.</p></div>'
    + '<div class="road-branch endgame-relic" role="button" tabindex="0" onclick="window.openDrop(\'Colossal Ancient Jewels\')"><h3>' + branchEmblem('talic-opt_graphic.png','👑') + '<span style="color:var(--q-unique)">Colossal Ancients → Colossal Jewels</span></h3><p>The RotW pinnacle. Collect 5 Colossal Statues, cube the <strong>Colossal Summit</strong>, and beat Talic / Korlic / Madawc to claim the <strong>Colossal Ancient Jewels</strong> (lvl-75).</p></div>'
    + '</div>'
    + '<div class="road-section-h">The other endgame relics</div>'
    + '<div class="road-branches">'
    + '<div class="road-branch endgame-relic" role="button" tabindex="0" onclick="window.openDrop(\'Herald of Terror\')"><h3>' + branchEmblemRaw(HERALD_PORTRAIT,'👹') + '<span style="color:#b07cff">Herald of Terror</span></h3><p>The RotW apex super-unique. The five-rung Herald ladder (Fright → Terror) scales loot and is the gateway to the Sunder charms. Opens the Herald card.</p></div>'
    + '<div class="road-branch endgame-relic" role="button" tabindex="0" onclick="window.openDrop(\'Sunder Charms\')"><h3><span class="rb-art">' + artOr('Sunder Charms','💠','lg') + '</span><span style="color:var(--q-unique)">Sunder Charms</span></h3><p>Six element-piercing grand charms (Bone Break, Black Cleft, Crack of the Heavens, Cold Rupture, Flame Rift, Rotting Fissure) — cube Worldstone Shards into a Latent Sunder, then upgrade to a Renewed Sunder. Opens the unified Sunder card with all 6 ID cards.</p></div>'
    + '</div>';
  markEndgameRelics(box);
}
window.renderEndgameRoad = renderEndgameRoad;

const ITEM_REGISTRY = {};
BOSSES.forEach(boss => {
  boss.dropTable.forEach(d => {
    if (!ITEM_REGISTRY[d.n]) {
      ITEM_REGISTRY[d.n] = {n:d.n,tc:d.tc,qlvl:d.qlvl,tier:d.tier,sources:[]};
      ITEMS.push(ITEM_REGISTRY[d.n]);
    }
    const item = ITEM_REGISTRY[d.n];
    const verifiedDiffs = d.v || [];
    [["norm","Normal",0],["normTz","Normal TZ",1],["nm","NM",2],["nmTz","NM TZ",3],["hell","Hell",4],["hellTz","Hell TZ",5]].forEach(([k,label,idx]) => {
      const chance = d[k];
      const diff = boss.diffs[idx];
      const isVer = verifiedDiffs.includes(k);
      const kphMult = (k === "norm" || k === "normTz") ? 1.2 : (k === "nm" || k === "nmTz") ? 1.1 : 1.0;
      const effKph = Math.round(boss.kph * kphMult);
      if (chance !== null && chance !== undefined) {
        item.sources.push({boss:`${label} ${boss.name}`,chance,bossId:boss.id,verified:isVer,kph:effKph,diffKey:k});
      } else {
        let blocked = null;
        if (d.qlvl > 0 && d.qlvl > diff.mlvl) blocked = `qlvl ${d.qlvl} > ${label} mlvl ${diff.mlvl}`;
        else if (d.tc > 0 && d.tc > diff.tcMax) blocked = `TC ${d.tc} > ${label} ${boss.name} TC ${diff.tcMax}`;
        if (blocked) item.sources.push({boss:`${label} ${boss.name}`,chance:null,blocked,bossId:boss.id,diffKey:k});
      }
    });
  });
});

