// v42 UX fix: safe JSON parse — corrupt localStorage (browser quirks, dev tools edits,
// failed mid-write) was crashing the bible by throwing ReferenceError on every variable
// after the failed line. Now any bad key silently falls back to its default.
const _safeJsonParse = (raw, fallback) => {
  if (raw === null || raw === undefined) return fallback;
  try { return JSON.parse(raw); } catch(e) {
    console.warn('[bible] corrupt localStorage value, using default:', e.message);
    return fallback;
  }
};
