// v395 — ETHEREAL items: names the AI flagged as Ethereal (Cannot be Repaired). Shown with an ⊘ eth badge.
let etherealItems = new Set(_safeJsonParse(LS.getItem('d2r_ethereal'), []));
try { window.etherealItems = etherealItems; } catch(e){}   // v429 — exposed for the ethereal audit/debug
// v429 — KNOWLEDGE of what CAN vs CAN'T be ethereal (D2 rules), so a mis-read never tags an impossible item.
// CAN be ethereal: all armour (body/helm/shield/gloves/boots/belt/circlet), melee weapons, bows/crossbows,
// and class off-hands (orbs, wands, staves, scepters, voodoo/shrunken heads, grimoires). CANNOT: rings,
// amulets, jewels, charms, runes, gems (not equipment damage/defence), JAVELINS + THROWING weapons (they
// stack/are thrown — ethereal needs durability). Returns true/false, or null when the type is unknown (then
// we don't assert either way). Suffix-tolerant ("(Nos)", "(ethereal)").
function _canBeEthereal(name){
  if (!name) return null;
  var n = String(name).replace(/\s*\([^)]*\)\s*$/, '').trim();
  // 1) BASE CLASS FIRST (authoritative) — so "Ring Mail"/"Chain Mail"/"Scale Mail" read as body armour (CAN be
  // ethereal), NOT as jewelry from the word "ring". Same lesson as the \brune\b collision: trust the class map
  // over a name substring.
  var cats = (typeof _baseCats === 'function') ? _baseCats(n) : {};
  var keys = Object.keys(cats);
  if (keys.length){
    if (cats['javelin']) return false;                 // javelins stack/throw — never ethereal
    if (cats['weapon'] && !cats['melee weapon'] && !cats['missile weapon']) return false;  // throwing axe/knife/dart
    return true;                                       // armour (all), melee weapons, bows/xbows, orbs, staves, heads…
  }
  // 2) not a base itself → resolve a UNIQUE / SET / off-grail name to its BASE type, judge that
  // (Windforce→Hydra Bow→can, Gheed's→Grand Charm→cannot, Darkglow→Ring Mail→body armour→can).
  var base = '';
  try { if (typeof ITEM_CODEX!=='undefined' && ITEM_CODEX[n] && ITEM_CODEX[n].base) base = ITEM_CODEX[n].base; } catch(e){}
  try { if (!base && typeof EXTRA_ITEMS!=='undefined' && EXTRA_ITEMS[n] && EXTRA_ITEMS[n].base) base = EXTRA_ITEMS[n].base; } catch(e){}
  try { if (!base && typeof ITEM_TIP!=='undefined' && ITEM_TIP[n] && ITEM_TIP[n].b) base = String(ITEM_TIP[n].b).replace(/^\d+\s*socket\s*/i,''); } catch(e){}
  try { if (!base && typeof findSetPiece==='function'){ var _sp = findSetPiece(n); if (_sp && _sp.base) base = _sp.base; } } catch(e){}
  if (base && _etherNorm(base) !== _etherNorm(n)) return _canBeEthereal(base);   // recurse on the resolved base (its class OR its name decides)
  // 3) NO base class anywhere → fall back to the name kind. Jewelry/charm/rune/gem can't be ethereal; a unique
  // ring/amulet (Raven Frost, Mara's) lands here with no class → its base type ('Ring'/'Amulet') also has no
  // class in BASE_CLASS, so use the name. (Genuine armour/weapon bases never reach here — they matched step 1.)
  var low = n.toLowerCase();
  if (/\b(ring|amulet|jewel|charm|rainbow facet)\b/.test(low)) return false;
  if (/\brune\b(?!\s+(?:sword|bow|staff|scepter|master))/.test(low)) return false;
  if (/\b(chipped|flawed|flawless|perfect)\b/.test(low) && /\b(amethyst|topaz|sapphire|emerald|ruby|diamond|skull)\b/.test(low)) return false;
  return null;                                         // truly unknown type → don't assert
}
window._canBeEthereal = _canBeEthereal;
window._isEthereal = function(n){ try {
  if (_canBeEthereal(n) === false) return false;                 // v429 — a type that CAN'T be ethereal never is (kills mis-flags)
  if (etherealItems.has(n)) return true;                         // exact match (fast path)
  var nn = _etherNorm(n); if (!nn) return false;                 // v402 — fall back to base-normalized match
  for (var e of etherealItems){ if (_etherNorm(e) === nn) return true; }
  return false;
} catch(e){ return false; } };
// v450 (CORRECTS v412) — SUPERIOR socketed bases. A Superior base IS a normal-quality (white) item and DOES
// form runewords like any white base — and keeps its superior bonus on top. Tracked like ethereal so the base
// card shows the "valid superior base (keeps its bonus)" note (NOT the old wrong "can't runeword" warning).
let superiorBases = new Set(_safeJsonParse(LS.getItem('d2r_superiorBases'), []));
window._isSuperior = function(n){ try {
  // v580.1 — the NAME PREFIX is authoritative too: a base registered/labelled "Superior X (…)" is superior
  // even when the intake's superiorBases flag-set never saw it (live bug: the cube gamble fired on Konyo's
  // "Superior Flail (Larzuk base)" because only the flag-set was checked).
  if (/^\s*Superior\s+/i.test(String(n || ''))) return true;
  if (superiorBases.has(n)) return true;
  var nn = _etherNorm(n); if (!nn) return false;
  for (var e of superiorBases){ if (_etherNorm(e) === nn) return true; }
  return false;
} catch(e){ return false; } };
