// the verdict for a runeword card: blocked (won't form for you) / caution (unverified) / ok.
window._rwGuard = function(key){
  if (!key) return null;
  var v = rwVerify[key], ladderOnly = !!_RW_LADDER_ONLY[key], nonLadder = (rwLadderMode === 'nonladder');
  if (v === 'fail') return { level:'block', why:'You marked this as <b>did-not-form</b> in your game.' + (ladderOnly?' It is a <b>ladder-only</b> runeword — it will not form on a non-ladder character.':'') };
  if (v === 'ok') return { level:'ok', why:'You confirmed this <b>formed</b> in your game.' };   // explicit success = ground truth, overrides the ladder assumption
  if (ladderOnly && nonLadder) return { level:'block', why:'<b>Ladder-only</b> runeword — it will <b>not form on a non-ladder character</b>. Set your mode to Ladder (top of the Chronicle) only if your character truly is ladder.' };
  if (ladderOnly) return { level:'caution', why:'<b>Ladder-only</b> runeword — only forms on a <b>ladder</b> character. Confirm your character is ladder before cubing.' };
  return { level:'caution', why:'Recipe not yet confirmed on your server — <b>test on a cheap base first</b> before committing high runes.' };
};
