const effMF = (gMF, factor) => (gMF*100)/(gMF+factor);
const adjustChance = (base, gMF) => {
  if (!base) return null;
  if (base < 100) return base;
  const refEff = effMF(300, 250);
  const userEff = effMF(gMF, 250);
  return Math.round(base * (1+refEff/100) / (1+userEff/100));
};
const PLAYER_Q = {"countess":{"norm":0.0,"nm":0.0,"hell":0.0},"andariel":{"norm":0.28358,"nm":0.28358,"hell":0.27941},"duriel":{"norm":0.0,"nm":0.0,"hell":0.0},"mephisto":{"norm":0.1875,"nm":0.1875,"hell":0.18293},"travincal":{"norm":0.34545,"nm":0.34545,"hell":0.34545},"diablo":{"norm":0.1875,"nm":0.1875,"hell":0.18293},"baal":{"norm":0.1875,"nm":0.1875,"hell":0.18293},"pindle":{"norm":0.0,"nm":0.0,"hell":0.0},"nihl":{"norm":0.31667,"nm":0.31667,"hell":0.31148},"cows":{"norm":0.625,"nm":0.625,"hell":0.625},"pit":{"norm":0.625,"nm":0.625,"hell":0.625}};
    function playerMult(bossId, diffKey, players){
      if(!bossId || !diffKey) return 1;
      var tier = diffKey.indexOf('hell')===0 ? 'hell' : diffKey.indexOf('nm')===0 ? 'nm' : 'norm';
      var q = (PLAYER_Q[bossId]||{})[tier];
      if(!q) return 1;
      var k = 1 + Math.floor((players||1)/2);
      return (1 - Math.pow(q,k)) / (1 - q);
    }
    function effChance(base, bossId, diffKey){
      var a = adjustChance(base, mf);
      if (a === null || a < 100) return a;
      var m = playerMult(bossId, diffKey, players);
      return m > 1 ? Math.round(a / m) : a;
    }
    const fmt = c => c === null || c === undefined ? "—" : (c < 100 ? `${c}%` : `1:${c.toLocaleString()}`);
const runsFor = (chance, conf) => !chance || chance < 100 ? null : Math.ceil(Math.log(1-conf)/Math.log(1-1/chance));
// hours for X% confidence given chance + kills_per_hour
const hoursFor = (chance, conf, kph) => {
  if (!chance || chance < 100 || !kph) return null;
  const runs = runsFor(chance, conf);
  return runs / kph;
};
const fmtHours = h => {
  if (h === null || h === undefined || !isFinite(h)) return "—";
  if (h < 1) return `${Math.round(h*60)}min`;
  if (h < 24) return `${h.toFixed(1)}h`;
  return `${(h/24).toFixed(1)}d`;
};
