  // ── v309: tooltip-style example items from Konyo's screenshots (the crafted orange is the priority) ──
  "Dire Hand (Crafted Blood Gloves)": { stats:["+20% Increased Attack Speed","3% Life Stolen Per Hit","+10% Chance of Crushing Blow","+20 to Life","Fire / Cold / Poison Resist +30%"], rarity:'crafted', base:'Vampirebone Gloves', req:57, cat:'Crafted', val:'high', beats:'most unique gloves (melee)', desc:"The crafted-glove jackpot — a Perfect-Ruby <b>Blood</b> craft on elite Vampirebone Gloves (“Dire Hand” is the auto-generated crafted name). <b>Life-leech + life are guaranteed</b>; a godly roll adds <b>20% IAS + 10% Crushing Blow + triple resists</b>. That combo (IAS + leech + Crushing Blow + res) out-classes most unique gloves for a melee / zealer build — exactly the kind of crafted <b>orange</b> item to chase." },
  "Chromatic Amulet (+30 all res, magic)": { stats:["All Resistances +30"], rarity:'magic', base:'Amulet', req:41, cat:'Rare jewelry', val:'low–mid', desc:"A clean magic amulet with the <b>Chromatic</b> prefix maxed — <b>All Resistances +30</b> in one neck slot. The cheapest way to plug a big resist hole; a budget stand-in until you find a +skills / FCR rare or Mara's." },
  "Jeweler's Dusk Shroud of Stability (4os caster armor)": { stats:["Socketed (4) — “Jeweler's” prefix","“of Stability” — +Enhanced Defense","— filled with godly rare jewels →","+45% Increased Attack Speed","+24% Faster Hit Recovery","+9 to Dexterity"], rarity:'magic', base:'Dusk Shroud', req:58, cat:'Runeword bases', val:'mid–high', desc:"A magic <b>Jeweler's</b> (max-socket) Dusk Shroud — the lightest caster body — rolled with <b>4 sockets + “of Stability” ED</b>, then filled with godly rare jewels for IAS / FHR / +stats. A 4-socket magic base like this is a premium runeword shell OR a jewel-stuffed end-game armor in its own right." },
  "Jeweler's Diadem of Speed (3os circlet)": { stats:["Socketed (3) — “Jeweler's” prefix","“of Speed” — +30% Faster Run/Walk","— filled with godly rare jewels →","+45% Increased Attack Speed","+120% Enhanced Damage"], rarity:'magic', base:'Diadem', req:64, cat:'Runeword bases', val:'mid–high', desc:"A magic <b>Jeweler's</b> Diadem (the top circlet base) with <b>3 sockets + “of Speed” FRW</b>, jewel-stuffed for IAS + ED. Circlets keep their magic affixes AND carry 3 jewels — a godly socketed Diadem rivals unique helms for a melee build." },
  "Godly Leech Ring (rare)": { stats:["+9 to Minimum Damage","+120 to Attack Rating","8% Life Stolen Per Hit","+20 to Strength","Fire / Cold / Lightning / Poison Resist +"], rarity:'rare', base:'Ring', req:66, cat:'Rare jewelry', val:'mid', beats:'most unique rings (short of Raven Frost / SoJ)', desc:"The melee all-rounder rare ring — <b>life-leech + big Attack Rating + min damage + 20 Strength + multi-resist</b>. A clean roll like this beats most unique rings short of Raven Frost / SoJ for a physical build." },
  "Superior Phase Blade (4× Shael, max-IAS base)": { stats:["+110% Increased Attack Speed (4× Shael)","+15% Enhanced Damage (superior)","+3 to Attack Rating","All Resistances +30 (res jewels)","Indestructible · Socketed"], rarity:'basic', base:'Phase Blade', req:54, cat:'Runeword bases', val:'mid', desc:"A budget max-attack-speed weapon — a <b>Superior</b> (extra ED) Phase Blade socketed with <b>4 Shael runes</b> for ~110% IAS, indestructible and very low strength. The poor-man's Grief base: hit the top IAS breakpoint cheaply, then add res / ED jewels in the spare sockets." },

