// v425 — full item enumerator for the vault-manager simulation & nightly audit: every grail unique/set/base
// (ITEMS), every off-grail reference item (EXTRA_ITEMS), every set PIECE, and every runeword. Lazy (called
// after load) + deduped. This is the canonical "all 1200+ items" list the audit walks.
window.__allItemNames = function(){
  var out = [];
  try { (typeof ITEMS!=='undefined'?ITEMS:[]).forEach(function(i){ if (i && i.n) out.push(i.n); }); } catch(e){}
  try { Object.keys(EXTRA_ITEMS||{}).forEach(function(n){ out.push(n); }); } catch(e){}
  try { (typeof __allSets==='function'?__allSets():[]).forEach(function(s){ (s.pieces||[]).forEach(function(p){ if (p) out.push(typeof __pieceBase==='function'?__pieceBase(p):p); }); }); } catch(e){}
  try { Object.keys(typeof RUNEWORD_TIP!=='undefined'?RUNEWORD_TIP:{}).forEach(function(n){ out.push(n); }); } catch(e){}
  try { Object.keys(typeof BASE_CLASS!=='undefined'?BASE_CLASS:{}).forEach(function(n){ out.push(n); }); } catch(e){}   // v430 — the 498 game-data bases (were excluded → audits only saw 799 of ~1297)
  var seen = Object.create(null), uniq = [];
  out.forEach(function(n){ if (n && !seen[n]){ seen[n] = 1; uniq.push(n); } });
  return uniq;
};
