function getRarityClass(c) {
  if (!c || c < 100) return "rare-5";
  if (c >= 50000) return "rare-1";
  if (c >= 10000) return "rare-2";
  if (c >= 2000) return "rare-3";
  if (c >= 500) return "rare-4";
  return "rare-5";
}
function tcPill(tc) {
  if (tc === 87) return '<span class="pill pill-tc87">TC87</span>';
  if (tc === 84 || tc === 85) return '<span class="pill pill-tc85">TC'+tc+'</span>';
  if (tc === 78 || tc === 75 || tc === 73 || tc === 72) return '<span class="pill pill-tc78">TC'+tc+'</span>';
  if (tc === 60) return '<span class="pill pill-tc60">TC60</span>';
  return tc === 0 ? '<span class="pill" style="background:rgba(255,0,212,.18);color:var(--terror)">special</span>' : '<span class="pill pill-tc60">TC'+tc+'</span>';
}
function tierPill(tier) {
  if (tier === "uber") return '<span class="pill pill-uber">uber</span>';
  if (tier === "grail") return '<span class="pill pill-grail">grail</span>';
  return '';
}
function deriveBlocked(item, diff) {
  if (item.qlvl > 0 && item.qlvl > diff.mlvl) return {type:"mlvl",reason:`qlvl ${item.qlvl} > ${diff.label} mlvl ${diff.mlvl}`};
  if (item.tc > 0 && item.tc > diff.tcMax) return {type:"tc",reason:`TC ${item.tc} > ${diff.label} TC ${diff.tcMax}`};
  return null;
}

// In-game item QUALITY (for D2R-accurate name colors). Distinct from item.tier,
// which is the bible's grail-rarity bucket (common/high/grail/uber/set/special).
// Keyed off tier (authoritative) NOT name keywords — names like "Carin Shard",
// "Blackhand Key", "Nokozan Relic", "Annihilus", "Tyrael's Might" are UNIQUES
// (gold), only the tier=special event tokens/shards (Keys, Worldstone Shard) are
// the orange "material" group. set → green, rune → orange, else unique → gold.
function itemQuality(item) {
  const n = item.n || "";
  if (item.tier === "special") return "material";
  if (item.tier === "set" || /\(set\)|\(set piece\)|\bset\b/i.test(n)) return "set";
  if (/\brune\b/i.test(n)) return "rune";
  return "unique";
}

// Build inline SVG sparkline showing cumulative probability over hours
function sparkline(chance, kph, hoursMax) {
  if (!chance || !kph) return '';
  const W = 80, H = 18, pts = 24;
  const stepHr = hoursMax / pts;
  let path = '';
  for (let i = 0; i <= pts; i++) {
    const hr = i * stepHr;
    const kills = hr * kph;
    const p = kills > 0 ? 1 - Math.pow(1 - 1/chance, kills) : 0;
    const x = (i / pts) * W;
    const y = H - (p * H);
    path += (i === 0 ? 'M' : 'L') + x.toFixed(1) + ',' + y.toFixed(1) + ' ';
  }
  return `<svg class="sparkline" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">
    <line x1="0" y1="${H/2}" x2="${W}" y2="${H/2}" stroke="#3a2f1e" stroke-width="0.5" stroke-dasharray="2,2"/>
    <path d="${path}" stroke="#66ff88" stroke-width="1.5" fill="none"/>
  </svg>`;
}

function renderGrailProgress() {
  const allGrails = ITEMS.filter(i => i.tier === "grail" || i.tier === "uber");
  const total = allGrails.length;
  const have = allGrails.filter(i => _gFound(i.n)).length;
  const pct = total ? have / total : 0;
  const pctNum = Math.round(pct * 100);
  const circleC = 2 * Math.PI * 26;
  const offset = circleC * (1 - pct);
  $("gp-circle-fill").setAttribute("stroke-dashoffset", offset);
  $("gp-circle-text").textContent = pctNum + "%";
  $("gp-bar-fill").style.width = pctNum + "%";
  const remaining = total - have;
  let msg = "";
  if (have === 0) msg = `Mark grail items as ✓ owned to track your Holy Grail collection. <strong>${total}</strong> grails tracked.`;
  else if (remaining === 0) msg = `<strong style="color:var(--best)">🏆 GRAIL COMPLETE!</strong> You collected all ${total} tracked items. Send a screenshot.`;
  else msg = `<strong>${have} / ${total}</strong> grails owned · ${remaining} to go · ⭐ ${wishlist.size} starred for priority. See the Hero card above for next pickup ideas.`;
  $("gp-detail").innerHTML = msg;
  renderGrailTierBreakdown(allGrails);
}
// Split the grail circle into its two honest sub-pools — uber/elite uniques vs the broad
// grail-unique set — counting only the user's own ✓-owned items per item.tier. Pure
// aggregation of existing data; no new odds or categories are invented.
function renderGrailTierBreakdown(allGrails){
  const el = $("gp-tier-breakdown");
  if (!el) return;
  const rows = [
    {lab:"🔱 Uber / elite uniques", cls:"uber", pool:allGrails.filter(i => i.tier === "uber")},
    {lab:"💍 Grail uniques", cls:"grail", pool:allGrails.filter(i => i.tier === "grail")},
  ].filter(r => r.pool.length > 0);
  el.innerHTML = rows.map(r => {
    const total = r.pool.length;
    const have = r.pool.filter(i => _gFound(i.n)).length;
    const p = total ? Math.round(have / total * 100) : 0;
    return `<div class="gp-tier"><div class="gp-tier-head"><span class="gp-tier-lab">${r.lab}</span><span class="gp-tier-num">${have} / ${total}</span></div><div class="gp-tier-bar"><div class="gp-tier-fill ${r.cls}" style="width:${p}%"></div></div></div>`;
  }).join("");
}

