let activeBossId = null;

window.setActiveBoss = function(bossId, focusDiff, opts) {
  // v42 Bug H (CC find): support intent disambiguation. Default 'toggle' is correct
  // for boss-chip re-clicks (close-on-second-click). But entry points like
  // openBossDetail, TZ zone cards, gic-source-cell, Cmd+click source chip,
  // URL hash routes — all want 'open' semantics (already-active = no-op, not close).
  const intent = opts?.intent || 'toggle';
  if (activeBossId === bossId) {
    if (intent === 'toggle') { clearActiveBoss(); return; }
    // intent === 'open' — re-reveal panel in place without closing (v46: block:'nearest', no teleport)
    __alignCard('#boss-detail-panel');
    return;
  }
  activeBossId = bossId;
  // v33: re-render hero picks to be boss-specific
  if (typeof renderHero === 'function') renderHero();
  renderBossDetailCard(bossId, focusDiff);
  // Update chip active state
  document.querySelectorAll('.boss-chip').forEach(c => {
    c.dataset.active = (c.dataset.bossId === bossId) ? 'true' : 'false';
  });
  // Route-audit contract: ensure #boss-detail-overlay is unhidden
  document.getElementById('boss-detail-overlay')?.classList.remove('hidden');
  // v46 unify: expand the detail panel IN PLACE directly under the clicked boss
  // card (like the TZ-zone dropdown) instead of teleporting to a fixed panel at the
  // top of the grid. Same #boss-detail-overlay element + content (tests intact).
  const _ov = document.getElementById('boss-detail-overlay');
  const _card = document.getElementById(bossId);
  if (_ov && _card) _card.insertAdjacentElement('afterend', _ov);
  __alignCard('#boss-detail-panel');
};

window.clearActiveBoss = function(opts) {
  const wasActive = activeBossId;
  activeBossId = null;
  // v33: re-render hero picks to global mode
  if (typeof renderHero === 'function') renderHero();
  const panel = $("boss-detail-panel");
  if (panel) { panel.classList.remove('show'); panel.innerHTML = ''; }
  // Route-audit contract: hide the overlay
  document.getElementById('boss-detail-overlay')?.classList.add('hidden');
  document.querySelectorAll('.boss-chip').forEach(c => c.dataset.active = 'false');
  // v42 UX route-back: smoothly return user to the chip bar so they can pick another boss.
  // BUT only when a boss was actually open AND the caller hasn't asked us to stay put.
  // (openItemDetail calls clearActiveBoss to dismiss any boss overlay, then scrolls to its
  // own panel — without noScroll this scroll-to-nav fired 10ms later and clobbered it,
  // leaving the golden item card ~3000px below the fold = a dead-feeling click.)
  // v46 unify: the detail panel now expands inline under its card, so closing simply
  // collapses it in place — no teleport back to the nav bar.
  void wasActive;
};

window.setMFPreset = function(value) {
  const slider = document.getElementById('mf');
  if (!slider) return;
  slider.value = value;
  slider.dispatchEvent(new Event('input', {bubbles:true}));
  updateMFPresetActive(value);
  // Click pulse feedback
  document.querySelectorAll('.mf-preset-chip[data-mf="'+value+'"]').forEach(c => {
    c.classList.add('clicked');
    setTimeout(() => c.classList.remove('clicked'), 200);
  });
};

function updateMFPresetActive(value) {
  document.querySelectorAll('.mf-preset-chip').forEach(c => {
    c.dataset.active = (parseInt(c.dataset.mf) === parseInt(value)) ? 'true' : 'false';
  });
  const numInput = document.getElementById('mfNumberInput');
  if (numInput && document.activeElement !== numInput) numInput.value = value;
}

// Sync MF number input → slider
document.addEventListener('DOMContentLoaded', () => {
  const numInput = document.getElementById('mfNumberInput');
  const slider = document.getElementById('mf');
  if (numInput && slider) {
    numInput.addEventListener('input', e => {
      let v = parseInt(e.target.value) || 0;
      v = Math.max(0, Math.min(1000, v));
      slider.value = v;
      slider.dispatchEvent(new Event('input', {bubbles:true}));
      updateMFPresetActive(v);
    });
    numInput.addEventListener('blur', e => {
      let v = parseInt(e.target.value) || 0;
      v = Math.max(0, Math.min(1000, v));
      e.target.value = v;
    });
    // Initialize from current slider value
    setTimeout(() => updateMFPresetActive(slider.value), 100);
    // Hook slider changes to update presets active state
    slider.addEventListener('input', () => updateMFPresetActive(slider.value));
  }
});

