const TZ_BOSS_MAP = [
  // Only zones where a boss from the 11-boss roster actually spawns / is the headline farm
  // get a click-through. Super-unique / density-only zones (Crystalline Passage, Tristram,
  // Arcane Sanctuary, Flayer Dungeon, Spider Forest, Burial Grounds) intentionally return no
  // match: their value is super-uniques NOT in the roster, so a boss-detail route would mislead.
  // (Render template makes a no-match card non-clickable: cursor:default + honest title.)
  {re:/catacombs/i, boss:'andariel'},                       // Andariel — Catacombs L4
  {re:/halls of (anguish|pain|vaught)|nihl/i, boss:'nihl'}, // Nihlathak — Halls of Vaught
  {re:/worldstone keep|wsk/i, boss:'baal'},                 // Baal — Throne via WSK
  {re:/river of flame|chaos sanctuary/i, boss:'diablo'},    // Diablo — Chaos Sanctuary
  {re:/^the pit|pit$|tamoe highland/i, boss:'pit'},         // The Pit
  {re:/durance|mephisto/i, boss:'mephisto'},                // Mephisto — Durance of Hate
  {re:/forgotten tower|countess/i, boss:'countess'},        // Countess — Forgotten Tower
  {re:/travincal|kurast/i, boss:'travincal'},               // Council — Travincal
  {re:/moo moo|cow level|hell bovines/i, boss:'cows'},      // Hell Bovines — Cow Level
  {re:/pindle|nihlathak.s temple|anya/i, boss:'pindle'},    // Pindleskin — Nihlathak's Temple
  {re:/arcane sanctuary|summoner/i, boss:'summoner'},       // The Summoner — Arcane Sanctuary (event: Key of Hate)
  {re:/duriel|tomb/i, boss:'duriel'},                       // Duriel — Tal Rasha's Tomb
];
function tzZoneBoss(zoneName){
  if (!zoneName) return null;
  for (const m of TZ_BOSS_MAP) if (m.re.test(zoneName)) return m.boss;
  return null;
}

function renderSpecialDrops() {
  const el = $("special-drops-grid");
  if (!el || typeof SPECIAL_DROPS === 'undefined') return;
  // Unified art: route the category emblem + every item through artOr so any logo
  // registered once in D2IO_ART lights up here automatically (single source of truth).
  // Aggregate categories with no graphic of their own borrow a representative item's art.
  const CAT_ART = {essence:'Essence of Hatred', token:'Token of Absolution', key:'Key of Terror',
    organ:"Diablo's Horn", uberCharm:'Hellfire Torch', colossalJewel:'Colossal Ancient Jewels',
    colossalStatue:'Colossal Ancient Statue', sunder:'Bone Break'};
  // v167 — category titles route to their aggregate hub/golden card when one exists.
  const CAT_ROUTE = {sunder:'Sunder Charms', colossalJewel:'Colossal Ancient Jewels',
    colossalStatue:'Colossal Ancient Statue', token:'Token of Absolution', cowAccess:"Wirt's Leg"};
  const _art = (typeof artOr === 'function');
  el.innerHTML = Object.entries(SPECIAL_DROPS).map(([key, cat]) => {
    const itemsHtml = cat.items.map(it => {
      const safe = it.n.replace(/'/g, "\\'");
      const has = (typeof findMaterial !== 'function') || !!findMaterial(it.n);
      const inner = `${_art ? artOr(it.n, '', 'sm') : ''}<span>${it.n}</span>`;
      const nameHtml = has
        ? `<span class="sd-item-id" role="button" tabindex="0" onclick="event.stopPropagation();window.openDrop('${safe}')" title="open ${it.n} detail card">${inner}</span>`
        : `<span class="sd-item-id">${inner}</span>`;
      return `<div class="sd-item">
      <div class="sd-item-name">${nameHtml}<span class="sd-item-rate">${it.rate}</span></div>
      <div class="sd-item-from">${it.from.join(' OR ')}</div>
      ${it.note ? `<div class="sd-item-note">${it.note}</div>` : ''}
    </div>`;
    }).join('');
    const catIcon = _art ? artOr(CAT_ART[key] || cat.label, cat.icon, 'md') : cat.icon;
    const catRoute = CAT_ROUTE[key] || null;
    return `<div class="sd-cat">
      <div class="sd-cat-head">
        <span class="sd-cat-icon">${catIcon}</span>
        <div class="sd-cat-label${catRoute?' zd-item-click':''}"${catRoute?` role="button" tabindex="0" style="cursor:pointer" title="open ${catRoute} card" onclick="event.stopPropagation();window.openDrop('${_esc1(catRoute)}')"`:''}>${cat.label}</div>
        <div class="sd-cat-count">${cat.items.length} item${cat.items.length===1?'':'s'}</div>
      </div>
      <div class="sd-cat-blurb">${cat.blurb}</div>
      <div class="sd-items">${itemsHtml}</div>
      ${cat.recipe ? `<div class="sd-recipe">📐 <strong>recipe:</strong> ${cat.recipe}</div>` : ''}
      ${cat.important ? `<div class="sd-important">⚠ ${cat.important}</div>` : ''}
    </div>`;
  }).join('');
}

let aidCardOrigin = null; // {tab:'bosses', bossId:'mephisto'} or null

window.navigateToItem = function(itemName, originContext) {
  aidCardOrigin = originContext || null;
  clearActiveBoss();
  selectedItem = itemName;
  // v42 UX: also set as the active item so the persistent top bar shows context
  // (drop-row clicks in boss detail were leaving user on calc tab with no top-bar indicator)
  if (typeof setActiveItem === 'function') setActiveItem(itemName);
  switchTab('calc');
  renderDetail();
  // Smooth scroll to top of aid-card with offset for sticky elements
  __alignCard('#item-detail .aid-card');
};

window.goBackFromAid = function() {
  if (!aidCardOrigin) return;
  // v42 fix (Bug E — CC find): capture into a local BEFORE nulling. The previous
  // version nulled aidCardOrigin synchronously, then the 60ms setTimeout closure
  // tried to read .bossId from null → silent TypeError → setActiveBoss never ran.
  // User saw bosses tab activate with no boss expanded.
  const origin = aidCardOrigin;
  aidCardOrigin = null;
  if (origin.tab === 'bosses' && origin.bossId) {
    switchTab('bosses');
    setTimeout(() => setActiveBoss(origin.bossId, undefined, {intent:'open'}), 60);
  } else if (origin.tab) {
    switchTab(origin.tab);
  }
};

function tagTzZonesWithBossId() {
  document.querySelectorAll('.tz-zone-card').forEach(card => {
    const nameEl = card.querySelector('.tz-zone-name');
    if (!nameEl) return;
    const bossId = (typeof tzZoneBoss === 'function') ? tzZoneBoss(nameEl.textContent.trim()) : null;
    if (bossId) {
      // a roster boss genuinely spawns here → clickable, honest affordance
      card.setAttribute('data-boss-id', bossId);
      const boss = (typeof BOSSES !== 'undefined') ? BOSSES.find(b => b.id === bossId) : null;
      card.style.cursor = 'pointer';
      card.title = 'click → open ' + (boss ? boss.name : bossId) + ' boss detail';
    } else {
      // v44 honest-affordance: this zone's value is its OWN super-uniques (Frozenstein,
      // Griswold, the Summoner, etc.) which have no boss card — so it must NOT look
      // v45: it DOES toggle an inline drop-detail box, so it is honestly clickable. Empty data-boss-id keeps the route guard a no-op.
      card.setAttribute('data-boss-id', '');
      card.style.cursor = 'pointer';
      card.title = 'click → expand drop detail';
    }
  });
}
const EXCLUSIVE_DROPS = {
  countess:{item:'Key of Terror', note:'One of the 3 Pandemonium keys — drops ONLY from the Countess (Hell). Your gateway to Uber Tristram.'},
  summoner:{item:'Key of Hate', note:'One of the 3 Pandemonium keys — drops ONLY from the Summoner (Hell). Your gateway to Uber Tristram.'},
  nihl:{item:'Key of Destruction', note:'One of the 3 Pandemonium keys — drops ONLY from Nihlathak (Hell). Your gateway to Uber Tristram.'},
  dclone:{item:'Annihilus', note:'The ONLY source of the Annihilus charm — +1 all skills, +10–20 all attributes, +10–20 all resists, +5–10% experience. Flat drop, every kill.'}
};
// Drop-scaling classes — single source of truth, shared by renderBossNav (chips)
// and renderBossCards (card sections) so both mirror the same grouping.
const PLAYER_TIERS = [
  {name:'ACT BOSSES',      cls:'pt-vault',  members:['andariel','duriel'],            tag:'The early-act bosses — Andariel (Act 1) and Duriel (Act 2). Quick, guaranteed full drops on every kill.'},
  {name:'THE PRIME EVILS', cls:'pt-prime',  members:['mephisto','diablo','baal'],     tag:'The three brothers — Mephisto (Act 3), Diablo (Act 4), Baal (Act 5). The deepest endgame treasure pools.'},
  {name:'SUPER-UNIQUES',   cls:'pt-fisted', members:['travincal','pindle'],           tag:'Elite farm targets — the Travincal council (high-rune king) and Pindleskin (fastest run in the game).'},
  {name:'HIGH-DENSITY ZONES', cls:'pt-swarm', members:['pit','cows'],                 tag:'Not bosses — packed lvl-85 zones. The Pit and the Cow Level rain loot, and more players means more drops.'},
  {name:'PANDEMONIUM KEYS', cls:'pt-keys',  members:['countess','summoner','nihl'],   tag:'The three Uber Tristram keys — Terror, Hate, Destruction. Cube one of each &rarr; a mini-uber portal; collect all three organs &rarr; the Uber Tristram red portal. (See the UBER bosses below.)'},
];
function renderBossNav() {
  const __bossOf = {};
  BOSSES.forEach(b => { __bossOf[b.id] = b; });
  const chip = b => `<a href="javascript:void(0)" class="boss-chip" data-boss-id="${b.id}" onclick="setActiveBoss('${b.id}')">` + artOr(b.name, '<span class="emoji">' + b.emoji + '</span>', 'sm') + b.name + `</a>`;
  const used = {};
  const groups = PLAYER_TIERS.map(g => {
    const chips = g.members.filter(id => __bossOf[id]).map(id => { used[id] = 1; return chip(__bossOf[id]); }).join("");
    if (!chips) return "";
    // live per-tier drop-quantity multiplier at current /players — mirrors the card-section headers
    const ms = g.members.filter(id => __bossOf[id]).map(id => playerMult(id, 'hell', players));
    let xtxt = '×1.00';
    if (ms.length) {
      const lo = Math.min(...ms), hi = Math.max(...ms);
      xtxt = (Math.abs(lo - hi) < 0.005) ? ('×' + hi.toFixed(2)) : ('×' + lo.toFixed(2) + '–' + hi.toFixed(2));
    }
    return `<div class="boss-nav-group ${g.cls}"><span class="boss-nav-group-label">${g.name}<span class="boss-nav-group-mult" title="drop-quantity multiplier at /players ${players}"> · ${xtxt}</span></span><div class="boss-nav-group-chips">${chips}</div></div>`;
  }).join("");
  const leftover = BOSSES.filter(b => !used[b.id]).map(chip).join("");
  const leftoverHtml = leftover ? `<div class="boss-nav-group pt-event"><span class="boss-nav-group-label">WORLD EVENT<span class="boss-nav-group-mult" title="event-only drops — not /players scaled"> · event</span></span><div class="boss-nav-group-chips">${leftover}</div></div>` : "";
  $("boss-nav").innerHTML = groups + leftoverHtml;
}

function bossTopDropsHtml(boss, limit){
  const _grailPool = boss.dropTable.filter(d => d.tier === "grail" || d.tier === "uber");
  const _topDrops = [];
  _grailPool.forEach(d => {
    let best = null, bestKey = null;
    ["norm","normTz","nm","nmTz","hell","hellTz"].forEach(k => {
      const adj = effChance(d[k], boss.id, k);
      if (adj !== null && (best === null || adj < best)) { best = adj; bestKey = k; }
    });
    if (best !== null) _topDrops.push({ d, best, bestKey });
  });
  _topDrops.sort((a, b) => b.best - a.best); // rarest (highest 1:N) first
  const _topN = _topDrops.slice(0, limit || 20);
  return _topN.length ? `
      <div class="top-drops">
        <h3 class="top-drops-title">&#127942; Holy Grail &mdash; Top Drops <span class="top-drops-sub">rarest first &middot; top ${_topN.length} of ${_grailPool.length} grail/uber droppable here</span></h3>
        <ol class="top-drops-list">
          ${_topN.map((t, i) => {
            const d = t.d;
            const kphMult = (t.bestKey === "norm" || t.bestKey === "normTz") ? 1.2 : (t.bestKey === "nm" || t.bestKey === "nmTz") ? 1.1 : 1.0;
            const hrs = hoursFor(t.best, 0.5, boss.kph * kphMult);
            const diffLbl = t.bestKey.replace("Tz", " TZ").toUpperCase();
            const ver = (d.v || []).includes(t.bestKey) ? ' <span class="top-drop-verified" title="silospen-verified anchor">&#128274;</span>' : '';
            const sym = d.tier === "uber" ? "&#9889;" : "&#9733;";
            const esc = d.n.replace(/'/g, "\\'");
            return `<li class="top-drop-row ${d.tier === 'uber' ? 'top-drop-uber' : ''}" onclick="navigateToItem('${esc}')" title="open ${d.n} in the calculator">
              <span class="top-drop-rank">#${i + 1}</span>
              <span class="top-drop-name${d.tier==='uber'?'':' q-'+(_artRarity(d.n)||itemQuality(d))}" data-arttip="${_d2artEsc(d.n)}">${sym} ${nameLogo(d.n)}${d.n}${ver}</span>
              <span class="top-drop-odds">${fmt(t.best)} <span class="top-drop-diff">${diffLbl}</span></span>
              <span class="top-drop-hrs">${hrs !== null ? fmtHours(hrs) : "&mdash;"}</span>
            </li>`;
          }).join("")}
        </ol>
      </div>` : '';
}
window.bossTopDropsHtml = bossTopDropsHtml;

// v341.56 — PERF: the full per-boss drop table (~300 rows × 14 bosses ≈ 50k DOM nodes) is now built
// LAZILY, only when its "Show all drops" <details> is opened. Cuts the Bosses tab from ~54k nodes to
// ~6k on load. Open-state is preserved across MF/players/filter/sort re-renders.
window._openDropBosses = window._openDropBosses || new Set();
function _bossFilteredDrops(boss){
  var filter = bossFilters[boss.id] || "all";
  var dropTable = boss.dropTable.slice();
  if (filter === "grail") dropTable = dropTable.filter(function(d){ return d.tier === "grail" || d.tier === "uber"; });
  if (filter === "achievable") dropTable = dropTable.filter(function(d){ return ["norm","normTz","nm","nmTz","hell","hellTz"].some(function(k){ return d[k] !== null; }); });
  if (filter === "starred") dropTable = dropTable.filter(function(d){ return wishlist.has(d.n); });
  if (filter === "hideowned") dropTable = dropTable.filter(function(d){ return !_gFound(d.n); });
  var sortKey = bossSorts[boss.id];
  if (sortKey) {
    var sp = sortKey.split(":"), col = sp[0], dir = sp[1];
    dropTable.sort(function(a,b){ var av = a[col] || Infinity, bv = b[col] || Infinity; return dir === "asc" ? av - bv : bv - av; });
  }
  return dropTable;
}
window._bossFilteredDrops = _bossFilteredDrops;
function _bossDropRowsHtml(bossId){
  const boss = (typeof BOSSES !== 'undefined') ? BOSSES.find(b => b.id === bossId) : null;
  if (!boss) return '';
  const filter = bossFilters[boss.id] || "all";
  const dropTable = _bossFilteredDrops(boss);
  const rows = dropTable.map(d => {
    const diffKeys = ["norm","normTz","nm","nmTz","hell","hellTz"];
    const verifiedDiffs = d.v || [];
    const adjusted = diffKeys.map(k => effChance(d[k], boss.id, k));
    const valid = adjusted.filter(v => v !== null && v >= 100);
    const minChance = valid.length ? Math.min(...valid) : null;
    const cells = diffKeys.map((k,i) => {
      const val = adjusted[i];
      const diff = boss.diffs[i];
      const isVerified = verifiedDiffs.includes(k);
      const dcol = {norm:'dcol-norm',normTz:'dcol-normtz',nm:'dcol-nm',nmTz:'dcol-nmtz'}[k] || '';
      if (val !== null && val !== undefined) {
        if (val < 100) return `<td class="diff-col ${dcol} rare-5">${fmt(val)}</td>`;
        const cls = getRarityClass(val);
        const bestCls = (val === minChance) ? 'best-cell' : '';
        const verCls = isVerified ? 'verified-cell' : '';
        const verTitle = isVerified ? ' title="🔒 silospen-verified anchor"' : '';
        return `<td class="diff-col ${dcol} ${cls} ${bestCls} ${verCls}"${verTitle}>${fmt(val)}</td>`;
      }
      const blocked = deriveBlocked(d, diff);
      if (blocked) {
        const cls = blocked.type === "mlvl" ? "blocked-mlvl" : "blocked-tc";
        const short = blocked.reason.length > 22 ? blocked.reason.substring(0,22)+'…' : blocked.reason;
        return `<td class="diff-col ${dcol} ${cls}" title="${blocked.reason}">${short}</td>`;
      }
      return `<td class="diff-col ${dcol} cannot">—</td>`;
    }).join("");
    const itemNameClass = "q-" + ((typeof _artRarity === 'function' && _artRarity(d.n)) || itemQuality(d));
    const starred = wishlist.has(d.n);
    const isOwned = _gFound(d.n);
    const wishCls = starred ? 'wishlist-row' : '';
    const ownedCls = isOwned ? 'owned-row' : '';
    const escName = d.n.replace(/'/g,"\\'");
    return `<tr class="clickable ${wishCls} ${ownedCls}" data-item="${d.n}">
        <td class="item-name ${itemNameClass}" data-arttip="${_d2artEsc(d.n)}">
          <span class="star-btn ${starred?'starred':''}" data-star="${d.n}" onclick="event.stopPropagation();toggleStar('${escName}')">${starred?'★':'☆'}</span>
          ${nameLogo(d.n)}${d.n} ${tierPill(d.tier)}
          <button class="owned-btn ${isOwned?'owned':''}" onclick="event.stopPropagation();toggleOwned('${escName}')" title="${isOwned?'mark as not owned':'mark as owned (will strikethrough)'}">${isOwned?'✓':'☐'}</button>
        </td>
        <td class="tc">${tcPill(d.tc)} ${d.qlvl?'q'+d.qlvl:''}</td>
        ${cells}
      </tr>`;
  }).join("");
  return rows || `<tr><td colspan="8" class="drops-empty-cell" style="text-align:center;padding:18px;opacity:.72;color:var(--text)">No items match the <strong>${filter === 'grail' ? 'grail / uber' : filter === 'achievable' ? 'achievable' : filter === 'starred' ? '⭐ wishlist' : filter === 'hideowned' ? 'hide ✓ owned' : filter}</strong> filter &mdash; <button class="boss-filter-pill" style="display:inline-block;margin-left:6px" onclick="setBossFilter('${bossId}','all')">show all ${boss.dropTable.length}</button></td></tr>`;
}
window._bossDropRowsHtml = _bossDropRowsHtml;
// build a boss's drop <tbody> if it hasn't been filled yet (on <details> open + post-re-render for open ones)
function _ensureBossRows(bossId){
  var tb = document.querySelector('#boss-cards tbody[data-drops-for="' + bossId + '"]');
  if (tb && tb.getAttribute('data-filled') !== '1'){ tb.innerHTML = _bossDropRowsHtml(bossId); tb.setAttribute('data-filled','1'); }
}
window._ensureBossRows = _ensureBossRows;
// build (and optionally open) EVERY boss's drop table at once. Powers a future "expand all" and lets
// tests that assert against the full drop tables opt back into eager rows after the v341.56 lazy split.
function _buildAllBossDrops(open){
  if (typeof BOSSES === 'undefined') return 0;
  var n = 0;
  BOSSES.forEach(function(b){
    if (open){ var d = document.querySelector('#' + b.id + ' .all-drops-details'); if (d){ d.open = true; window._openDropBosses.add(b.id); } }
    _ensureBossRows(b.id); n++;
  });
  return n;
}
window._buildAllBossDrops = _buildAllBossDrops;

function renderBossCards() {
  var __cardOf = {};
  BOSSES.forEach(boss => {
    __cardOf[boss.id] = (() => {
    const tClasses = ["t-norm","t-norm-tz","t-nm","t-nm-tz","t-hell","t-hell-tz"];
    const diffsHtml = boss.diffs.map((d,i) => `<div class="diff-cell ${tClasses[i]}" title="${d.label}: mlvl ${d.mlvl}, max TC ${d.tcMax}">
      <div class="diff-label ${d.terror?'terror':''}">${d.label}</div>
      <div class="diff-mlvl">mlvl ${d.mlvl}</div>
      <div class="diff-tc-line">${d.tc}</div>
    </div>`).join("");

    const filter = bossFilters[boss.id] || "all";
    const dropTable = _bossFilteredDrops(boss);   // v341.56 — filter/sort extracted; rows built lazily on <details> open
    const sortKey = bossSorts[boss.id];

    // Quick takeaway with hours
    let quickTake = '';
    let bestRow = null, bestChance = Infinity, bestDiffKey = null;
    boss.dropTable.forEach(d => {
      if ((d.tier !== "grail" && d.tier !== "uber") || _gFound(d.n)) return;
      ["hellTz","hell","nmTz","nm","normTz","norm"].forEach(k => {
        if (d[k]) {
          const adj = effChance(d[k], boss.id, k);
          if (adj < bestChance) { bestChance = adj; bestRow = d; bestDiffKey = k; }
        }
      });
    });
    if (bestRow) {
      const r50 = runsFor(bestChance, 0.5);
      const kphMult = (bestDiffKey === "norm" || bestDiffKey === "normTz") ? 1.2 : (bestDiffKey === "nm" || bestDiffKey === "nmTz") ? 1.1 : 1.0;
      const hrs = hoursFor(bestChance, 0.5, boss.kph * kphMult);
      const diffLabel = bestDiffKey.replace("Tz", " TZ").toUpperCase();
      // v26: null-guard — runsFor + hoursFor can return null when chance is unreachable/blocked
      if (r50 !== null && hrs !== null) {
        quickTake = `<div class="quick-take">⚡ <strong>Quick take @ ${mf}% MF:</strong> Best grail = <span class="item-link"${_qStyle(bestRow.n,'unique')}>${bestRow.n}</span> at <strong>${fmt(bestChance)}</strong> (${diffLabel}) · <strong>${r50.toLocaleString()} runs</strong> ≈ <strong style="color:var(--terror)">${fmtHours(hrs)}</strong> for 50% drop at ${Math.round(boss.kph * kphMult)}/hr</div>`;
      }
    }

    // === Holy Grail — Top Drops: grail/uber items droppable here, ranked rarest-first ===
    // best achievable 1:N per item at this boss, sorted descending so the rarest / most
    // prestigious chase items lead; the full common-item tail lives in the dropdown below.
    const topDropsHtml = bossTopDropsHtml(boss, 20);

    const sortCol = sortKey ? sortKey.split(":")[0] : null;
    const sortDir = sortKey ? sortKey.split(":")[1] : null;
    const hdrCls = k => sortCol !== k ? "sortable" : "sortable sort-" + sortDir;

    return `<div class="boss-card collapsible collapsed" id="${boss.id}">
      <div class="boss-header clickable" onclick="openBossDetail('${boss.id}')" style="cursor:pointer">
        ${artOr(boss.name, '<span class="boss-emoji">'+boss.emoji+'</span>', 'lg')}
        <div class="boss-title-block">
          <p class="boss-name">${boss.name}</p>
          <p class="boss-subtitle">${boss.subtitle}</p>
          <p class="boss-loc">${boss.loc} · <span style="color:var(--terror);font-weight:600">${boss.kph} kills/hr</span></p>
        </div>
        <div class="boss-tier-tag">
          <div class="boss-tier-label">${boss.tierLabel}</div>
          <div class="boss-tier-val">${boss.tierTag}</div>
        </div>
      </div>
      <div class="boss-body">
        <div class="diff-grid">${diffsHtml}</div>
        ${quickTake}
        ${topDropsHtml}
        <details class="all-drops-details" data-boss="${boss.id}"${window._openDropBosses.has(boss.id)?' open':''}>
        <summary class="all-drops-summary">&#9656; Show all ${dropTable.length} droppable items &mdash; full table (filter &amp; sort)</summary>
        <div class="boss-filter-bar">
          <span class="boss-filter-label">show:</span>
          <button class="boss-filter-pill ${filter==='all'?'active':''}" onclick="setBossFilter('${boss.id}','all')">all (${boss.dropTable.length})</button>
          <button class="boss-filter-pill ${filter==='grail'?'active':''}" onclick="setBossFilter('${boss.id}','grail')">grail only</button>
          <button class="boss-filter-pill ${filter==='achievable'?'active':''}" onclick="setBossFilter('${boss.id}','achievable')">achievable only</button>
          <button class="boss-filter-pill ${filter==='starred'?'active':''}" onclick="setBossFilter('${boss.id}','starred')">⭐ wishlist</button>
          <button class="boss-filter-pill ${filter==='hideowned'?'active':''}" onclick="setBossFilter('${boss.id}','hideowned')">hide ✓ owned</button>
        </div>
        <h3 style="margin:14px 0 6px;font-size:13px;color:var(--gold);text-transform:uppercase;letter-spacing:.6px">drop chances per kill (your MF: ${mf}%) — ${dropTable.length} shown</h3>
        <div class="scroll-table"><table class="drops">
          <thead><tr>
            <th>item</th>
            <th>TC/qlvl</th>
            <th class="diff-col dcol-norm ${hdrCls('norm')}" onclick="setBossSort('${boss.id}','norm')">NORM</th>
            <th class="diff-col dcol-normtz ${hdrCls('normTz')}" onclick="setBossSort('${boss.id}','normTz')">NORM TZ</th>
            <th class="diff-col dcol-nm ${hdrCls('nm')}" onclick="setBossSort('${boss.id}','nm')">NM</th>
            <th class="diff-col dcol-nmtz ${hdrCls('nmTz')}" onclick="setBossSort('${boss.id}','nmTz')">NM TZ</th>
            <th class="diff-col ${hdrCls('hell')}" onclick="setBossSort('${boss.id}','hell')">HELL</th>
            <th class="diff-col ${hdrCls('hellTz')}" onclick="setBossSort('${boss.id}','hellTz')">HELL TZ</th>
          </tr></thead>
          <tbody data-drops-for="${boss.id}"></tbody>
        </table></div>
        </details>
        <div class="success"><strong>Why farm:</strong> ${boss.why}</div>
        <div class="info"><strong>🎮 Recommended char:</strong> ${boss.char}</div>
      </div>
    </div>`;
  })();
  });

  const _usedIds = {};
  PLAYER_TIERS.forEach(g => g.members.forEach(id => { _usedIds[id] = 1; }));
  const _tiersHtml = PLAYER_TIERS.map(g => {
    const ms = g.members.filter(id => __cardOf[id]).map(id => playerMult(id, 'hell', players));
    let xtxt = '×1.00';
    if (ms.length) {
      const lo = Math.min(...ms), hi = Math.max(...ms);
      xtxt = (Math.abs(lo - hi) < 0.005) ? ('×' + hi.toFixed(2)) : ('×' + lo.toFixed(2) + '–' + hi.toFixed(2));
    }
    const cards = g.members.map(id => __cardOf[id] || '').join('');
    return `<div class="tier-section ${g.cls}">
      <div class="tier-head"><span class="tier-name">${g.name}</span><span class="tier-mult" title="drop-quantity multiplier at /players ${players}">/players ${players} · ${xtxt}</span></div>
      <div class="tier-tag">${g.tag}</div>${cards}</div>`;
  }).join('');
  const _leftover = BOSSES.filter(b => !_usedIds[b.id]).map(b => __cardOf[b.id] || '').join('');
  // v46 unify: the boss-detail overlay gets relocated INSIDE #boss-cards (it now expands
  // inline under the active card). Lift it out before we blow away innerHTML so the
  // singleton survives MF/players/filter re-renders, then re-anchor it under the rebuilt card.
  const _bdOv = document.getElementById('boss-detail-overlay');
  const _bcEl = $("boss-cards");
  if (_bdOv && _bcEl && _bcEl.contains(_bdOv) && _bcEl.parentElement) _bcEl.parentElement.insertBefore(_bdOv, _bcEl);
  $("boss-cards").innerHTML = `<div class="tier-intro">Grouped by <strong>/players</strong> drop-scaling — drag <strong>P#</strong> above to watch each class react.</div>` + _tiersHtml + _leftover;
  if (_bdOv && typeof activeBossId !== 'undefined' && activeBossId) {
    const _activeCard = document.getElementById(activeBossId);
    if (_activeCard) _activeCard.insertAdjacentElement('afterend', _bdOv);
  }

  // v341.56 — rows are built lazily, so wire #boss-cards ONCE with delegation: (a) build a boss's
  // drop <tbody> when its <details> opens (+ track open state), (b) row click → navigate (works for
  // rows added after render). Then re-fill any details left open across this re-render.
  const _bc = $("boss-cards");
  if (_bc && !_bc._dropsWired) {
    _bc._dropsWired = true;
    _bc.addEventListener('toggle', e => {
      const det = e.target;
      if (!det || !det.classList || !det.classList.contains('all-drops-details')) return;
      const id = det.getAttribute('data-boss'); if (!id) return;
      if (det.open) { window._openDropBosses.add(id); window._ensureBossRows(id); }
      else window._openDropBosses.delete(id);
    }, true);   // capture — the <details> 'toggle' event does not bubble
    _bc.addEventListener('click', e => {
      const tr = e.target.closest && e.target.closest('tr.clickable[data-item]');
      if (!tr || !_bc.contains(tr)) return;
      if (e.target.classList.contains('star-btn') || e.target.classList.contains('owned-btn')) return;
      if (typeof navigateToItem === 'function') {
        navigateToItem(tr.dataset.item);
      } else {
        selectedItem = tr.dataset.item;
        if (typeof setActiveItem === 'function') setActiveItem(tr.dataset.item);
        switchTab("calc"); renderCalc();
        setTimeout(() => $("item-detail").scrollIntoView({behavior:"smooth",block:"start"}), 100);
      }
    });
  }
  window._openDropBosses.forEach(id => window._ensureBossRows(id));
}

function setBossFilter(bossId, mode) { bossFilters[bossId] = mode; persist(); renderBossCards(); }
function setBossSort(bossId, col) {
  const cur = bossSorts[bossId];
  let dir = "asc";
  if (cur && cur.startsWith(col + ":")) dir = cur.endsWith("asc") ? "desc" : null;
  if (dir === null) delete bossSorts[bossId];
  else bossSorts[bossId] = col + ":" + dir;
  persist();
  renderBossCards();
}
function toggleStar(name) {
  if (wishlist.has(name)) wishlist.delete(name);
  else wishlist.add(name);
  persist();
  renderHero();
  renderBossCards();
  renderCalc();
  renderGrailProgress();
}
function toggleOwned(name) {
  // v677 — grail items live in the FOUND LEDGER (d2r_foundLog), never the vault: a chronicle tick
  // is knowledge, not possession (Konyo throws most finds away). Non-grail labels (socketed bases,
  // tagged keepers) keep the classic owned-set toggle — they ARE physical.
  const _gi = ITEMS.find(i => i.n === name) || ((window._UNI_EXTRA && window._UNI_EXTRA[name]) ? { n: name } : null);
  let wasOwned;
  if (_gi){
    wasOwned = _gFound(name);
    try {
      const fl = JSON.parse(window.LSR.getItem('d2r_foundLog')||'{}');
      if (wasOwned){ delete fl[name]; if (owned.has(name)){ owned.delete(name); persist(); } }   // un-tick also clears any legacy vault entry
      else fl[name] = window._grailStamp ? window._grailStamp() : new Date().toLocaleString();
      window.LSR.setItem('d2r_foundLog', JSON.stringify(fl));
      _gFoundDirty();
    } catch(e){}
  } else {
    wasOwned = owned.has(name);
    if (wasOwned) owned.delete(name);
    else owned.add(name);
    persist();
  }
  // v659 — seeded grail names: an explicit un-tick is USER TRUTH — record it so the boot floor
  // respects it (mirrors d2r_rwUnmade for the runeword seed); re-ticking clears the record.
  // v684 — same mac-ladder guard as toggleSetPiece: never let a ladder toggle mutate MAIN's shared unfound ledger.
  try { if (window._GRAIL_SEED && window._GRAIL_SEED[name] && (window._isCousinShell || window.D2R_PROFILE !== 'ladder')) { var _gu = JSON.parse(window.LSR.getItem('d2r_grailUnfound')||'{}'); if (wasOwned) _gu[name] = 1; else delete _gu[name]; window.LSR.setItem('d2r_grailUnfound', JSON.stringify(_gu)); } } catch(e){}
  // Celebrate first-time ownership of grail items
  if (!wasOwned) {
    const item = ITEMS.find(i => i.n === name);
    if (item && (item.tier === "grail" || item.tier === "uber")) {
      showCelebrate(`🏆 ${name} acquired!`);
    }
  }
  renderHero();
  renderBossCards();
  renderCalc();
  renderGrailProgress();
  // v619 — found-sync BOTH WAYS (Konyo: 'after the item is found it should sync to the platform back
  // and forth'): if a grail forge tab is the active view, its lists + seal stamps re-scan immediately
  // (tab entry already re-renders for every other path).
  try { var _tf=document.getElementById('tab-funi'); if(_tf&&_tf.classList.contains('active')&&typeof window.renderForgeUni==='function') window.renderForgeUni(); } catch(e){}
  try { var _ts=document.getElementById('tab-fsets'); if(_ts&&_ts.classList.contains('active')&&typeof window.renderForgeSets==='function') window.renderForgeSets(); } catch(e){}
}

function _collectProgress(){
  // v636 — v635's LS→LSR rebind silently killed this (LSR has no .length/.key(i): the loop never ran,
  // every export since was `data:{}` — swarm-caught). Iterate the RAW store, scoped to the ACTIVE
  // account: forked keys export under their BARE names (so a restore's LS.setItem routes them into
  // whichever account is active), the other account's namespace is never included.
  // v684 — machine-fork aware (the v663/v665 2×2 outgrew the L·-only logic: mac-main exports leaked
  // the whole W·/WL· cousin world + both machine pointers, and a restore could overwrite the other
  // machine's account then reboot into it). One rule now covers all four shells: a raw key exports
  // (bare-named) IFF it is exactly where the ACTIVE account reads that bare name — LSR.key() decides.
  const out = {}; const RAW = window.LSR.raw;
  const PTRS = { 'd2r_activeProfile':1, 'd2r_activeProfileWin':1, 'd2r_activeMachine':1 };
  for (let i = 0; i < RAW.length; i++){
    const rk = RAW.key(i); if (rk == null) continue;
    const bare = rk.indexOf('WL·') === 0 ? rk.slice(3) : (rk.indexOf('L·') === 0 || rk.indexOf('W·') === 0) ? rk.slice(2) : rk;
    if (PTRS[bare]) continue;                                                        // pointers never travel — a restore must not flip account or machine
    if (window.LSR.key(bare) === rk) out[bare] = RAW.getItem(rk);                     // active account's view only; the other namespaces never leave
  }
  return out;
}
function _progressSnapshot(){
  // v686 — schema v2 (Grok's idea, kept lean): meta names WHERE the snapshot came from so a restore
  // can be sanity-read by eye across the 2×2 machine/account grid. `data` stays FLAT — _applyProgress
  // reads only .data, so v1 and v2 snapshots both restore everywhere.
  return JSON.stringify({ app:"d2r-bible", kind:"grail-progress", version:2,
    meta:{ schemaVersion:2, build:(window.D2R_BUILD&&window.D2R_BUILD.id)||'v687', profile:(window.D2R_PROFILE||'main'), machine:(window.D2R_MACHINE||'mac') },
    exported:new Date().toISOString(), data:_collectProgress() }, null, 2);
}
function _backupStatus(msg, kind){ const el = $("backup-status"); if (!el) return; el.textContent = msg; el.className = "backup-status " + (kind || ""); }
function exportProgress(){
  const ta = $("backup-textarea"); if (ta) ta.value = _progressSnapshot();
  _backupStatus(`Snapshot built — ${owned.size} owned · ${wishlist.size} starred · ${setPieces.size} set pieces. Copy or download it to keep it safe.`, "ok");
}
function copyProgress(){
  const snap = _progressSnapshot(); const ta = $("backup-textarea"); if (ta) ta.value = snap;
  if (navigator.clipboard && navigator.clipboard.writeText){
    navigator.clipboard.writeText(snap).then(() => _backupStatus("Copied snapshot to clipboard ✓", "ok"), () => { if (ta) ta.select(); _backupStatus("Couldn't auto-copy — select the text above and copy manually.", "warn"); });
  } else { if (ta) ta.select(); _backupStatus("Select-all + ⌘/Ctrl-C to copy the snapshot above.", "warn"); }
}
function downloadProgress(){
  const snap = _progressSnapshot(); const ta = $("backup-textarea"); if (ta) ta.value = snap;
  try {
    const blob = new Blob([snap], {type:"application/json"});
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a"); a.href = url; a.download = "d2r-grail-progress-" + new Date().toISOString().slice(0,10) + ".json";
    document.body.appendChild(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(url), 1500);
    _backupStatus("Downloaded snapshot file ✓", "ok");
  } catch(e){ _backupStatus("Download isn't available here — copy the text instead.", "warn"); }
}
async function _applyProgress(raw){
  let parsed; try { parsed = JSON.parse(raw); } catch(e){ _backupStatus("That isn't a valid snapshot — expected the JSON from Export.", "err"); return false; }
  const data = (parsed && parsed.data && typeof parsed.data === "object") ? parsed.data : ((parsed && typeof parsed === "object") ? parsed : null);
  const keys = data ? Object.keys(data).filter(k => typeof data[k] === "string") : [];
  if (!keys.length){ _backupStatus("No saved progress found in that snapshot.", "err"); return false; }
  if (!(await uiConfirm("Restore " + keys.length + " saved settings from this snapshot? This OVERWRITES the grail / wishlist / settings currently in this browser."))) { _backupStatus("Restore cancelled — nothing changed.", "warn"); return false; }
  keys.forEach(k => { if (k === 'd2r_activeProfile' || k === 'd2r_activeProfileWin' || k === 'd2r_activeMachine' || k.indexOf('L·') === 0 || k.indexOf('W·') === 0) return;   // v636 — a restore must never flip the account or reach across into the other one (v684: nor flip/overwrite the other MACHINE — W· covers WL· too)
    try { LS.setItem(k, data[k]); } catch(e){} });
  _backupStatus("Restored " + keys.length + " keys — reloading…", "ok");
  setTimeout(() => location.reload(), 600);
  return true;
}
function importProgress(){ const ta = $("backup-textarea"); _applyProgress(ta ? ta.value.trim() : ""); }
function loadProgressFile(ev){
  const f = ev.target.files && ev.target.files[0]; if (!f) return;
  const r = new FileReader();
  r.onload = () => { const ta = $("backup-textarea"); if (ta) ta.value = r.result; _applyProgress(String(r.result)); };
  r.readAsText(f); ev.target.value = "";
}
window.exportProgress = exportProgress; window.copyProgress = copyProgress; window.downloadProgress = downloadProgress;
window.importProgress = importProgress; window.loadProgressFile = loadProgressFile;
function showCelebrate(msg) {
  const el = document.createElement("div");
  el.className = "celebrate";
  el.textContent = msg;
  document.body.appendChild(el);
  setTimeout(() => el.remove(), 2500);
}
window.setBossFilter = setBossFilter;
window.setBossSort = setBossSort;
window.toggleStar = toggleStar;
window.toggleOwned = toggleOwned;

function renderCalc() {
  const grid = $("item-grid");
  const filtered = ITEMS.filter(it => {
    if (currentFilter === "grail" && it.tier !== "grail") return false;
    if (currentFilter === "uber" && it.tier !== "uber") return false;
    if (currentFilter === "starred" && !wishlist.has(it.n)) return false;
    if (currentFilter === "owned" && !_gFound(it.n)) return false;
    if (currentFilter === "missing" && (_gFound(it.n) || (it.tier !== "grail" && it.tier !== "uber"))) return false;
    if (currentFilter === "special" && it.tier !== "special") return false;
    if (currentFilter === "tc87" && it.tc !== 87) return false;
    if (currentFilter === "tc85" && it.tc !== 84 && it.tc !== 85) return false;
    if (currentFilter === "tc78" && it.tc !== 78 && it.tc !== 75 && it.tc !== 73 && it.tc !== 72) return false;
    if (currentFilter === "tc60" && it.tc !== 60) return false;
    if (searchQ && !it.n.toLowerCase().includes(searchQ.toLowerCase())) return false;
    return true;
  });
  $("search-counter").textContent = `showing ${filtered.length} of ${ITEMS.length} items${searchQ?` matching "${searchQ}"`:''}${currentFilter!=='all'?` · filter: ${currentFilter}`:''}`;
  grid.innerHTML = filtered.map((it, idx) => {
    const isOwned = _gFound(it.n);
    const _r = (typeof _artRarity === 'function') ? _artRarity(it.n) : '';
    return `<div tabindex="0" data-idx="${idx}" class="item-tile tier-tc${it.tc} ${_r?'it-r-'+_r:''} ${it.tier==='grail'?'item-tile-grail':''} ${it.tier==='uber'?'item-tile-uber':''} ${wishlist.has(it.n)?'item-tile-starred':''} ${selectedItem===it.n?'selected':''}" data-name="${it.n}" style="${isOwned?'opacity:.5;text-decoration:line-through':''}">
      <div class="item-tile-row">${artOr(it.n, '', 'sm')}<div class="item-tile-text">
        <div class="item-tile-name" data-arttip="${_d2artEsc(it.n)}">${it.n}</div>
      </div></div></div>`;
  }).join("");
  grid.querySelectorAll(".item-tile").forEach(el => {
    el.onclick = () => { selectedItem = el.dataset.name; activeItem = el.dataset.name; setActiveItem(el.dataset.name); renderCalc(); renderDetail(); document.getElementById("item-detail")?.scrollIntoView({behavior:"smooth", block:"start"}); };
  });
  renderDetail();
}

// === v14 UX helpers ===
window.openGlossary = () => document.getElementById('glossary-modal').classList.add('show');
window.closeGlossary = () => document.getElementById('glossary-modal').classList.remove('show');

function renderCodexCard(name){
  if (typeof ITEM_CODEX === 'undefined') return "";
  var c = ITEM_CODEX[name];
  if(!c) return "";
  var RC = {unique:'var(--d2-unique)', set:'var(--d2-set)', special:'var(--d2-unique)'};
  var ac = RC[c.rarity] || 'var(--gold)';
  var title = (c.cat==='set' && c.setName) ? c.setName : name.replace(/\s*\([^)]*\)\s*$/,'');
  // v380 — prefix the verified base TIER (Normal/Exceptional/Elite) → "Elite Unique" / "Elite Set", like diablo2.io.
  var _tier = (typeof _baseTier==='function' && c.base) ? _baseTier(c.base) : '';
  var _tpfx = _tier ? (_tier.charAt(0).toUpperCase()+_tier.slice(1)+' ') : '';
  var rarityLabel = c.rarity==='set' ? (_tpfx + (c.cat==='setpiece'?'Set Item':'Set')) : (c.rarity==='special' ? (c.cat||'Special') : (_tpfx + 'Unique'));
  var reqs = [
    c.reqLvl?('Req Level '+c.reqLvl):'',
    c.reqStr?('Req Str '+c.reqStr):'',
    c.reqDex?('Req Dex '+c.reqDex):'',
    c.sockets?(c.sockets+' Sockets'):''
  ].filter(Boolean).map(function(r){return '<span class="cx-req">'+r+'</span>';}).join('');
  var props = (c.props&&c.props.length)?('<div class="cx-props">'+c.props.map(function(p){return '<div class="cx-prop">'+p+'</div>';}).join('')+'</div>'):'';
  var setb = (c.setBonuses&&c.setBonuses.length)?('<div class="cx-setblock"><div class="cx-set-head">'+(c.setName||'Set')+' &middot; '+(c.cat==='set'?'full set bonus':'partial set bonus')+'</div>'+c.setBonuses.map(function(s){return '<div class="cx-setbonus">'+s+'</div>';}).join('')+'</div>'):'';
  var _art = (typeof artOr==='function');
  var mem = (c.setMembers&&c.setMembers.length)?('<div class="cx-members"><div class="cx-set-head">Set Items</div>'+c.setMembers.map(function(m){var lg=_art?artOr(m.name,'','sm'):'';return '<div class="cx-member">'+(lg?'<span class="cx-member-art">'+lg+'</span>':'')+'<span class="cx-member-nm">'+m.name+'</span>'+(m.slot?' <span class="cx-member-slot">'+m.slot+'</span>':'')+'</div>';}).join('')+'</div>'):'';
  var note = c.note?('<div class="cx-note">'+c.note+'</div>'):'';
  return '<div class="codex-card" style="--cx-accent:'+ac+'">'
    +'<div class="cx-head"><span class="cx-rarity">'+rarityLabel+'</span>'
    +'<span class="cx-name" style="color:'+ac+'">'+(_art?artOr(title,'','sm'):'')+title+'</span>'
    +((c.base&&c.cat!=='set')?('<span class="cx-base">'+c.base+'</span>'):'')+'</div>'
    +(reqs?('<div class="cx-reqs">'+reqs+'</div>'):'')
    +props+setb+mem+note+'</div>';
}

function renderDetail() {
  const panel = $("item-detail");
  if (!selectedItem) { panel.classList.remove("show"); return; }
  const item = ITEMS.find(i => i.n === selectedItem);
  if (!item) { panel.classList.remove("show"); return; }
  panel.classList.add("show");
  const adjusted = item.sources.map(s => ({...s, adjustedChance:s.chance?effChance(s.chance,s.bossId,s.diffKey):null}));
  const valid = adjusted.filter(s => s.adjustedChance !== null && s.adjustedChance >= 100);
  const sorted = [...valid].sort((a,b) => {
    const aHrs = hoursFor(a.adjustedChance, 0.5, a.kph) || Infinity;
    const bHrs = hoursFor(b.adjustedChance, 0.5, b.kph) || Infinity;
    return aHrs - bHrs;
  });
  const best = sorted[0];
  const allSorted = [...adjusted].sort((a,b) => {
    if (a.adjustedChance === null && b.adjustedChance !== null) return 1;
    if (b.adjustedChance === null && a.adjustedChance !== null) return -1;
    if (a.adjustedChance === null) return 0;
    const aHrs = hoursFor(a.adjustedChance, 0.5, a.kph) || Infinity;
    const bHrs = hoursFor(b.adjustedChance, 0.5, b.kph) || Infinity;
    return aHrs - bHrs;
  });
  let bestBoxHtml = "";
  if (best) {
    const r50 = runsFor(best.adjustedChance, 0.5);
    const r95 = runsFor(best.adjustedChance, 0.95);
    const h50 = hoursFor(best.adjustedChance, 0.5, best.kph);
    const h95 = hoursFor(best.adjustedChance, 0.95, best.kph);
    bestBoxHtml = `<div class="best-source-box" style="cursor:pointer" onclick="switchTab('bosses');setTimeout(()=>{document.getElementById('${best.bossId}').scrollIntoView();jumpToBossItem('${item.n.replace(/'/g,"\\'")}', '${best.bossId}')},100)" title="click to jump to ${best.boss} and highlight this item">
      <div class="best-source-label">⭐ fastest farm for ${item.n}${best.verified?' · 🔒 VERIFIED':''} · click to jump</div>
      <div class="best-source-name">${best.boss} · ${best.kph}/hr ${sparkline(best.adjustedChance, best.kph, Math.max(1, h50*2))}</div>
      <div class="best-source-stats">
        <span>chance: <strong>${fmt(best.adjustedChance)}</strong></span>
        <span>50%: <strong>${r50?.toLocaleString()} runs ≈ ${fmtHours(h50)}</strong></span>
        <span>95%: <strong>${r95?.toLocaleString()} runs ≈ ${fmtHours(h95)}</strong></span>
      </div>
    </div>`;
  }
  const starHtml = `<span class="star-btn ${wishlist.has(item.n)?'starred':''}" style="font-size:24px" onclick="toggleStar('${item.n.replace(/'/g,"\\'")}')">${wishlist.has(item.n)?'★':'☆'}</span>`;
  const ownedHtml = `<button class="owned-btn ${_gFound(item.n)?'owned':''}" style="font-size:14px;padding:4px 10px" onclick="toggleOwned('${item.n.replace(/'/g,"\\'")}')">${_gFound(item.n)?'✓ owned':'☐ mark owned'}</button>`;
  panel.innerHTML = `${renderAidCard(item.n, {context:'calc'})}${renderCodexCard(item.n)}${typeof setPiecesSectionHtml==='function'?setPiecesSectionHtml(item.n):''}<div class="scroll-table"><table class="drops">
    <thead><tr><th>source</th><th class="diff-col">your chance</th><th class="diff-col">50% conf</th><th class="diff-col">≈ time</th><th class="diff-col">95% conf</th></tr></thead>
    <tbody>
      ${allSorted.map(s => {
        const isBest = best && s.boss === best.boss && s.adjustedChance === best.adjustedChance;
        const csrc = {norm:'csrc-norm',normTz:'csrc-normtz',nm:'csrc-nm',nmTz:'csrc-nmtz'}[s.diffKey] || '';
        if (s.adjustedChance === null) {
          return `<tr class="${csrc}"><td>${s.boss}</td><td class="diff-col blocked-mlvl" title="${s.blocked||''}">${s.blocked||'—'}</td><td class="diff-col">—</td><td class="diff-col">—</td><td class="diff-col">—</td></tr>`;
        }
        if (s.adjustedChance < 100) {
          return `<tr class="${csrc}"><td>${s.boss}</td><td class="diff-col">${fmt(s.adjustedChance)}</td><td class="diff-col">—</td><td class="diff-col">—</td><td class="diff-col">—</td></tr>`;
        }
        const r50 = runsFor(s.adjustedChance, 0.5);
        const r95 = runsFor(s.adjustedChance, 0.95);
        const h50 = hoursFor(s.adjustedChance, 0.5, s.kph);
        const verBadge = s.verified ? ' <span style="color:var(--verified);font-size:10px">🔒 verified</span>' : '';
        return `<tr class="${csrc}"><td style="${isBest?'color:var(--best);font-weight:600':''}">${s.boss}${verBadge} <span style="color:var(--text-dim);font-size:10px">${s.kph}/hr</span></td><td class="diff-col ${isBest?'best-cell':''} ${s.verified?'verified-cell':''}">${fmt(s.adjustedChance)}</td><td class="diff-col">${r50.toLocaleString()}</td><td class="diff-col" style="color:var(--terror)">${fmtHours(h50)}</td><td class="diff-col">${r95.toLocaleString()}</td></tr>`;
      }).join("")}
    </tbody>
  </table></div>
  ${best ? `<div class="puv-deep-dive">
    <div class="puv-header">
      <span class="puv-header-emoji">🔬</span>
      <div class="puv-header-text">
        <h3 class="puv-title">POWER USER DEEP DIVE — drop probability analysis</h3>
        <div class="puv-subtitle">@ <strong>${best.boss}</strong> · 1:${best.adjustedChance.toLocaleString()} chance · ${best.kph}/hr</div>
      </div>
    </div>

    <div class="puv-section">
      <div class="puv-section-title">📊 Confidence Thresholds — how many runs you actually need</div>
      <div class="puv-confidence-grid" id="puv-confidence-grid">
        ${[10, 25, 50, 75, 90, 95, 99].map(pct => {
          const p = pct / 100;
          const r = Math.ceil(Math.log(1 - p) / Math.log(1 - 1/best.adjustedChance));
          const hrs = r / best.kph;
          const fmtHr = hrs < 1 ? Math.round(hrs*60)+'m' : hrs < 24 ? hrs.toFixed(1)+'h' : (hrs/24).toFixed(1)+'d';
          return `<div class="puv-conf-cell ${pct===50?'highlight':''}">
            <div class="puv-conf-pct">${pct}%</div>
            <div class="puv-conf-runs">${r.toLocaleString()}</div>
            <div class="puv-conf-label">runs</div>
            <div class="puv-conf-time">${fmtHr}</div>
          </div>`;
        }).join('')}
      </div>
      <div class="puv-help">Read as: "${(() => { const r50 = Math.ceil(Math.log(.5) / Math.log(1 - 1/best.adjustedChance)); return r50.toLocaleString(); })()} runs gives you 50% chance of getting it" · half of players unlucky beyond this · 99% threshold = grind floor</div>
    </div>

    <div class="puv-section">
      <div class="puv-section-title">🎲 Monte Carlo Simulator — N sessions, see actual variance</div>
      <div class="puv-sim-controls">
        <span class="puv-sim-label">trials per session:</span>
        <button class="puv-trial-chip" data-trials="20" onclick="setPuvTrials(20)" data-active="true">20</button>
        <button class="puv-trial-chip" data-trials="100" onclick="setPuvTrials(100)">100</button>
        <button class="puv-trial-chip" data-trials="500" onclick="setPuvTrials(500)">500</button>
        <button class="puv-trial-chip" data-trials="2000" onclick="setPuvTrials(2000)">2000</button>
        <span class="puv-sim-label" style="margin-left:14px">runs each:</span>
        <input class="puv-sim-input" type="number" id="puv-runs" value="500" min="1" max="100000">
        <button class="puv-sim-btn" onclick="window.runPuvSim(${best.adjustedChance}, ${best.kph})">🎲 RUN</button>
      </div>
      <div class="puv-sim-result" id="puv-sim-result">
        <span style="color:var(--gold-dim);font-style:italic">Click 🎲 RUN — see the distribution of N sessions @ R runs each</span>
      </div>
    </div>

    <div class="puv-section">
      <div class="puv-section-title">⚖️ MF Comparison — what does more MF actually buy you?</div>
      <div class="puv-mf-compare" id="puv-mf-compare">
        ${(() => {
          const baseChance = best.adjustedChance;
          // Compute what chance would be at +200 MF, max 1000 MF
          const otherMfs = [Math.max(0, mf - 200), mf, Math.min(1000, mf + 200), 1000].filter((v,i,a) => a.indexOf(v) === i && v !== mf);
          // Sort and ensure current mf included
          const mfs = [...new Set([Math.max(0, mf - 200), mf, Math.min(1000, mf + 200), 1000])].sort((a,b) => a - b);
          // Get raw chance for re-scaling
          const item = ITEMS.find(i => i.n === selectedItem);
          const src = item.sources.find(s => s.bossId === best.bossId && s.diffKey === best.diffKey);
          const rawChance = src ? src.chance : null;
          if (!rawChance) return '<div style="color:var(--gold-dim)">Cannot compute MF comparison for this source.</div>';
          return mfs.map(mfVal => {
            const ch = adjustChance(rawChance, mfVal);
            const r50 = Math.ceil(Math.log(.5) / Math.log(1 - 1/ch));
            const hrs = r50 / best.kph;
            const fmtHr = hrs < 1 ? Math.round(hrs*60)+'m' : hrs < 24 ? hrs.toFixed(1)+'h' : (hrs/24).toFixed(1)+'d';
            const isCurrent = mfVal === mf;
            return `<div class="puv-mf-cell ${isCurrent?'current':''}">
              <div class="puv-mf-pct">${mfVal}% MF${isCurrent?' ⭐':''}</div>
              <div class="puv-mf-chance">1:${ch.toLocaleString()}</div>
              <div class="puv-mf-runs">${r50.toLocaleString()} runs</div>
              <div class="puv-mf-time">${fmtHr} @ 50%</div>
            </div>`;
          }).join('');
        })()}
      </div>
    </div>
  </div>` : ''}`;
  // expose sim helper - power user version
  let puvTrials = 20;
  window.setPuvTrials = (n) => {
    puvTrials = n;
    document.querySelectorAll('.puv-trial-chip').forEach(c => {
      c.dataset.active = (parseInt(c.dataset.trials) === n) ? 'true' : 'false';
    });
  };
  window.runPuvSim = (chance, kph) => {
    const runs = parseInt(document.getElementById('puv-runs').value) || 500;
    const trials = puvTrials;
    const results = new Array(trials);
    let totalDrops = 0;
    for (let t = 0; t < trials; t++) {
      let drops = 0;
      for (let r = 0; r < runs; r++) if (Math.random() < 1/chance) drops++;
      results[t] = drops;
      totalDrops += drops;
    }
    const sorted = [...results].sort((a, b) => a - b);
    const avg = totalDrops / trials;
    const expected = runs / chance;
    const minDrops = sorted[0];
    const maxDrops = sorted[trials - 1];
    const p10 = sorted[Math.floor(trials * 0.10)];
    const p25 = sorted[Math.floor(trials * 0.25)];
    const median = sorted[Math.floor(trials * 0.50)];
    const p75 = sorted[Math.floor(trials * 0.75)];
    const p90 = sorted[Math.floor(trials * 0.90)];
    const zero = results.filter(d => d === 0).length;
    const oneOrMore = results.filter(d => d >= 1).length;
    const twoOrMore = results.filter(d => d >= 2).length;
    // Histogram: bin by drop count
    const histo = {};
    results.forEach(d => { histo[d] = (histo[d] || 0) + 1; });
    const histoKeys = Object.keys(histo).map(Number).sort((a, b) => a - b);
    const maxBar = Math.max(...Object.values(histo));
    const histoHtml = histoKeys.map(k => {
      const count = histo[k];
      const h = Math.max(4, Math.round(80 * count / maxBar));
      const c = k === 0 ? '#553333' : k === 1 ? '#f0c060' : k >= 3 ? '#00ffaa' : '#88dd88';
      return `<div class="puv-histo-col">
        <div class="puv-histo-count">${count}</div>
        <div class="puv-histo-bar" style="height:${h}px;background:${c}"></div>
        <div class="puv-histo-label">${k}</div>
      </div>`;
    }).join('');
    document.getElementById('puv-sim-result').innerHTML = `
      <div class="puv-sim-meta">${trials.toLocaleString()} sessions × ${runs.toLocaleString()} runs each = ${(trials*runs).toLocaleString()} kills simulated · ${(trials*runs/kph).toFixed(1)} hours of "play"</div>
      <div class="puv-histo">${histoHtml}</div>
      <div class="puv-histo-axis">↑ # of sessions with that many drops · → # of drops in one session</div>
      <div class="puv-sim-stats-grid">
        <div class="puv-stat"><span class="puv-stat-label">EXPECTED</span><span class="puv-stat-val">${expected.toFixed(2)}</span></div>
        <div class="puv-stat"><span class="puv-stat-label">OBSERVED AVG</span><span class="puv-stat-val" style="color:#00ffaa">${avg.toFixed(2)}</span></div>
        <div class="puv-stat"><span class="puv-stat-label">P10 (unlucky)</span><span class="puv-stat-val" style="color:#ff7777">${p10}</span></div>
        <div class="puv-stat"><span class="puv-stat-label">MEDIAN</span><span class="puv-stat-val">${median}</span></div>
        <div class="puv-stat"><span class="puv-stat-label">P90 (lucky)</span><span class="puv-stat-val" style="color:#88ff88">${p90}</span></div>
        <div class="puv-stat"><span class="puv-stat-label">RANGE</span><span class="puv-stat-val">${minDrops} → ${maxDrops}</span></div>
        <div class="puv-stat"><span class="puv-stat-label">ZERO DROPS</span><span class="puv-stat-val" style="color:#ff7777">${zero}/${trials} (${Math.round(zero/trials*100)}%)</span></div>
        <div class="puv-stat"><span class="puv-stat-label">1+ DROP</span><span class="puv-stat-val" style="color:#00ffaa">${oneOrMore}/${trials} (${Math.round(oneOrMore/trials*100)}%)</span></div>
        <div class="puv-stat"><span class="puv-stat-label">2+ DROPS</span><span class="puv-stat-val">${twoOrMore}/${trials} (${Math.round(twoOrMore/trials*100)}%)</span></div>
      </div>
    `;
  };
}

let activeSourceKey = null; // format: 'bossId|diffKey'
function setActiveItem(name, sourceBossId, sourceDiffKey) {
  activeItem = name;
  // v42 polish: record in recently-viewed even when navigation skips the palette
  try { if (name && typeof window._v42_pushRecent === 'function') window._v42_pushRecent({label: name, cat: 'item'}); } catch(e) {}
  if (sourceBossId !== undefined && sourceDiffKey !== undefined) activeSourceKey = `${sourceBossId}|${sourceDiffKey}`;
  else if (sourceBossId !== undefined) activeSourceKey = sourceBossId; // legacy bossId-only call — match any diff
  if (!name) activeSourceKey = null;
  const bar = $("active-item-bar");
  const detail = $("active-item-detail");
  if (!bar) return;
  if (!name) {
    bar.classList.remove("show");
    if (detail) { detail.classList.remove("show"); detail.innerHTML = ""; }
    document.querySelectorAll(".boss-card").forEach(c => { c.classList.remove("has-item"); c.classList.remove("no-item"); });
    // v42 UX route-back: smoothly return user to the top of bosses tab so they can pick another item
    setTimeout(() => {
      const target = document.getElementById('boss-nav') || document.querySelector('.tabs');
      if (target) {
        const y = target.getBoundingClientRect().top + window.scrollY - 100;
        window.scrollTo({ top: Math.max(0, y), behavior: 'smooth' });
      }
    }, 60);
    return;
  }
  bar.classList.add("show");
  $("aib-item-name").textContent = name;
  // Find best source for active item summary
  const item = ITEMS.find(i => i.n === name);
  if (item) {
    const adj = item.sources.map(s => ({...s, adj: s.chance ? effChance(s.chance, s.bossId, s.diffKey) : null}));
    const valid = adj.filter(s => s.adj !== null && s.adj >= 100);
    valid.sort((a, b) => {
      const ah = hoursFor(a.adj, 0.5, a.kph) || Infinity;
      const bh = hoursFor(b.adj, 0.5, b.kph) || Infinity;
      return ah - bh;
    });
    if (valid.length) {
      const best = valid[0];
      const h50 = hoursFor(best.adj, 0.5, best.kph);
      $("aib-stats").innerHTML = `<strong>${valid.length}</strong> sources · fastest: <strong>${best.boss}</strong> @ ${fmt(best.adj)} (${fmtHours(h50)} for 50%)`;
    } else {
      $("aib-stats").innerHTML = "no achievable sources at your current MF setup";
    }
  }
  // Glow bosses that drop this item, dim others
  document.querySelectorAll(".boss-card").forEach(card => {
    const id = card.id;
    const boss = BOSSES.find(b => b.id === id);
    if (!boss) return;
    const has = boss.dropTable.some(d => d.n === name && ["norm","normTz","nm","nmTz","hell","hellTz"].some(k => d[k] !== null));
    if (has) { card.classList.add("has-item"); card.classList.remove("no-item"); }
    else { card.classList.add("no-item"); card.classList.remove("has-item"); }
  });
  // === v15: render the expanded detail panel ===
  renderActiveItemDetail(name);
  // === v17: pulse the exact (boss, diff) cell in the boss drop table ===
  setTimeout(() => {
    document.querySelectorAll("td.focused-cell").forEach(c => c.classList.remove("focused-cell"));
    if (!activeSourceKey || !activeSourceKey.includes('|')) return;
    const [bid, dk] = activeSourceKey.split('|');
    const card = document.getElementById(bid);
    if (!card) return;
    // v341.56 — drop rows are built lazily; open + build this boss's table so the row exists to pulse
    const _fcDet = card.querySelector('.all-drops-details');
    if (_fcDet && !_fcDet.open) _fcDet.open = true;
    if (window._openDropBosses) window._openDropBosses.add(bid);
    if (typeof window._ensureBossRows === 'function') window._ensureBossRows(bid);
    const row = card.querySelector(`tr[data-item="${name.replace(/"/g,'\\"')}"]`);
    if (!row) return;
    const diffIdx = DIFF_KEYS_ORDERED.indexOf(dk);
    if (diffIdx < 0) return;
    const cells = row.querySelectorAll("td.diff-col");
    if (cells[diffIdx]) cells[diffIdx].classList.add("focused-cell");
  }, 200);
}

function renderActiveItemDetail(name){
  const detail = $("active-item-detail");
  if (!detail || !name) { if (detail) { detail.classList.remove("show"); detail.innerHTML = ""; } return; }
  const html = renderAidCard(name, {context:"bosses"});
  if (!html) { detail.classList.remove("show"); detail.innerHTML = ""; return; }
  detail.innerHTML = html;
  detail.classList.add("show");
}

// === v19: shared aid-card renderer used by BOTH bosses tab + calc tab ===
function renderAidCard(name, opts){
  opts = opts || {};
  const item = ITEMS.find(i => i.n === name);
  if (!item) return "";

  const adj = item.sources.map(s => ({...s, adj: s.chance ? effChance(s.chance, s.bossId, s.diffKey) : null}));
  // Convention (see fmt): raw chance < 100 is a PERCENTAGE per kill (event/uber drops like
  // Annihilus + the Pandemonium Keys), >= 100 is a 1:N denominator. The global runsFor/hoursFor
  // only handle 1:N, so %-sources need the binomial applied to the per-kill % directly.
  const isPctC = c => c != null && c < 100;
  const pctRuns = (pct, conf) => (pct > 0 && pct < 100) ? Math.ceil(Math.log(1-conf)/Math.log(1-pct/100)) : null;
  const runsForA = (rawChance, adjVal, conf) => isPctC(rawChance) ? pctRuns(adjVal, conf) : runsFor(adjVal, conf);
  const hoursForA = (rawChance, adjVal, kph, conf) => { const r = runsForA(rawChance, adjVal, conf); return (r != null && kph) ? r / kph : null; };
  // %-sources are achievable — don't drop them as "no sources".
  const valid = adj.filter(s => s.adj !== null && (s.adj >= 100 || isPctC(s.chance)));
  valid.sort((a,b) => (hoursForA(a.chance,a.adj,a.kph,0.5)||Infinity) - (hoursForA(b.chance,b.adj,b.kph,0.5)||Infinity));
  // v87 is a Hell-only view: norm/normTz/nm/nmTz source chips are hidden site-wide
  // (CSS line ~107). Only render the difficulties the user can actually see/click so
  // the first chip is never an invisible NM/NORM source. Falls back to all tiers if an
  // item has no Hell source at all (so the bar is never empty for a reachable item).
  const _hellOnly = valid.filter(s => s.diffKey === 'hell' || s.diffKey === 'hellTz');
  const chipSrc = _hellOnly.length ? _hellOnly : valid;

  let focus = null;
  if (activeSourceKey) {
    if (activeSourceKey.includes('|')) {
      focus = valid.find(s => `${s.bossId}|${s.diffKey}` === activeSourceKey);
    } else {
      focus = valid.find(s => s.bossId === activeSourceKey);
    }
  }
  if (!focus) focus = valid[0];

  if (!focus) {
    return `<div class="aid-card"><div class="aid-empty">No achievable sources for <strong>${name}</strong> at MF ${mf}% — try higher difficulty or terror zone.</div></div>`;
  }

  const h50 = hoursForA(focus.chance, focus.adj, focus.kph, 0.5);
  const r50 = runsForA(focus.chance, focus.adj, 0.5);
  const h95 = hoursForA(focus.chance, focus.adj, focus.kph, 0.95);
  const r95 = runsForA(focus.chance, focus.adj, 0.95);
  const isFastest = focus === valid[0];
  const fastest = valid[0];

  const desc = ITEM_INFO[name] || `<span style="color:var(--text-muted);font-style:italic">${item.tier} item · TC${item.tc}${item.qlvl?' · qlvl '+item.qlvl:''} — no curated description yet</span>`;
  const rec = BOSS_CHAR_REC[focus.bossId];
  const char = rec ? CHARS[rec.top] : null;
  const plan = BOSS_ACTION_PLAN[focus.bossId];
  const diffMod = DIFF_MODIFIERS[focus.diffKey] || {label: (focus.diffKey||'').toUpperCase()};
  const escName = name.replace(/'/g, "\\'");
  const tierCls = `tier-${item.tier}`;
  const isStarred = wishlist.has(name);
  const isOwned = _gFound(name);

  const fasterBanner = !isFastest && fastest ? `
    <div class="aid-faster-banner">
      <span>⚠ <strong>${fastest.boss}</strong> is ${fmtHours(h50 - hoursForA(fastest.chance,fastest.adj,fastest.kph,0.5))} faster: ${fmt(fastest.adj)} (${fmtHours(hoursForA(fastest.chance,fastest.adj,fastest.kph,0.5))} for 50%)</span>
      <a href="javascript:void(0)" onclick="${opts.context==='calc'?'switchTab(\'bosses\');':''}setActiveItem('${escName}', '${fastest.bossId}', '${fastest.diffKey}');setTimeout(()=>{document.getElementById('${fastest.bossId}').scrollIntoView();jumpToBossItem('${escName}')},100)">jump to fastest →</a>
    </div>` : '';

  const compareRows = DIFF_KEYS_ORDERED.map(dk => {
    const src = item.sources.find(s => s.bossId === focus.bossId && s.diffKey === dk);
    if (!src) return null;
    const sAdj = src.chance ? effChance(src.chance, src.bossId, src.diffKey) : null;
    const blocked = src.blocked;
    const sH50 = sAdj ? hoursForA(src.chance, sAdj, src.kph, 0.5) : null;
    const isFocused = dk === focus.diffKey;
    const diffLabel = (DIFF_MODIFIERS[dk]||{}).label || dk.toUpperCase();
    const acr = {norm:'acr-norm',normTz:'acr-normtz',nm:'acr-nm',nmTz:'acr-nmtz'}[dk] || '';
    return `<div class="aid-compare-row ${isFocused?'focused':''} ${acr}">
      <div class="aid-compare-diff">${isFocused?'⭐ ':''}${diffLabel}</div>
      <div class="aid-compare-chance ${!sAdj?'blocked':''}">${sAdj ? fmt(sAdj) : (blocked || '—')}</div>
      <div class="aid-compare-time">${sH50 ? fmtHours(sH50) : '—'}</div>
      <div class="aid-compare-kph">${src.kph?src.kph+'/hr':''}</div>
      <div class="aid-compare-pin" onclick="setActiveItem('${escName}', '${focus.bossId}', '${dk}')" title="${isFocused?'currently focused':'focus this difficulty'}">${isFocused?'●':'○'}</div>
    </div>`;
  }).filter(Boolean).join('');

  return `<div class="aid-card${_artRarity(name)?' aid-r-'+_artRarity(name):''}">
    <header class="aid-header">
      <div class="aid-header-left">
        <div class="aid-item-name">
          <span class="aid-star ${isStarred?'starred':''}" onclick="toggleStar('${escName}')" style="cursor:pointer;margin-right:6px;font-size:18px;color:${isStarred?'var(--star)':'var(--text-muted)'}">${isStarred?'★':'☆'}</span>
          ${artOr(name, '', 'sm')}
          <span class="aid-name-txt"${typeof _qStyle==='function'?_qStyle(name,'unique'):''}>${name}</span>
          ${isOwned?' <span style="color:var(--best);font-size:12px;font-family:var(--mono);background:rgba(102,255,136,.1);padding:2px 6px;border-radius:3px">✓ OWNED</span>':''}
        </div>
        <div class="aid-item-meta">
          <span class="aid-meta-pill">TC${item.tc}</span>
          ${item.qlvl ? `<span class="aid-meta-pill">qlvl ${item.qlvl}</span>` : ''}
          <span class="aid-meta-pill ${tierCls}">${item.tier.toUpperCase()}</span>
          <span class="aid-meta-pill" style="color:var(--text-muted)">${valid.length} source${valid.length===1?'':'s'}</span>
        </div>
      </div>
      <div class="aid-header-close">
        ${aidCardOrigin && opts.context==='calc' && aidCardOrigin.bossId ? `<button class="aid-back-btn" onclick="goBackFromAid()" title="back to ${aidCardOrigin.bossId} boss detail">← back to ${(BOSSES.find(b=>b.id===aidCardOrigin.bossId)||{}).name || aidCardOrigin.bossId}</button>` : ''}
        <button class="aid-close-btn" onclick="toggleOwned('${escName}')">${isOwned?'☑ owned':'☐ mark owned'}</button>
        <button class="aid-close-btn" onclick="openGlossary()" title="what does TC and qlvl mean?">?</button>
        ${opts.context==='bosses'
          ? `<button class="aid-close-btn" onclick="navigateToItem('${escName}')">↗ open in calc</button>`
          : `<button class="aid-close-btn" onclick="setActiveItem('${escName}');switchTab('bosses');setTimeout(()=>{document.getElementById('${focus.bossId}').scrollIntoView();jumpToBossItem('${escName}')},100)">↗ jump to boss</button>`}
      </div>
    </header>

    ${(typeof isSetAggregate==='function' && isSetAggregate(item.n))
        ? '<div class="aid-set-comp" style="margin:14px 0 2px">'+setDetailHtml(item.n, {embed:true})+'</div>'
        : ((typeof ITEM_CODEX!=='undefined' && ITEM_CODEX[item.n] && ITEM_CODEX[item.n].setMembers && ITEM_CODEX[item.n].setMembers.length) ? '<div class="aid-set-comp" style="margin:14px 0 2px">'+renderCodexCard(item.n)+'</div>' : '')}
    <div class="aid-tabbar">
      <div class="aid-tabbar-label">↔ pick your source · ${chipSrc.length} option${chipSrc.length===1?'':'s'} · click any to refocus the panel below</div>
      <div class="aid-tabbar-chips">
        ${chipSrc.slice(0,12).map(s => {
          const isF = s.bossId===focus.bossId && s.diffKey===focus.diffKey;
          const sH50 = hoursForA(s.chance, s.adj, s.kph, 0.5);
          const schip = {norm:'schip-norm',normTz:'schip-normtz',nm:'schip-nm',nmTz:'schip-nmtz'}[s.diffKey] || '';
          return `<button class="source-chip ${schip}" onclick="setActiveItem('${escName}', '${s.bossId}', '${s.diffKey}')${opts.context==='calc'?';switchTab(\'bosses\');setTimeout(()=>{document.getElementById(\''+s.bossId+'\').scrollIntoView();jumpToBossItem(\''+escName+'\')},100)':''}" ${isF?'data-active="true"':''}>${isF?'⭐ ':''}${s.boss}<span class="chip-chance">${fmt(s.adj)}</span><span class="chip-time">${fmtHours(sH50)}</span>${s.verified?'<span class="chip-verified">🔒</span>':''}</button>`;
        }).join('')}
        ${chipSrc.length > 12 ? `<span class="aid-tabbar-more">+${chipSrc.length-12} more (see compare table below)</span>` : ''}
      </div>
    </div>

    <section class="aid-section">
      <div class="aid-section-label">📜 what it does</div>
      <div class="aid-desc">${desc}</div>
    </section>

    <section class="aid-section">
      <div class="aid-section-label">📍 focused source</div>
      <div class="aid-focus-card">
        <div class="aid-focus-head">
          <span class="aid-focus-boss">${focus.boss}</span>
          <span class="aid-focus-diff-pill">${diffMod.label.toUpperCase()}</span>
          <span class="aid-focus-kph">${focus.kph}/hr</span>
          ${isFastest ? '<span class="aid-focus-badge aid-focus-fastest">⭐ FASTEST</span>' : ''}
          ${focus.verified ? '<span class="aid-focus-badge aid-focus-verified">🔒 VERIFIED</span>' : ''}
        </div>
        <div class="aid-stats-grid">
          <div class="aid-stat">
            <div class="aid-stat-label">chance</div>
            <div class="aid-stat-val">${fmt(focus.adj)}</div>
            <div class="aid-stat-hint">@ ${mf}% MF</div>
          </div>
          <div class="aid-stat">
            <div class="aid-stat-label">50% confident</div>
            <div class="aid-stat-val">${r50!=null?r50.toLocaleString():'—'}<span class="aid-stat-unit">runs</span></div>
            <div class="aid-stat-hint">≈ ${fmtHours(h50)}</div>
          </div>
          <div class="aid-stat">
            <div class="aid-stat-label">95% confident</div>
            <div class="aid-stat-val">${r95!=null?r95.toLocaleString():'—'}<span class="aid-stat-unit">runs</span></div>
            <div class="aid-stat-hint">≈ ${fmtHours(h95)}</div>
          </div>
        </div>
        ${fasterBanner}
      </div>
    </section>

    ${char ? `<section class="aid-section">
      <div class="aid-section-label">⭐ best char from your roster</div>
      <div class="aid-char-card">
        <div class="aid-char-medal">${rec.top==='konyolock'?'🗡️':rec.top==='konyodin'?'🔨':rec.top==='konyoress'?'❄️':'🥋'}</div>
        <div class="aid-char-body">
          <div class="aid-char-name">${char.name}</div>
          <div class="aid-char-build">${char.build}</div>
          <div class="aid-char-reason">${rec.reason}</div>
        </div>
      </div>
    </section>` : ''}

    ${plan ? `<section class="aid-section">
      <div class="aid-section-label">📋 pre-run action plan</div>
      <div class="aid-plan">
        <div class="aid-plan-row"><div class="aid-plan-key">go to</div><div class="aid-plan-val">${plan.open}</div></div>
        <div class="aid-plan-row"><div class="aid-plan-key">build tip</div><div class="aid-plan-val">${plan.build}</div></div>
        <div class="aid-plan-row"><div class="aid-plan-key">cadence</div><div class="aid-plan-val">${plan.run}</div></div>
        ${diffMod.note ? `<div class="aid-plan-modifier">📊 <strong>${diffMod.label}</strong>: ${diffMod.note}</div>` : ''}
        ${plan.warning ? `<div class="aid-plan-warning">⚠ ${plan.warning}</div>` : ''}
        ${diffMod.warn ? `<div class="aid-plan-warning">${diffMod.warn}</div>` : ''}
      </div>
    </section>` : ''}

    <section class="aid-section">
      <div class="aid-section-label">⚖ compare all difficulties · ${(BOSSES.find(b=>b.id===focus.bossId)||{}).name||focus.boss} × ${name}</div>
      <div class="aid-compare">
        <div class="aid-compare-head">
          <div>difficulty</div><div>chance</div><div>time 50%</div><div>kph</div><div></div>
        </div>
        ${compareRows}
      </div>
    </section>
  </div>`;
}
window.clearActiveItem = () => setActiveItem(null);

function tzZoneCardHtml(z, zi){
  const tags = z.tags.map(t => `<span class="tz-zone-tag ${t}">${t==='hot'?'🔥 hot':t==='dense'?'⚡ dense':t==='tc87'?'TC87 unlock':t==='tc85'?'TC85 unlock':t}</span>`).join('');
  

  const bossId = (typeof tzZoneBoss === 'function') ? (tzZoneBoss(z.name) || '') : '';
  

  const fi = (typeof zoneFeedsInto === 'function') ? zoneFeedsInto(z) : [];
  const fiStrip = (typeof feedsIntoStripHtml === 'function') ? feedsIntoStripHtml(fi) : '';
  

  const click = `window.toggleZoneDetail(${zi})`;
  const titleTxt = bossId ? ('open ' + z.name + ' drop detail (with ' + bossId + ' cross-link)') : 'open full zone drop detail';
  return `<div class="tz-zone-card" data-zone-idx="${zi}" data-boss-id="${bossId}" onclick="${click}" style="cursor:pointer" title="${titleTxt}">
      <div class="tz-zone-header">
        ${tzZoneEmblem(z)}
        <div class="tz-zone-title-block">
          <p class="tz-zone-name sec-h-t">${z.name}</p>
          <p class="tz-zone-sub">🎯 ${linkifySU(z.unique)}</p>
          <p class="tz-zone-loc">${z.act} · mlvl ${z.mlvl} terror · TC ${z.tcMax} max · ${z.density}</p>
        </div>
        <span class="tz-zone-tier">${z.tier}</span>
        <span class="tz-zone-chev sec-chev" aria-hidden="true">▾</span>
      </div>
      <div class="tz-zone-collapse">
        <div class="tz-zone-body">${z.why}</div>
        ${fiStrip}
        <div class="tz-zone-tags">${tags}</div>
      </div>
      <div class="tz-zone-detail" id="tz-zone-detail-${zi}" hidden></div>
    </div>`;
}

function tzCrosslinkCardHtml(cl){
  const b = (typeof BOSSES !== 'undefined') ? BOSSES.find((x) => x.id === cl.bossId) : null;
  if (!b) return '';
  const clArt = (typeof artUrl === 'function') ? artUrl(b.name) : null;
  const clEmblem = clArt
    ? `<span class="sec-h-art tz-zone-emblem"><span class="d2art-wrap sm"><img class="d2art-img" loading="lazy" alt="${b.name}" src="${clArt}" onload="this.parentNode.classList.remove('d2art-failed')" onerror="this.parentNode.classList.add('d2art-failed')"><span class="d2art-fallback"><span class="tz-zone-emoji">${b.emoji || '🗺️'}</span></span></span></span>`
    : `<span class="sec-h-art tz-zone-emblem"><span class="tz-zone-emoji">${b.emoji || '🗺️'}</span></span>`;
  return `<div class="tz-crosslink-card" data-crosslink-boss-id="${b.id}" onclick="window.openBossDetail('${b.id}')" style="cursor:pointer" title="open ${b.name}'s full ID card in the Bosses tab">
      <div class="tz-zone-header">
        ${clEmblem}
        <div class="tz-zone-title-block">
          <p class="tz-zone-name sec-h-t">${b.name}</p>
          <p class="tz-zone-sub">${b.subtitle || ''}</p>
          <p class="tz-zone-loc">${b.loc || ''}</p>
        </div>
        <span class="tz-zone-tier">${b.tierTag || ''}</span>
        <span class="tz-zone-chev sec-chev" aria-hidden="true">▾</span>
      </div>
      <div class="tz-crosslink-go">📜 permanent lvl-85 zone — it fires TZ alerts, but its full ID card lives in the Bosses tab. Click to open ${b.name}'s drop table →</div>
    </div>`;
}
window.tzCrosslinkCardHtml = tzCrosslinkCardHtml;
function renderTzZones() {
  const el = document.getElementById('tz-zones-container');
  if (!el) return;
  

  const crosslinks = (typeof TZ_CROSSLINKS !== 'undefined') ? TZ_CROSSLINKS : [];
  const indices = TZ_ZONES.map((_, zi) => zi);
  const used = new Set();
  let html = '';
  TERROR_GROUPS.forEach((g) => {
    const members = indices.filter((zi) => !used.has(zi) && g.match(TZ_ZONES[zi]));
    const groupLinks = crosslinks.filter((cl) => cl.act === g.act);
    if (!members.length && !groupLinks.length) return;
    members.forEach((zi) => used.add(zi));
    const count = members.length + groupLinks.length;
    html += `<div class="tz-group-head"><span class="tz-group-emoji">${g.emoji}</span><span class="tz-group-act">${g.act}</span><span class="tz-group-label">${g.label}</span><span class="tz-group-count">${count} zone${count===1?'':'s'}</span></div>`;
    html += members.map((zi) => tzZoneCardHtml(TZ_ZONES[zi], zi)).join('');
    html += groupLinks.map((cl) => tzCrosslinkCardHtml(cl)).join('');
  });
  const leftover = indices.filter((zi) => !used.has(zi));
  if (leftover.length){
    html += `<div class="tz-group-head"><span class="tz-group-emoji">📍</span><span class="tz-group-act">Other</span><span class="tz-group-label">uncategorised terror zones</span><span class="tz-group-count">${leftover.length} zone${leftover.length===1?'':'s'}</span></div>`;
    html += leftover.map((zi) => tzZoneCardHtml(TZ_ZONES[zi], zi)).join('');
  }
  el.innerHTML = html;
}

// v258: a slot-appropriate emoji fallback for set pieces whose art file we don't have
// yet (diablo2.io bot-guards server fetches — those 14 need the browser fetcher). Shows
// the real art when present, a 💍/📿/🥾… glyph by slot otherwise — never a blank.
function _setSlotGlyph(p){
  const m = /\(([^)]+)\)\s*$/.exec(p); const slot = m ? m[1].toLowerCase() : '';
  if (/ring/.test(slot)) return '💍';
  if (/amulet/.test(slot)) return '📿';
  if (/helm|mask|circlet|crown|cap|visage|coif|diadem/.test(slot)) return '⛑️';
  if (/shield|guard/.test(slot)) return '🛡️';
  if (/armor|chainmail|plate|mail|body|skin|hide/.test(slot)) return '🥋';
  if (/glove|gauntlet|cuff|gage/.test(slot)) return '🧤';
  if (/boot|greave|sabot|pillar|advance/.test(slot)) return '🥾';
  if (/belt|cord|sash|girdle|detail/.test(slot)) return '🔗';
  if (/sword|axe|mace|hammer|scepter|rod|staff|spear|polearm|club|wand|orb|blade|charge|guardian|crusher|sickle/.test(slot)) return '⚔️';
  return '🗡️';
}
function renderSetTracker() {
  const el = document.getElementById('set-tracker');
  if (!el) return;
  el.innerHTML = ITEM_SETS.map(set => {
    const have = set.pieces.filter(p => setPieces.has(p)).length;
    const complete = have === set.pieces.length;
    const pieces = set.pieces.map(p => {
      const esc = p.replace(/'/g, "\\'");
      const _i = p.indexOf(' (');
      const _b = _i >= 0 ? p.slice(0, _i) : p;            // strip the "(slot)" suffix -> base item name
      const _bAttr = _b.replace(/"/g, '&quot;');
      // set pieces have no individual openDrop card, so art-logo + hover-popup only (no dead route)
      const _nm = `<span class="set-piece-name" data-arttip="${_bAttr}"${_qStyle(_b, 'set')}>${artOr(_b, _setSlotGlyph(p), 'sm')} ${p}</span>`;
      return `<div class="set-piece ${setPieces.has(p)?'checked':''}" onclick="toggleSetPiece('${esc}')">
        <span class="set-piece-box"></span>
        ${_nm}
      </div>`;
    }).join('');
    const _routable = (typeof isSetAggregate === 'function') && isSetAggregate(set.name);
    const _setEsc = set.name.replace(/'/g, "\\'");
    const nameHtml = _routable
      ? `<div class="set-card-name set-card-open" role="button" tabindex="0" title="open the ${set.name} ID card" onclick="event.stopPropagation();window.openDrop('${_setEsc}')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();window.openDrop('${_setEsc}')}">${set.name}${complete?' ✓':''} <span class="set-open-caret">↗</span></div>`
      : `<div class="set-card-name">${set.name}${complete?' ✓':''}</div>`;
    return `<div class="set-card ${complete?'complete':''}">
      <div class="set-card-header">
        <span class="sec-h-art set-card-emblem">${artOr(set.name, '🛡️', 'sm')}</span>
        <div class="set-card-title-block">
          ${nameHtml}
          <div class="set-card-progress">${have} / ${set.pieces.length} pieces${complete?' · complete':''}</div>
        </div>
      </div>
      <div class="set-pieces">${pieces}</div>
    </div>`;
  }).join('');
}
function toggleSetPiece(piece) {
  // v644 — set pieces chronicle into the same found ledger
  try { const fl = JSON.parse(window.LSR.getItem('d2r_foundLog')||'{}');
    if (setPieces.has(piece)) delete fl[piece]; else fl[piece] = window._grailStamp ? window._grailStamp() : new Date().toLocaleString();
    window.LSR.setItem('d2r_foundLog', JSON.stringify(fl)); } catch(e){}
  // v682 — a seeded piece un-tick is USER TRUTH: record it so the boot floor never re-asserts it
  // v684 — MAC-ladder must NOT write this: d2r_grailUnfound isn't ladder-forked, so a ladder un-tick
  // would land in MAIN's shared ledger and permanently gate main's seed floor (and a ladder re-tick
  // would erase main's explicit un-marks). The floor only runs on the owner (mac main); cousin's
  // W·-family writes stay correct via LSR.
  try { if (window._SET_SEED && window._SET_SEED[piece] && (window._isCousinShell || window.D2R_PROFILE !== 'ladder')) { var _sgu = JSON.parse(window.LSR.getItem('d2r_grailUnfound')||'{}'); if (setPieces.has(piece)) _sgu[piece] = 1; else delete _sgu[piece]; window.LSR.setItem('d2r_grailUnfound', JSON.stringify(_sgu)); } } catch(e){}
  if (setPieces.has(piece)) setPieces.delete(piece);
  else setPieces.add(piece);
  persist();
  renderSetTracker();
  // v619 — found-sync both ways: a tick from the Tools checklist wall re-scans an open F·Sets tab
  // (and vice versa — fsets ticks already call renderSetTracker via toggleSetPiece).
  try { var _ts=document.getElementById('tab-fsets'); if(_ts&&_ts.classList.contains('active')&&typeof window.renderForgeSets==='function') window.renderForgeSets(); } catch(e){}
}
window.toggleSetPiece = toggleSetPiece;

// v259: 1-photo AI set-piece intake — screenshot your set items → Claude reads the
// names → each recognised piece is checked off in the tracker (the setPieces Set).
window.setIntake = async function(files){
  var report = document.getElementById('set-intake-report');
  if (!files || !files.length) return;
  window._aiIntakeStart('set-tracker','reading your set items','the AI is checking the tracker');
  function downscale(file){
    return new Promise(function(resolve, reject){
      var img=new Image(), url=URL.createObjectURL(file);
      img.onload=function(){
        var MAX=1568, scale=Math.min(1, MAX/Math.max(img.width,img.height));
        var c=document.createElement('canvas');
        c.width=Math.round(img.width*scale); c.height=Math.round(img.height*scale);
        c.getContext('2d').drawImage(img,0,0,c.width,c.height);
        URL.revokeObjectURL(url);
        resolve(c.toDataURL('image/jpeg',0.85).split(',')[1]);
      };
      img.onerror=reject; img.src=url;
    });
  }
  // base-name vocab + base→full-piece map (setPieces keys are the full "Name (slot)" strings)
  var baseToPiece={}, vocab=[];
  try { __allSets().forEach(function(st){ (st.pieces||[]).forEach(function(p){ var i=p.indexOf(' ('); var b=(i>=0?p.slice(0,i):p); baseToPiece[b.toLowerCase()]=p; vocab.push(b); }); }); } catch(e){}
  var marked=[], errors=0;
  for (var i=0;i<files.length;i++){
    try{
      var b64=await downscale(files[i]);
      var endpoint = localStorage.getItem('d2r_intakeUrl') || (location.protocol==='file:'?'https://bull-4-u.com/api/intake':'/api/intake');
      // items mode (reads NAMES from tooltips), not tally — a set piece is owned-or-not
      var resp=await fetch(endpoint,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({image:b64,media_type:'image/jpeg',names:vocab})});
      if(!resp.ok){ errors++; continue; }
      var data=await resp.json();
      (data.items||[]).forEach(function(n){
        var piece = baseToPiece[String(n).toLowerCase().trim()];
        if(piece && !setPieces.has(piece)){ setPieces.add(piece); marked.push(piece); }
      });
    }catch(e){ errors++; }
  }
  persist(); renderSetTracker();
  window._aiIntakeStop('set-tracker');
  if (report){ report.hidden=false;
    if (marked.length){
      report.innerHTML='🪄 <strong>checked off '+marked.length+' set piece'+(marked.length===1?'':'s')+'</strong>: '
        + marked.sort().map(function(k){return '<span style="color:var(--best,#66ff88)">'+k+'</span>';}).join(' · ')
        + (errors?' · <span style="color:var(--hell,#ff4040)">'+errors+' image error'+(errors===1?'':'s')+'</span>':'')
        + '<div style="color:var(--text-dim);font-size:11px;margin-top:5px">Reads item NAMES from tooltips — for best results, screenshot with an item’s hover-tooltip open. Click any piece to toggle it manually.</div>';
    } else {
      report.innerHTML='No set pieces recognised'+(errors?' ('+errors+' image error'+(errors===1?'':'s')+')':'')+'. Tip: this reads NAMES, so a shot with the item’s hover-tooltip open works best (artwork alone isn’t enough).';
    }
  }
};

