async function importGemTally(){
  var ta = document.getElementById('gem-import-box'); var status = document.getElementById('gem-import-status');
  var setStatus = function(m){ if (status) status.textContent = m; };
  if (!ta) return;
  var raw = (ta.value || '').trim();
  if (!raw){ setStatus('Paste a tally first.'); return; }
  var next = {}; var parsed = null;
  try { parsed = JSON.parse(raw); } catch (e) {}
  if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)){
    Object.keys(parsed).forEach(function(k){ var key = findGem(k); var v = parseInt(parsed[k], 10); if (key && isFinite(v) && v > 0) next[key] = v; });
  } else {
    var re = /([A-Za-z]+(?:\s+[A-Za-z]+)?)\s*[:=]\s*(\d+)/g; var m;
    while ((m = re.exec(raw)) !== null){ var key = findGem(m[1].trim()); var v = parseInt(m[2], 10); if (key && isFinite(v) && v > 0) next[key] = v; }
  }
  var n = Object.keys(next).length;
  if (!n){ setStatus('No valid gems found — try "Perfect Amethyst: 4".'); return; }
  if (Object.keys(gemStash).length && !(await uiConfirm('Replace your current gem tally with this import?'))){ setStatus('Import cancelled.'); return; }
  gemStash = next; persist(); renderGemStash();
  var total = Object.values(next).reduce(function(a, b){ return a + b; }, 0);
  setStatus('Loaded ' + n + ' gem types (' + total + ' gems).'); ta.value = '';
}
