  var haveGemCubed = (typeof gemCubeUpPotential === 'function') ? gemCubeUpPotential(craft.gemType, 4) >= 1 : false;
  var haveBase = true;                             // v341.44 — magic base is vendor-buyable at will → always on hand (locked HAVE)
