  function cnRecipeStatus(p){
    function ing(i){
      var ic = i.kind==='base' ? '<span class="cn-rc-g">'+((typeof CRAFT_SLOT_GLYPH!=='undefined'&&CRAFT_SLOT_GLYPH[i.name])?CRAFT_SLOT_GLYPH[i.name]:'🔨')+'</span>'
             : i.kind==='jewel' ? '<span class="cn-rc-jw"><img src="art/jewel04_graphic.png" alt="" loading="lazy"></span>'
             : '<span class="cn-rc-i">'+((typeof artOr==='function')?artOr(i.name,'','sm'):'')+'</span>';
      var lab = i.kind==='base' ? ('magic '+i.name) : i.kind==='jewel' ? 'any jewel' : i.name;
      return '<span class="cn-rs-ing '+(i.have?'cn-has':'cn-needs')+'" title="'+(i.have?'have ':'need ')+_askEsc(lab)+'">'+ic+(i.have?'<span class="cn-rs-tick">✓</span>':'')+'</span>';
    }
    return '<span class="cn-need-n">'+(p.awayN||1)+' more to go</span><span class="cn-recst">'+p.recipe.map(ing).join('')+'</span>';
  }
