    var rar = (typeof _artRarity==='function') ? _artRarity(p.name) : '';
    var glow = (typeof _Q_HEX!=='undefined' && _Q_HEX[rar]) ? _Q_HEX[rar] : '#ffa800';  // in-game palette, keyed by _artRarity
    // the tile's main image = the FINISHED crafted item (the result), rarity-glowing — not the gem.
    // Crafted jackpots resolve to their base sprite (Blood Gloves → leather gloves, etc.).
    var icon = p.kind==='craft' ? ((typeof artOr==='function')?artOr(p.name,'🔨','sm'):'🔨') : '📜';
    var star = p.beats?(' <span class="cn-star" title="rivals/beats '+_askEsc(p.beats)+'">★</span>'):'';
    // recipe rendered as ART CHIPS (no truncation): runeword = the rune sequence as icons;
    // craft = slot glyph + Perfect gem icon + slot rune icon (+ the throwaway jewel).
    var recipe;
