    + (_cnFocus
        ? (tp.close.length ? '<div class="cn-focusnote">🎯 <b>Sandbox focus</b> — showing only what these ingredients make. <span style="opacity:.72">'+tp.close.length+' near-miss'+(tp.close.length===1?'':'es')+' hidden · clear the sandbox to see “what to grab next”.</span></div>' : '')
        : group('🔜 Almost there — what to grab next', tp.close,'🔜','cn-close'));
  if(!body) body='<div class="cn-empty">Nothing top-tier craftable yet — tally more runes &amp; gems with 📸 intake and this dashboard updates itself.</div>';
  var when=''; try{ when=window.LSR.getItem('d2r_createNowDate')||''; }catch(e){}
  var ai=''; try{ ai=window.LSR.getItem('d2r_createNowAi')||''; }catch(e){}
  var aiBanner = ai ? ('<div class="cn-ai">💡 <b>Today’s pick:</b> '+_askMd(ai)+'</div>') : '';
