    Object.keys(pv.runes).forEach(function(k){ if(pv.runes[k]>0) chips.push(pvArt(k,'rune')+_askEsc(k)+(pv.runes[k]>1?(' ×'+pv.runes[k]):'')); });
    Object.keys(pv.gems).forEach(function(k){ if(pv.gems[k]>0) chips.push(pvArt(k,'gem')+_askEsc(k)+(pv.gems[k]>1?(' ×'+pv.gems[k]):'')); });
    Object.keys(pv.bases||{}).forEach(function(k){ if(pv.bases[k]>0) chips.push(pvArt(k,'base')+'magic '+_askEsc(k)+' base'); });
    Object.keys(pv.jewels||{}).forEach(function(k){ if(pv.jewels[k]>0) chips.push(pvArt(k,'jewel')+_askEsc(k)+(pv.jewels[k]>1?(' ×'+pv.jewels[k]):'')); });
    pvBar='<div class="cn-preview"><div class="cn-pv-note">🧪 <b>Preview</b> — simulating extra runes, gems &amp; magic bases on a <b>sandbox</b>. Your real tallies &amp; every other section are <b>untouched</b>. Toggle off to return to your real stash.</div>'
      +'<div class="cn-pv-row"><button class="cn-pv-add" onclick="window._pvMenuOpen=!window._pvMenuOpen;window.renderCreateNow()">➕ Add item '+(menuOpen?'▲':'▼')+'</button>'
      +(chips.length?'<button class="cn-pv-clear" onclick="window.previewClear()">✕ clear sandbox</button>':'')+'</div>'
