const SUN_CUBE_IMG = 'art/horadric_cube_graphic.png';
const _SUN_IMM = {physical:'imm-phys',poison:'imm-pois',lightning:'imm-light',cold:'imm-cold',fire:'imm-fire',magic:'imm-magic'};
function _sunIng(name, route){
  const esc = String(name).replace(/'/g,"\\'");
  const attr = String(name).replace(/"/g,'&quot;');
  const click = route ? ` onclick="event.stopPropagation();window.openDrop('${esc}')" title="open ${attr} card"` : '';
  return `<span class="sun-ing${route?' route':''}" data-arttip="${attr}"${click}>${nameLogo(name)}${name}</span>`;
}
function renderSunderRecipes(){
  const grid = document.getElementById('sunder-recipe-grid');
  if (!grid) return;
  grid.innerHTML = SUNDER_RECIPES.map((s) => {
    const esc = s.n.replace(/'/g,"\\'");
    const attr = s.n.replace(/"/g,'&quot;');
    const pill = _SUN_IMM[s.el] || 'imm-phys';
    const shardIng = s.shards.map((sh) => _sunIng(sh, true)).join('<span class="sun-plus">+</span>');
    const cc = (typeof SUNDER_CHARMS !== 'undefined') ? (SUNDER_CHARMS.find(c => c.n === s.n) || {}) : {};
    const emoji = cc.emoji || '🔮';
    const best = cc.build ? (cc.star ? '⭐ ' + cc.build : cc.build) : s.best;
    return `<details class="sun-recipe sun-tile" data-charm="${attr}">
      <summary>
        <span class="sun-tile-emblem" data-arttip="${attr}">${artOr(s.n, '<span class="ct-emoji">'+emoji+'</span>', 'lg')}</span>
        <span class="sun-tile-id">
          <span class="sun-charm" data-arttip="${attr}" onclick="event.preventDefault();event.stopPropagation();window.openDrop('${esc}')" title="open ${attr} ID card">${s.n}</span>
          <span class="sun-tile-meta"><span class="sun-pill ${pill}">breaks ${s.breaks}</span><span class="sun-tile-best">best for ${best}</span></span>
        </span>
        <span class="sun-chev" aria-hidden="true">▾</span>
      </summary>
      <div class="sun-body">
        <div class="sun-formula">
          <img class="sun-cube" src="${SUN_CUBE_IMG}" alt="Horadric Cube" loading="lazy" title="Cube these together in the Horadric Cube" onerror="this.classList.add('fail')">
          ${_sunIng('Latent ' + s.n, false)}
          <span class="sun-plus">+</span>${_sunIng(s.gem, false)}
          <span class="sun-plus">+</span>${_sunIng(s.rune + ' Rune', true)}
          <span class="sun-plus">+</span>${shardIng}
          <span class="sun-arrow">&rarr;</span><span class="sun-renewed" data-arttip="Renewed ${attr}">${nameLogo(s.n)}Renewed ${s.n}</span>
        </div>
        <div class="sun-note">Sunders <span class="${pill}">${s.breaks.toLowerCase()}</span> immunity to ~95% resist . best for <span class="sun-best">${s.best}</span>. Renewing re-rolls all stats - re-cube for the best roll. Only ONE Sunder active at a time.</div>
      </div>
    </details>`;
  }).join('');
}
window.renderSunderRecipes = renderSunderRecipes;
window.openSunderRecipes = function(charm){
  if (window.switchTab) window.switchTab('tools');
  const card = document.getElementById('sunder-recipe-card');
  if (card){ card.classList.remove('collapsed'); const h=card.querySelector('.boss-header'); if(h) h.setAttribute('aria-expanded','true'); }
  // When routed for a SPECIFIC charm (per-charm recipe search), expand + scroll
  // that charm's row so "renew black cleft" lands on Black Cleft, not the
  // top-of-grid Bone Break. No charm -> just open the card (collapsed grid).
  const row = charm ? document.querySelector('#sunder-recipe-grid details.sun-recipe[data-charm="' + String(charm).replace(/"/g,'&quot;') + '"]') : null;
  if (row){
    document.querySelectorAll('#sunder-recipe-grid details.sun-recipe[open]').forEach((d) => { if (d !== row) d.removeAttribute('open'); });
    row.setAttribute('open','');
    row.scrollIntoView({behavior:'smooth',block:'center'});
  } else if (card){
    card.scrollIntoView({behavior:'smooth',block:'start'});
  }
};

