  if (typeof _codexSetMember === 'function'){ var _cm = _codexSetMember(nm); if (_cm) return { artName: nm, desc: _setPieceTipHtml({ base:_cm.name, slot:_cm.slot, set:{ name:_cm.setName, pieces:new Array(_cm.pieceCount) } }), rich: true }; }
