function toggleUberBoss(id){
  const card = document.getElementById('uberboss-' + id);
  if (!card) return;
  const body = card.querySelector('.ubc-body');
  const head = card.querySelector('.ubc-head');
  if (!body) return;
  if (body.hasAttribute('hidden')) { body.removeAttribute('hidden'); card.classList.add('open'); if (head) head.setAttribute('aria-expanded', 'true'); }
  else { body.setAttribute('hidden', ''); card.classList.remove('open'); if (head) head.setAttribute('aria-expanded', 'false'); }
}
window.toggleUberBoss = toggleUberBoss;
function jumpToUberBoss(id){
  if (window.switchTab) window.switchTab('ancients');
  setTimeout(function(){
    const card = document.getElementById('uberboss-' + id);
    if (!card) return;
    const sec = card.closest('.event-card-body');
    if (sec && sec.hasAttribute('hidden')) { const ec = sec.closest('.event-card'); if (ec && window.toggleEventCard) window.toggleEventCard(ec.id); }
    const body = card.querySelector('.ubc-body');
    if (body && body.hasAttribute('hidden')) toggleUberBoss(id);
    card.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }, 120);
}
