// Import a pasted tally. Accepts JSON ({"Key of Terror":3,…}) or "Full name: count"
// lines. Full material names are matched case-insensitively; replaces the stash.
async function importMaterialTally(){
  const ta = document.getElementById('material-import-box');
  const status = document.getElementById('material-import-status');
  const setStatus = (msg) => { if (status) status.textContent = msg; };
  if (!ta) return;
  const raw = (ta.value || '').trim();
  if (!raw){ setStatus('Paste a tally first.'); return; }
  const byLc = {}; MATERIALS.forEach((m) => { byLc[m.n.toLowerCase()] = m.n; });
  const next = {};
  let parsed = null;
  try { parsed = JSON.parse(raw); } catch (e) {}
  if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)){
    Object.keys(parsed).forEach((k) => {
      const canon = byLc[String(k).toLowerCase().trim()];
      const v = parseInt(parsed[k], 10);
      if (canon && isFinite(v) && v > 0) next[canon] = v;
    });
  } else {
    MATERIALS.forEach((m) => {
      const re = new RegExp(m.n.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\D*?(\\d+)', 'i');
      const mm = re.exec(raw);
      if (mm){ const v = parseInt(mm[1], 10); if (isFinite(v) && v > 0) next[m.n] = v; }
    });
  }
  const n = Object.keys(next).length;
  if (!n){ setStatus('No valid materials found — check the format.'); return; }
  if (Object.keys(materialStash).length && !(await uiConfirm('Replace your current materials tally with this import?'))) { setStatus('Import cancelled.'); return; }
  materialStash = next;
  persist();
  renderMaterialStash();
  const total = Object.values(next).reduce((a, b) => a + b, 0);
  setStatus(`Loaded ${n} material types (${total} total).`);
  ta.value = '';
}
window.importMaterialTally = importMaterialTally;

// v256: 1-photo AI materials intake — screenshot your keys / organs / essences /
// statues / shards → Claude vision counts each → counts ADD to your materials tally.
window.materialIntake = async function(files){
  var report = document.getElementById('material-intake-report');
  if (!files || !files.length) return;
  window._aiIntakeStart('material-stash-grid','reading your special materials','the AI is counting keys, organs, essences & statues');
  function downscale(file){
    return new Promise(function(resolve, reject){
      var img=new Image(), url=URL.createObjectURL(file);
      img.onload=function(){
        var MAX=1568, scale=Math.min(1, MAX/Math.max(img.width,img.height));
        var c=document.createElement('canvas');
        c.width=Math.round(img.width*scale); c.height=Math.round(img.height*scale);
        c.getContext('2d').drawImage(img,0,0,c.width,c.height);
        URL.revokeObjectURL(url);
        resolve(c.toDataURL('image/jpeg',0.85).split(',')[1]);
      };
      img.onerror=reject; img.src=url;
    });
  }
  var byLc = {}, statueByLc = {}, vocab = [];
  try { MATERIALS.forEach(function(m){ byLc[m.n.toLowerCase()] = m.n; vocab.push(m.n); }); } catch(e){}
  // Colossal Statues are a COLLECTED tracker (Set), not a count stash — fold them into
  // the same photo: a detected statue gets marked collected.
  try { COLOSSAL_STATUES.forEach(function(s){ statueByLc[s.n.toLowerCase()] = s.n; vocab.push(s.n); }); } catch(e){}
  var added={}, statuesAdded=[], total=0, errors=0;
  for (var i=0;i<files.length;i++){
    try{
      var b64=await _tallyPrepImage(files[i]);
      var t=await _tallyRead(b64, vocab);
      if(t===null){ errors++; continue; }
      Object.keys(t).forEach(function(k){
        var lc = String(k).toLowerCase().trim();
        if (byLc[lc]){ var canon=byLc[lc]; var c=parseInt(t[k],10); if(isFinite(c)&&c>0){ materialStash[canon]=(parseInt(materialStash[canon],10)||0)+c; added[canon]=(added[canon]||0)+c; total+=c; } }
        else if (statueByLc[lc]){ var sn=statueByLc[lc]; var sc=parseInt(t[k],10); if(isFinite(sc)&&sc>0){ materialStash[sn]=(parseInt(materialStash[sn],10)||0)+sc; added[sn]=(added[sn]||0)+sc; total+=sc; } try { if(!statues.has(sn)){ statues.add(sn); statuesAdded.push(sn); } } catch(e){} }
      });
    }catch(e){ errors++; }
  }
  persist(); renderMaterialStash(); if (typeof renderStatueTracker==='function') renderStatueTracker();
  window._aiIntakeStop('material-stash-grid');
  if (report){ report.hidden=false;
    var names=Object.keys(added);
    if (names.length || statuesAdded.length){
      var parts=[];
      if (names.length) parts.push('<strong>'+total+' material'+(total===1?'':'s')+'</strong> ('+names.sort().map(function(k){return k+' ×'+added[k];}).join(' · ')+')');
      if (statuesAdded.length) parts.push('<strong>'+statuesAdded.length+' Colossal Statue'+(statuesAdded.length===1?'':'s')+'</strong> marked collected ('+statuesAdded.sort().join(' · ')+')');
      report.innerHTML='🪄 tallied '+parts.join(' · ')
        + (errors?' · <span style="color:var(--hell,#ff4040)">'+errors+' image error'+(errors===1?'':'s')+'</span>':'')
        + '<div style="color:var(--text-dim);font-size:11px;margin-top:5px">Best-effort read — eyeball the grid below and nudge any with −/+. Re-run adds again, so clear first for a fresh total.</div>';
    } else {
      report.innerHTML='No materials read'+(errors?' ('+errors+' image error'+(errors===1?'':'s')+')':'')+'. Try a clearer, closer screenshot of your keys / organs / essences / statues.';
    }
  }
};

function renderStatueTracker() {
  $("statue-tracker").innerHTML = STATUE_LIST.map(s => {
    const en = s.n.replace(/'/g,"\\'");
    const done = statues.has(s.n);
    // Three distinct click zones so every tile behaves identically:
    //   • the ✓ badge (and the tile background) toggles the collect glow/tally
    //   • the statue name routes to its statue ID card (openDrop)
    //   • the boss "from" row routes to that boss's ID card (openBossDetail)
    return `<div class="statue-card ${done?'collected':''}" onclick="toggleStatue('${en}')" title="click to mark collected">
    <button type="button" class="statue-check" title="${done?'collected — click to clear':'mark collected'}" onclick="event.stopPropagation();toggleStatue('${en}')">${done?'✓':''}</button>
    <div class="statue-card-name zd-item-click" style="cursor:pointer;display:flex;align-items:center;gap:6px" title="open ${s.n} ID card" onclick="event.stopPropagation();window.openDrop('${en}')">${artOr(s.n,artOr('Colossal Ancient Statue','👑','sm'),'sm')}<span>${s.n} <span style="font-size:10px;color:var(--text-dim);font-weight:normal">ID →</span></span></div>
    <div class="statue-card-from zd-item-click" style="cursor:pointer;display:flex;align-items:center;gap:5px" title="open ${s.boss}'s boss ID card" onclick="event.stopPropagation();window.openBossDetail&&window.openBossDetail('${s.bossId}')">${artOr(s.boss,s.fromGlyph||'',('sm'))}<span>${s.from} <span style="font-size:10px;color:var(--text-dim);font-weight:normal">→</span></span></div>
  </div>`;
  }).join("");
  const pct = (statues.size / 5) * 100;
  $("statue-fill").style.width = pct + "%";
  $("statue-text").textContent = `${statues.size} / 5`;
}
function toggleStatue(name) {
  if (statues.has(name)) statues.delete(name);
  else statues.add(name);
  persist();
  renderStatueTracker();
  // v42 structural fix (CC find): toggleStatue was missing its closing }, swallowing
  // ~80 lines of code (keydown listener, shortcut-hint, search highlighting, jumpToBossItem)
  // into its function body as dead code. Same code is duplicated at top level (lines ~5042+),
  // which is what actually runs. Removed the buried duplicate, properly closed toggleStatue.
  renderTzZones();
  renderSetTracker();
}
window.toggleStatue = toggleStatue;

function switchTab(name) {
  // v504 — guard an UNKNOWN tab id (a stale/typo'd URL hash like #calculator vs #calc) so we no-op
  // gracefully instead of throwing "Cannot read null.classList" and breaking the render.
  var _tabBtn = document.querySelector(`.tab[data-tab="${name}"]`), _tabEl = $("tab-"+name);
  if (!_tabBtn || !_tabEl) return;
  document.querySelectorAll(".tab").forEach(x => x.classList.remove("active"));
  if (name === "bosses" && activeItem) setTimeout(() => setActiveItem(activeItem), 50);

  document.querySelectorAll(".tab-content").forEach(x => x.classList.remove("active"));
  _tabBtn.classList.add("active");
  _tabEl.classList.add("active");
  // v607 — glide the tab in (transform/opacity only; class self-removes so re-entry replays)
  try { _tabEl.classList.remove("tab-in"); void _tabEl.offsetWidth; _tabEl.classList.add("tab-in"); setTimeout(function(){ _tabEl.classList.remove("tab-in"); }, 400); } catch(e){}
  // v28: ensure data-boss-id is set on TZ zones when tab becomes visible
  if (name === "tz" && typeof tagTzZonesWithBossId === "function") tagTzZonesWithBossId();
  if (name === "tztracker" && typeof tzTrackerOnShow === "function") tzTrackerOnShow();
  if (name === "forge" && typeof renderForge === "function") renderForge();   // v470 — recompute the task plan every time the Forge tab opens
  if (name === "tools" && typeof window.refreshLootFilterCount === "function") window.refreshLootFilterCount();   // v535 — live loot-filter base count
  if (name === "tools" && typeof window.renderSmartInsights === "function") window.renderSmartInsights();          // v543 — smart Chronicle insights
  if (name === "session" && typeof window.renderSessionCockpit === "function") window.renderSessionCockpit();      // v686 — cockpit recomputes on every open (same doctrine as the Forge)
}

// ===== TZ TRACKER (live terror-zone tab) =====
// Reads the live rotation from the same-origin /api/tz Pages Function (which
// proxies d2runewizard server-side). Only the HUNTABLE zones — the exact set
// the Telegram alert calls out — are clickable and route to their bible card;
// everything else renders dimmed. Offline (file://) shows a graceful note, so
// the suite's "no console errors" checks never see a failed fetch.
const TZ_HUNT = [
  { id:'mephisto', m:['durance of hate'],                                          label:'Mephisto',           emoji:'💧', why:'Act 3 boss — SoJ · Shako · deep unique pool',        go:()=>window.openBossDetail&&openBossDetail('mephisto') },
  { id:'duriel',   m:['tal rasha'],                                                label:'Duriel',             emoji:'🪲', why:'Act 2 tomb boss — fast, sparkly chests en route',      go:()=>window.openBossDetail&&openBossDetail('duriel') },
  { id:'andariel', m:['catacombs','cathedral'],                                    label:'Andariel',           emoji:'🕷️', why:'Act 1 boss — easy SoJ / Shako resets',                 go:()=>window.openBossDetail&&openBossDetail('andariel') },
  { id:'diablo',   m:['chaos sanctuary'],                                          label:'Diablo',             emoji:'😈', why:'Act 4 boss — full clear, Annihilus camp',             go:()=>window.openBossDetail&&openBossDetail('diablo') },
  { id:'baal',     m:['worldstone keep','throne of destruction','worldstone chamber'], label:'Baal',           emoji:'👹', why:'Act 5 boss — WSK pop + throne waves',                 go:()=>window.openBossDetail&&openBossDetail('baal') },
  { id:'travincal',m:['travincal'],                                                label:'Travincal',          emoji:'💰', why:'Council — #1 gold dump + runes + TC85',               go:()=>window.openBossDetail&&openBossDetail('travincal') },
  { id:'countess', m:['forgotten tower','tower cellar'],                           label:'Countess',           emoji:'🔑', why:'Dedicated rune table + Key of Terror',                go:()=>window.openBossDetail&&openBossDetail('countess') },
  { id:'pindle',   m:['nihlathak','halls of vaught','halls of anguish','halls of pain'], label:'Pindle / Nihlathak', emoji:'❄️', why:'Pindle = fastest exp + loot per second',         go:()=>window.openBossDetail&&openBossDetail('nihl') },
  { id:'cows',     m:['cow level','moo moo farm'],                                 label:'Secret Cow Level',   emoji:'🐄', why:'Rune farming + insane density',                       go:()=>window.openBossDetail&&openBossDetail('cow') },
  { id:'pit',      m:['the pit','pit level'],                                      label:'The Pit',            emoji:'🕳️', why:'mlvl 85 · TC85 — best non-boss item ceiling',         go:()=>window.navTo&&navTo('tz') },
  { id:'eldritch', m:['bloody foothills','frigid highlands','abaddon'],            label:'Eldritch / Shenk',   emoji:'🧊', why:'DClone camp · huge packs = bulk drops',               go:()=>window.navTo&&navTo('tz') },
  { id:'arcane',   m:['arcane sanctuary'],                                         label:'Arcane Sanctuary',   emoji:'🌀', why:'Summoner · wide-open density',                        go:()=>window.navTo&&navTo('tz') },
  { id:'river',    m:['river of flame'],                                           label:'River of Flame',     emoji:'🔥', why:'Hephasto · TZ aura cap (lvl 12)',                     go:()=>window.navTo&&navTo('tz') },
  { id:'flayer',   m:['flayer dungeon'],                                           label:'Flayer Dungeon',     emoji:'🪓', why:'Endugu · mlvl 96 + TC85 when terror’d',          go:()=>window.navTo&&navTo('tz') },
  { id:'crystal',  m:['crystalline passage','frozen river'],                       label:'Crystalline Passage',emoji:'🧊', why:'Frozenstein · dense cold-imm pack',                   go:()=>window.navTo&&navTo('tz') },
];
function tzHuntMatch(zoneName){
  const z = String(zoneName||'').toLowerCase();
  for (const h of TZ_HUNT){ for (const n of h.m){ if (z.indexOf(n) !== -1) return h; } }
  return null;
}
function tzGo(id){ const h = TZ_HUNT.find(x => x.id === id); if (h && h.go) h.go(); }
window.tzGo = tzGo; window.tzHuntMatch = tzHuntMatch; window.TZ_HUNT = TZ_HUNT;

function _tzEsc(t){ return String(t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
function tzZoneRowHtml(zoneName){
  if (!zoneName) return '<div class="tzt-zone tzt-filler"><span class="tzt-z-emoji">·</span><span class="tzt-z-name">(unknown)</span></div>';
  const h = tzHuntMatch(zoneName);
  if (h){
    return '<div class="tzt-zone tzt-hunt" role="button" tabindex="0" data-tz-hunt="'+h.id+'" '
      + 'onclick="window.tzGo(\''+h.id+'\')" onkeydown="if(event.key===\'Enter\'||event.key===\' \'){event.preventDefault();window.tzGo(\''+h.id+'\')}" '
      + 'title="hunt → '+_tzEsc(h.label)+'">'
      + '<span class="tzt-z-emoji">'+h.emoji+'</span>'
      + '<span class="tzt-z-name">'+_tzEsc(zoneName)+'</span>'
      + '<span class="tzt-z-go">'+_tzEsc(h.label)+' →</span>'
      + '<span class="tzt-z-why">'+_tzEsc(h.why)+'</span></div>';
  }
  return '<div class="tzt-zone tzt-filler"><span class="tzt-z-emoji">😴</span>'
    + '<span class="tzt-z-name">'+_tzEsc(zoneName)+'</span>'
    + '<span class="tzt-z-skip">not a hunt zone — sit this one out</span></div>';
}
function renderTzTracker(data){
  const body = document.getElementById('tztracker-body');
  if (!body) return;
  if (data === 'offline'){
    body.innerHTML = '<div class="tzt-offline">📡 Live rotation needs the online site — open '
      + '<a href="https://bull-4-u.com/d2r/" target="_blank" rel="noopener">bull-4-u.com/d2r</a> to see the current terror zone.</div>';
    return;
  }
  if (data === 'error'){
    body.innerHTML = '<div class="tzt-offline">⚠️ Couldn’t reach the live tracker right now — hit ↻ Refresh in a moment.</div>';
    return;
  }
  body.innerHTML =
    '<div class="tzt-slot tzt-now"><div class="tzt-slot-label"><span class="tzt-live-dot"></span> LIVE NOW</div>'+tzZoneRowHtml(data.current)+'</div>'
    + '<div class="tzt-slot tzt-next"><div class="tzt-slot-label">⏭️ NEXT · ~30 MIN</div>'+tzZoneRowHtml(data.next)+'</div>';
  const u = document.getElementById('tzt-updated');
  if (u){ try { u.textContent = data.ts ? ('updated '+new Date(data.ts).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})) : ''; } catch(e){ u.textContent=''; } }
}
window.renderTzTracker = renderTzTracker;

function renderTzHistory(history){
  const el = document.getElementById('tztracker-body') && document.getElementById('tzt-history-body');
  if (!el) return;
  const cnt = document.getElementById('tzt-history-count');
  if (!history || !history.length){
    el.innerHTML = '<div class="tzt-hist-empty">📡 The 48-hour log is recording — it fills as rotations roll in (24/7, even while you’re away). Check back soon.</div>';
    if (cnt) cnt.textContent = '';
    return;
  }
  const nowSlot = Math.floor(Date.now() / 1800000) * 1800000;
  let lastDay = '', out = '';
  for (const h of history){
    const d = new Date(h.slot);
    const day = d.toLocaleDateString([], { weekday:'long', month:'short', day:'numeric' });
    if (day !== lastDay){ out += '<div class="tzt-hist-day">'+day+'</div>'; lastDay = day; }
    const time = d.toLocaleTimeString([], { hour:'2-digit', minute:'2-digit' });
    const hu = tzHuntMatch(h.zone);
    const isNow = h.slot === nowSlot;
    if (hu){
      out += '<div class="tzt-hist-row tzt-hunt'+(isNow?' tzt-now':'')+'" role="button" tabindex="0" '
        + 'onclick="window.tzGo(\''+hu.id+'\')" onkeydown="if(event.key===\'Enter\'){window.tzGo(\''+hu.id+'\')}" title="hunt → '+_tzEsc(hu.label)+'">'
        + '<span class="tzt-hist-time">'+time+'</span><span class="tzt-hist-emoji">'+hu.emoji+'</span>'
        + '<span class="tzt-hist-zone">'+_tzEsc(h.zone)+'</span><span class="tzt-hist-go">'+_tzEsc(hu.label)+' →</span></div>';
    } else {
      out += '<div class="tzt-hist-row tzt-filler'+(isNow?' tzt-now':'')+'">'
        + '<span class="tzt-hist-time">'+time+'</span><span class="tzt-hist-emoji">·</span>'
        + '<span class="tzt-hist-zone">'+_tzEsc(h.zone)+'</span><span></span></div>';
    }
  }
  el.innerHTML = out;
  if (cnt){ const huntable = history.filter(h => tzHuntMatch(h.zone)).length; cnt.textContent = history.length+' slots · '+huntable+' huntable'; }
}
window.renderTzHistory = renderTzHistory;

let _tzLast = null, _tzFetching = false, _tzTimer = null;
function _tzHistCache(read, val){
  try {
    if (read){ const r = localStorage.getItem('d2r_tz_hist_cache'); return r ? JSON.parse(r) : []; }
    localStorage.setItem('d2r_tz_hist_cache', JSON.stringify(val || []));
  } catch(e){ return []; }
}
async function refreshTzTracker(manual){
  if (_tzFetching) return;
  if (location.protocol === 'file:'){ renderTzTracker('offline'); renderTzHistory(_tzHistCache(true)); return; }
  _tzFetching = true;
  try {
    const r = await fetch('/api/tz', { cache: 'no-store' });
    if (!r.ok) throw new Error('http '+r.status);
    const data = await r.json();
    if (data && (data.current || data.next)){ _tzLast = data; renderTzTracker(data); }
    else { renderTzTracker(_tzLast || 'error'); }
    if (data && Array.isArray(data.history)){ _tzHistCache(false, data.history); renderTzHistory(data.history); }
  } catch(e){ renderTzTracker(_tzLast || 'error'); renderTzHistory(_tzHistCache(true)); }
  finally { _tzFetching = false; }
}
window.refreshTzTracker = refreshTzTracker;
window._tzPeek = function(){ return _tzLast; };            // v686 — session cockpit reads the tracker's last fetch
window.tzZoneRowHtml = tzZoneRowHtml;                       // v686 — cockpit reuses the tracker's zone row renderer

function tzTrackerOnShow(){
  refreshTzTracker(false);
  if (_tzTimer){ clearInterval(_tzTimer); _tzTimer = null; }
  _tzTimer = setInterval(function(){
    const panel = document.getElementById('tab-tztracker');
    if (panel && panel.classList.contains('active')) refreshTzTracker(false);
    else { clearInterval(_tzTimer); _tzTimer = null; }
  }, 120000);
}
window.tzTrackerOnShow = tzTrackerOnShow;

