$("players").oninput = () => { players = parseInt($("players").value); persist(); updatePlayers(); renderHero(); renderBossNav(); renderBossCards(); if (activeItemDetail) renderItemDetailCard(activeItemDetail); if (typeof activeBossId !== "undefined" && activeBossId) renderBossDetailCard(activeBossId); renderWishlistHuntPath(); };
