// v551 — HD-ART NAV ICONS. Shiny in-game sprites replace the flat emoji on BOTH the main tabs AND the compass
// navigator (Konyo: "fancy HD art replicating the title name"). Centralised map → swap any single icon in one place.
// Each <img> keeps its original emoji in data-emoji and falls back to it if the art 404s, so the nav never breaks.
var TAB_ICON = {
  main:'logo_scroll.png', bosses:'hd_perfect_skull.png', calc:'hd_perfect_diamond.png',
  tz:'essenceterror_graphic.png', tztracker:'mr_hellfiretorch.png', runes:'hd_ber_rune.png',
  rotw:'harlequincrest_graphic.png', funi:'crownofages_graphic.png', fsets:'talrashasguardianship_graphic.png', ancients:'flamerift_graphic.png', endgame:'mr_hellfiretorch.png',
  binds:'mr_annihilus.png', ref:'hd_grimoire.png', tools:'horadric_cube_graphic.png', forge:'hd_war_hammer.png'
};
window._tabIcoFail = function(img){ try { var e=img.getAttribute('data-emoji')||'•'; var s=document.createElement('span'); s.className=(img.className||'').replace(/\btab-hdico\b/,'').trim(); s.textContent=e; img.replaceWith(s); } catch(err){} };
function _tabIcoImg(tab, emoji, cls){
  var f=TAB_ICON[tab];
  if(!f) return '<span class="'+(cls||'')+'">'+(emoji||'•')+'</span>';
  return '<img class="'+(cls||'')+' tab-hdico" src="art/'+f+'" alt="" loading="lazy" data-emoji="'+(emoji||'•')+'" onerror="window._tabIcoFail&&window._tabIcoFail(this)">';
}
function applyTabIcons(){
  document.querySelectorAll('.tabs .tab').forEach(function(t){
    var tab=t.dataset.tab; if(!TAB_ICON[tab]) return;
    if(t.querySelector('img.tab-hdico')) return;   // idempotent
    var parts=(t.textContent||'').trim().split(/\s+/);
    var emoji=parts[0]||'•', label=parts.slice(1).join(' ')||tab;
    t.dataset.emoji=emoji; t.dataset.label=label;
    t.innerHTML=_tabIcoImg(tab, emoji, 'tab-ic-img')+'<span class="tab-lbl">'+label+'</span>';
  });
}
window.applyTabIcons=applyTabIcons;
// === v59: floating navigation compass widget ===
// Persistent maneuvering control (bottom-right) so any tab / back-to-top is one
// tap away regardless of scroll depth — no scrolling back up to the sticky tab bar.
function buildNavWidget() {
  if (document.getElementById("nav-widget")) return;
  try { applyTabIcons(); } catch(e){}   // v551 — HD icons on the main tabs before we read them for the compass
  const tabs = [...document.querySelectorAll(".tabs .tab")].map(t => {
    const emoji = t.dataset.emoji || (t.textContent || "").trim().split(/\s+/)[0] || "•";
    const label = t.dataset.label || (t.textContent || "").trim().split(/\s+/).slice(1).join(" ") || t.dataset.tab;
    return { tab: t.dataset.tab, ic: emoji, label };
  });
  const w = document.createElement("div");
  w.className = "nav-widget";
  w.id = "nav-widget";
  const chips = tabs.map(t =>
    `<div class="nav-chip" role="button" tabindex="0" data-nav="${t.tab}" onclick="navTo('${t.tab}')">`
    + `${_tabIcoImg(t.tab, t.ic, "nav-ic")}<span>${t.label}</span></div>`).join("");
  w.innerHTML =
    `<div class="nav-panel" id="nav-panel">`
    + `<div class="nav-panel-title">Navigate</div>`
    + chips
    + `<div class="nav-chip nav-top" role="button" tabindex="0" onclick="navTop()">`
    + `<span class="nav-ic">⬆️</span><span>Back to top</span></div>`
    + `</div>`
    + `<button class="nav-fab" id="nav-fab" aria-label="Navigation menu" title="Navigate" onclick="toggleNavPanel(event)">`
    + `<svg class="nav-compass" viewBox="0 0 48 48" aria-hidden="true" focusable="false">`
    + `<circle class="nc-ring" cx="24" cy="24" r="20"/>`
    + `<g class="nc-ticks"><line x1="24" y1="5" x2="24" y2="10"/><line x1="24" y1="38" x2="24" y2="43"/>`
    + `<line x1="5" y1="24" x2="10" y2="24"/><line x1="38" y1="24" x2="43" y2="24"/></g>`
    + `<g class="nc-needle"><polygon class="nc-n" points="24,8 28.5,24 24,21.5 19.5,24"/>`
    + `<polygon class="nc-s" points="24,40 19.5,24 24,26.5 28.5,24"/></g>`
    + `<circle class="nc-hub" cx="24" cy="24" r="2.6"/>`
    + `</svg></button>`;
  document.body.appendChild(w);
  // keyboard activation: Enter / Space fire the focused chip or FAB (role=button a11y)
  w.addEventListener("keydown", (e) => {
    if (e.key !== "Enter" && e.key !== " " && e.key !== "Spacebar") return;
    const t = e.target.closest(".nav-chip, .nav-fab");
    if (t) { e.preventDefault(); t.click(); }
  });
  // click-outside closes the panel
  document.addEventListener("click", (e) => {
    if (w.classList.contains("open") && !w.contains(e.target)) w.classList.remove("open");
  });
  const active = document.querySelector(".tab.active")?.dataset.tab;
  if (active) syncNavWidget(active);
}
function toggleNavPanel(e) { if (e) e.stopPropagation(); document.getElementById("nav-widget")?.classList.toggle("open"); }
// A user-initiated tab switch is a CLEAN switch: dismiss any open detail overlay,
// and returning to the bosses home drops the previously-farmed item highlight so
// you land on a fresh boss list (not the "stuck" filtered view) — then scroll to top.
function navClean(name) {
  if (typeof window.closeDrop === "function") window.closeDrop();
  if (typeof window.closeItemDetail === "function") window.closeItemDetail();
  if (typeof window.clearActiveBoss === "function") window.clearActiveBoss({ noScroll: true });
  if (name === "bosses" && typeof activeItem !== "undefined" && activeItem && typeof window.clearActiveItem === "function") window.clearActiveItem();
  window.switchTab(name);
  window.scrollTo({ top: 0, behavior: "smooth" });
}
window.navClean = navClean;
function navTo(tab) {
  navClean(tab);
  document.getElementById("nav-widget")?.classList.remove("open");
}
function navTop() {
  window.scrollTo({ top: 0, behavior: "smooth" });
  document.getElementById("nav-widget")?.classList.remove("open");
}
function syncNavWidget(name) {
  document.querySelectorAll("#nav-widget .nav-chip[data-nav]").forEach(c =>
    c.classList.toggle("active", c.getAttribute("data-nav") === name));
}
window.buildNavWidget = buildNavWidget;
window.navTo = navTo; window.navTop = navTop;
window.toggleNavPanel = toggleNavPanel; window.syncNavWidget = syncNavWidget;

