const _mwEsc = s => String(s).replace(/'/g,"\\'");
// Unified click router for any Most-Wanted target: material/rune/item via openDrop,
// section/concept via a clean tab switch. Keeps the board's clicks consistent with
// the rest of the site (no dead ends).
window.mwOpen = function(name, tab){
  if (tab){ if (typeof navClean === "function") navClean(tab); else if (typeof switchTab === "function") switchTab(tab); return; }
  if (name && typeof window.openDrop === "function") window.openDrop(name);
};
window.mwSection = function(boss, tab){
  if (tab){ if (typeof navClean === "function") navClean(tab); else switchTab(tab); return; }
  if (boss){
    if (typeof navClean === "function") navClean("bosses"); else switchTab("bosses");
    setTimeout(() => { if (typeof window.openBossDetail === "function") window.openBossDetail(boss); }, 80);
  }
};
window.mwToggleRw = function(i, ev){
  if (ev) ev.stopPropagation();
  const row = document.querySelector('#most-wanted .mw-row[data-mw="'+i+'"]');
  if (row) row.classList.toggle("open");
};
function renderMostWanted(){
  const host = document.getElementById("most-wanted");
  if (!host) return;
  const tierBadge = e => `<span class="mw-tier mw-tier-${e.dt}" title="community demand tier">${e.dt}</span>`;
  const rotwBadge = e => e.rotw ? ' <span class="mw-rotw-badge" title="Reign of the Warlock — mod-specific chase">ROTW</span>' : '';
  const rows = MW_TOP10.map((e, i) => {
    const isRw = Array.isArray(e.rw) && e.rw.length;
    const caret = isRw ? '<span class="mw-caret">▶</span>' : '';
    const onClick = isRw
      ? `mwToggleRw(${i})`
      : e.tab ? `mwOpen(null,'${_mwEsc(e.tab)}')` : `mwOpen('${_mwEsc(e.drop || e.n)}')`;
    const rwPanel = isRw ? `<div class="mw-rw">
        <div class="mw-rw-lbl">recipe — click any rune to open its card:</div>
        ${e.rw.map(r => `<span class="mw-rune-chip" role="button" tabindex="0" data-arttip="${_mwEsc(r)}" onclick="event.stopPropagation();mwOpen('${_mwEsc(r)}')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();event.stopPropagation();mwOpen('${_mwEsc(r)}');}">${r}</span>`).join("")}
      </div>` : "";
    const aria = isRw ? `aria-expanded="false"` : "";
    return `<li class="mw-row" data-mw="${i}" role="button" tabindex="0" ${aria}
        onclick="${onClick}"
        onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();${onClick};}"
        title="${isRw ? 'show '+e.n+' recipe' : 'open '+e.n}">
      <span class="mw-rank">#${i + 1}</span>
      <span class="mw-main">
        <span class="mw-name">${caret}<span class="mw-art">${artOr(e.drop || e.n, e.ic || '', 'sm')}</span> ${e.n}${rotwBadge(e)}</span>
        <span class="mw-why">${e.why}</span>
      </span>
      ${tierBadge(e)}
      ${rwPanel}
    </li>`;
  }).join("");
  const sections = MW_SECTIONS.map(s => {
    const onHead = s.tab ? `mwSection(null,'${_mwEsc(s.tab)}')` : `mwSection('${_mwEsc(s.boss)}')`;
    const wants = s.wants.map((w, wi) => {
      const wOnClick = w.tab ? `mwOpen(null,'${_mwEsc(w.tab)}')` : `mwOpen('${_mwEsc(w.drop || w.n)}')`;
      return `<span class="mw-want-chip ${wi === 0 ? 'mw-want-1' : ''}" role="button" tabindex="0"
          onclick="${wOnClick}"
          onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();${wOnClick};}"
          title="open ${w.n}">${w.n}</span>`;
    }).join("");
    return `<div class="mw-sec">
      <button class="mw-sec-head" onclick="${onHead}" title="jump to ${s.target}">
        <span class="mw-sec-icon">${s.icon}</span>
        <span class="mw-sec-titles">
          <span class="mw-sec-label">${s.label} · #1 most-wanted</span>
          <span class="mw-sec-target">${s.target} →</span>
        </span>
      </button>
      <div class="mw-sec-note">${s.note}</div>
      <div class="mw-wants">${wants}</div>
    </div>`;
  }).join("");
  host.innerHTML = `
    <h2 class="sec-h mw-title collapsed" onclick="toggleSec(this)">🔥 Most Wanted <span class="mw-sub">community &amp; forum trade demand · diablo.io-style · ROTW-aware</span> <span class="sec-chev">▾</span></h2>
    <div class="sec-body" hidden>
    <div class="mw-note">A separate layer from the Holy Grail: the grail tables rank by <em>game rarity</em> (how hard to find); this ranks by <em>community demand / trade value</em> (what's worth chasing &amp; holding) — they diverge. Demand tiers are an editorial community-consensus call, NOT a drop rate. Every item is clickable → opens its real card.</div>
    <div class="mw-section-label">Top 10 · most-wanted overall</div>
    <ol class="mw-top">${rows}</ol>
    <div class="mw-section-label">#1 most-wanted per act / section</div>
    <div class="mw-sections">${sections}</div>
    </div>`;
}
window.renderMostWanted = renderMostWanted;

// v379 — re-register per-base socketed keepers ("Monarch (4os)", "Colossus Voulge (Larzuk base)"…) from the
// persisted owned set, so after a reload they still resolve their own art + exact max-socket card (not generic).
try { if (typeof owned !== 'undefined' && typeof _ensureSocketBaseEntry === 'function') Array.from(owned).forEach(function(n){ _ensureSocketBaseEntry(n); }); } catch(e){}
// v631 — PROMOTE socket-known base reads out of the 'needs a look' ledger (Konyo's Heavy Crossbow (5os)
// → Mist: the host map SAW it but the planner could not task it, because unknownReads is invisible to
// _ownedBases). A read that parses as '<known base> (Nos)' whose socket count EXACT-FITS an unmade,
// unblocked runeword is not 'unknown' — it is live forge capability: register it as an owned socketed
// base so the planner, vault and capacity ledger all see it. Junk reads (nothing unmade fits) stay put.
// Idempotent; runs at boot and again at every vault-scan finish.
window._promoteUnknownBases = function(){
  var moved=[];
  try {
    if (typeof unknownReads==='undefined' || !unknownReads || !unknownReads.size) return moved;
    Array.from(unknownReads).forEach(function(lbl){
      var m=/^(.+?)\s*\(\s*(\d+)\s*os(?:\s+low base)?\s*\)\s*$/i.exec(String(lbl||'')); if(!m) return;
      var clean=(typeof _qualStrip==='function'?_qualStrip(m[1].trim()):m[1].trim())||m[1].trim();
      clean=clean.replace(/\bKriss\b/g,'Kris').replace(/\bStilleto\b/g,'Stiletto').replace(/\bMithral Point\b/g,'Mithril Point');
      if (typeof BASE_DB==='undefined' || !BASE_DB[clean]) return;
      if (typeof _isRunewordBase==='function' && !_isRunewordBase(clean)) return;
      var ks=parseInt(m[2],10)||0; if(ks<1) return;
      var fits=[];
      try { fits=(_baseUnmadeRunewords(clean, ks)||[]).filter(function(r){ return r && r.s===ks; }); } catch(e){}
      if (!fits.length) return;
      owned.add(lbl);
      try { _ensureSocketBaseEntry(lbl); } catch(e){}
      unknownReads.delete(lbl);
      moved.push(lbl);
    });
    if (moved.length){ try{ persist(); }catch(e){} }
  } catch(e){}
  return moved;
};
