// v321: paint static reference-table item-name spans (merc-gear etc.) their exact in-game rarity
// colour. These spans carry data-arttip with the item name but no rarity class; table.ref-tbl had
// no q-* rules so they read plain cream. Skip any span with an intentional inline colour (uber).
(function _wireRefTblRarity(){
  function go(){
    try {
      document.querySelectorAll('table.ref-tbl td.item-name [data-arttip]').forEach(function(el){
        if (el.style && el.style.color) return;
        var c = (typeof _qHex==='function') ? _qHex(el.getAttribute('data-arttip')) : '';
        if (c) el.style.color = c;
      });
    } catch(e){}
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', go); else go();
})();
