// keyboard shortcuts (v12 enhanced)
document.addEventListener("keydown", (e) => {
  const inInput = ["INPUT","TEXTAREA"].includes(document.activeElement?.tagName);
  if (e.key === "Escape") {
    document.getElementById("help-modal")?.classList.remove("show");
    if (activeItem) clearActiveItem();
    return;
  }
  // Arrow nav within item-grid when focused
  const grid = document.getElementById("item-grid");
  const focused = document.activeElement;
  if (grid && focused?.classList?.contains("item-tile")) {
    const tiles = Array.from(grid.querySelectorAll(".item-tile"));
    const curIdx = tiles.indexOf(focused);
    if (e.key === "ArrowRight" || e.key === "ArrowDown") {
      e.preventDefault();
      const next = tiles[Math.min(tiles.length-1, curIdx+1)];
      next?.focus();
      next?.click();
      return;
    }
    if (e.key === "ArrowLeft" || e.key === "ArrowUp") {
      e.preventDefault();
      const prev = tiles[Math.max(0, curIdx-1)];
      prev?.focus();
      prev?.click();
      return;
    }
    if (e.key === "Enter") {
      e.preventDefault();
      focused?.click();
      $("item-detail")?.scrollIntoView({behavior:"smooth", block:"start"});
      return;
    }
    if (e.key.toLowerCase() === "b" && selectedItem) {
      e.preventDefault();
      switchTab("bosses");
      setActiveItem(selectedItem);
      return;
    }
  }
  if (inInput) return;
  // v202: B works from ANYWHERE once an item is selected/active (was gated behind
  // keyboard-focus on a calc tile — click-selecting then pressing B did nothing)
  if (e.key.toLowerCase() === "b" && !e.shiftKey && (selectedItem || activeItem)) {
    e.preventDefault();
    switchTab("bosses");
    setActiveItem(selectedItem || activeItem);
    return;
  }
  if (e.key === "/" && !e.metaKey && !e.ctrlKey) {
    e.preventDefault();
    switchTab("calc");
    setTimeout(() => $("item-search").focus(), 100);
    return;
  }
  if (e.key === "?") {
    document.getElementById("help-modal")?.classList.add("show");
    return;
  }
  // v282: digit shortcuts follow the visual tab order, skipping the home + TZ-tracker tabs
  // (1=bosses … 0=tools). Keep this IN SYNC with KBD_SHORTCUTS above + the help-modal prose.
  const tabMap = {"1":"bosses","2":"calc","3":"tz","4":"runes","5":"rotw","6":"ancients","7":"endgame","8":"binds","9":"ref","0":"tools"};
  if (tabMap[e.key]) switchTab(tabMap[e.key]);
});

// show shortcut hint briefly on first visit
if (!LS.getItem("d2r_shortcuts_seen")) {
  const sh = $("shortcut-hint");
  if (sh) {
    sh.classList.add("show");
    setTimeout(() => { sh.classList.remove("show"); LS.setItem("d2r_shortcuts_seen", "1"); }, 6000);
  }
}

// v42 restored (was previously buried inside toggleStatue's function body due to the missing-brace
// structural bug; that buried copy was dead code and the only top-level copy lived here originally as
// a duplicate that I incorrectly removed; restored here as the single canonical definition):
// search highlighting — when user searches in calc, find matches in boss tables on switch back.
let lastSearch = "";
$("item-search").addEventListener("input", () => { lastSearch = $("item-search").value; });
// search box can highlight match in boss table after clicking item
window.jumpToBossItem = (itemName, bossId) => {
  // Scope the row search to the TARGET boss. Multi-boss items (e.g. the Shako drops
  // from 11 bosses) previously scrolled to the LAST matching row in the whole
  // document — so clicking pindle's source-chip landed the user on a different
  // boss's row ~4500px away. Prefer the explicit bossId, then the active source boss
  // (set by setActiveItem), and within that boss prefer a visible (non-collapsed) row.
  const bid = bossId || (activeSourceKey ? (activeSourceKey.includes('|') ? activeSourceKey.split('|')[0] : activeSourceKey) : null);
  const scope = bid ? document.getElementById(bid) : null;
  // v341.56 — drop rows are lazy: build + open the target boss's table so its row exists and is visible to scroll to
  if (bid && typeof window._ensureBossRows === 'function') {
    if (window._openDropBosses) window._openDropBosses.add(bid);
    window._ensureBossRows(bid);
    const _jDet = scope && scope.querySelector('.all-drops-details');
    if (_jDet && !_jDet.open) _jDet.open = true;
  }
  const pick = (root) => {
    const rows = [...root.querySelectorAll("tr.clickable")].filter(tr => tr.dataset.item === itemName);
    if (!rows.length) return false;
    rows.forEach(tr => tr.classList.add("search-match-highlight"));
    setTimeout(() => rows.forEach(tr => tr.classList.remove("search-match-highlight")), 1500);
    // Only scroll to a row that is genuinely visible. The full per-boss drop table
    // lives inside a collapsed <details>; scrolling to a row in there is meaningless
    // and would yank the user away from the boss card the caller just scrolled to.
    const visible = rows.find(tr => { const d = tr.closest('details'); return !d || d.open; });
    if (visible) visible.scrollIntoView({behavior:"smooth", block:"center"});
    return true;
  };
  if (!(scope && pick(scope))) pick(document);
  if (scope) { var __cs = function(){ scope.scrollIntoView({behavior:"auto", block:"center"}); }; __cs(); setTimeout(__cs, 400); setTimeout(__cs, 900); }
};

window.exportWishlistAsMarkdown = function() {
  if (!wishlist || wishlist.size === 0) {
    alert('Wishlist is empty. Star some items first (⭐ icon on any item).');
    return;
  }
  const mf = parseInt(document.getElementById('mf')?.value) || 0;
  const items = Array.from(wishlist).map(name => {
    const item = ITEMS.find(i => i.n === name);
    if (!item) return null;
    let bestSrc = null;
    (item.sources || []).forEach(s => {
      if (!s.chance || s.chance < 100) return;
      const adj = effChance(s.chance, s.bossId, s.diffKey);
      const hrs = hoursFor(adj, 0.5, s.kph || 100);
      if (hrs === null) return;
      if (!bestSrc || hrs < bestSrc.hrs) bestSrc = { boss: s.boss, chance: adj, kph: s.kph || 100, hrs };
    });
    return { name, tier: item.tier, qlvl: item.qlvl, tc: item.tc, bestSrc };
  }).filter(Boolean);
  
  // Sort by hours-to-50% ascending (achievable first)
  items.sort((a, b) => (a.bestSrc?.hrs || Infinity) - (b.bestSrc?.hrs || Infinity));
  
  const total50hrs = items.reduce((s, i) => s + (i.bestSrc?.hrs || 0), 0);
  const date = new Date().toISOString().split('T')[0];
  
  let md = `# Konyo Wishlist · ${date}\n\n`;
  md += `**MF**: ${mf}% · **Items**: ${items.length} · **Sum to 50%**: ${total50hrs.toFixed(1)}h (${(total50hrs/24).toFixed(1)}d at this pace)\n\n`;
  md += `| # | Item | Tier | TC | qlvl | Best source | Chance | 50%-runs | ~Hours |\n`;
  md += `|---|---|---|---|---|---|---|---|---|\n`;
  items.forEach((it, idx) => {
    const r50 = it.bestSrc ? Math.ceil(Math.log(.5) / Math.log(1 - 1/it.bestSrc.chance)) : '—';
    const hrs = it.bestSrc ? it.bestSrc.hrs.toFixed(1) + 'h' : '—';
    const chance = it.bestSrc ? `1:${it.bestSrc.chance.toLocaleString()}` : '—';
    md += `| ${idx+1} | ${it.name} | ${it.tier} | ${it.tc} | ${it.qlvl} | ${it.bestSrc?.boss || '—'} | ${chance} | ${r50.toLocaleString ? r50.toLocaleString() : r50} | ${hrs} |\n`;
  });
  md += `\n---\nGenerated by Konyo's D2R Farming Bible v37\n`;
  
  // Copy to clipboard
  navigator.clipboard.writeText(md).then(() => {
    const msg = document.createElement('div');
    msg.style.cssText = 'position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);background:linear-gradient(180deg,#1f1810,#0f0a05);border:2px solid var(--gold-bright);border-radius:10px;padding:20px 30px;color:var(--gold-bright);font-family:var(--mono);font-size:14px;z-index:99999;box-shadow:0 0 40px rgba(240,192,96,.4)';
    msg.innerHTML = `✓ Wishlist markdown copied to clipboard<br><span style="font-size:11px;color:var(--text);opacity:.7">${items.length} items · ${total50hrs.toFixed(1)}h total · paste into Obsidian/Discord</span>`;
    document.body.appendChild(msg);
    setTimeout(() => msg.remove(), 2500);
  }).catch(() => {
    alert('Wishlist markdown:\n\n' + md);
  });
};

