// --- Tab persistence
function _v39_persistActiveTab(name) {
  try { localStorage.setItem('d2r_activeTab', name); } catch(e) {}
}
function _v39_validTabName(name) {
  return name && document.querySelector(`.tab[data-tab="${name}"]`) != null;
}

// Wrap switchTab to persist + sync URL hash
const _v39_origSwitchTab = window.switchTab;
window.switchTab = function(name) {
  // v42 UX route-back: clicking the active tab should scroll to top (iOS-style "return to top")
  const currentActive = document.querySelector('.tab.active')?.getAttribute('data-tab');
  if (currentActive === name) {
    window.scrollTo({ top: 0, behavior: 'smooth' });
    return;
  }
  _v39_origSwitchTab(name);
  _v39_persistActiveTab(name);
  if (typeof syncNavWidget === "function") syncNavWidget(name);
  // Sync URL hash without scroll-jump
  try {
    const newHash = '#' + name;
    if (location.hash !== newHash) {
      history.replaceState(null, '', newHash);
    }
  } catch(e) {}
};

// --- URL hash routing: react to manual #anchor changes (back/forward, paste)
function _v39_routeFromHash() {
  const h = (location.hash || '').replace(/^#/, '').trim();
  if (!h) return;
  // Support #tab or #tab/bossId style
  const [tabName, bossId] = h.split('/');
  if (_v39_validTabName(tabName)) {
    if (!document.querySelector(`.tab[data-tab="${tabName}"].active`)) {
      _v39_origSwitchTab(tabName);
      _v39_persistActiveTab(tabName);
    }
    if (bossId && typeof window.openBossDetail === 'function') {
      // Defer slightly to let tab content render
      setTimeout(() => window.openBossDetail(bossId), 80);
    }
  }
}
window.addEventListener('hashchange', _v39_routeFromHash);

