// --- Sync pulse: when MF changes, briefly highlight all .chance cells
// so the user sees that the whole bible just resynchronized
let _v39_pulseTimer = null;
function _v39_pulseAllSyncedCells() {
  if (_v39_pulseTimer) return; // throttle within 600ms
  _v39_pulseTimer = setTimeout(() => { _v39_pulseTimer = null; }, 600);

  // PERF: pulse only the *summary* cells (~50 total), not every individual
  // table cell. Pulsing 19k+ cells caused per-element reflows that froze the page.
  // The visible "everything just resynced" message is conveyed via the prominent
  // summary cells — value displays, picks, top stats, slider readout.
  const targets = document.querySelectorAll([
    '.hero-pick-chance',  // 15-20 cells (top picks)
    '.sd-item-rate',      // 17 cells (special drops)
    '.verified-cell',     // 3 cells (verified anchors)
    '.stat-value',        // 8 cells (header stats)
    '#mf-val',            // MF readout
    '#eff-mf',            // effective MF
    '.boss-tier-val',     // 11 cells (one per boss)
    '.gbc-grail-chance',  // boss detail card grail chances (if open)
    '.gic-stat-value',    // item detail card stats (if open)
  ].join(','));

  if (!targets.length) return;

  // Single-pass class add — no per-element reflow trick.
  // CSS keyframe runs cleanly once; on rapid re-triggering the throttle handles dedupe.
  targets.forEach(el => el.classList.add('syncing'));

  // Strip the class after animation completes (.55s + buffer)
  setTimeout(() => {
    targets.forEach(el => el.classList.remove('syncing'));
  }, 700);
}

// Helper: run fn now if DOM is ready, else when DOMContentLoaded fires.
function _v39_whenReady(fn) {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', fn);
  } else {
    fn();
  }
}

// v116 — site-wide aura-logo rollout. Any element tagged data-aura-logo="<Aura>"
// gets the live animated aura gif injected as a leading logo chip, reusing the auraArt
// single-source helper (so every named aura across the bible carries the same "what to
// look for" visual as the bind cards). Idempotent — safe to call more than once.
function decorateAuraLogos() {
  if (typeof auraArt !== 'function') return 0;
  let n = 0;
  document.querySelectorAll('[data-aura-logo]').forEach((el) => {
    if (el.querySelector(':scope > .aura-logo')) return;
    const name = el.getAttribute('data-aura-logo');
    const glyph = el.getAttribute('data-aura-glyph') || '⚜️';
    el.insertAdjacentHTML('afterbegin', auraArt(name, glyph, 'sm') + ' ');
    el.classList.add('aura-cell');
    // make the aura cell open its ID card (route through openBindAuraByName)
    el.classList.add('aura-clickable');
    el.setAttribute('role', 'button');
    el.setAttribute('tabindex', '0');
    el.setAttribute('title', 'open ' + name + "'s aura ID card");
    el.addEventListener('click', (ev) => { ev.stopPropagation(); if (typeof openBindAuraByName === 'function') openBindAuraByName(name); });
    el.addEventListener('keydown', (ev) => { if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); el.click(); } });
    n++;
  });
  return n;
}
window.decorateAuraLogos = decorateAuraLogos;
_v39_whenReady(decorateAuraLogos);

// v123 — inline item-logo rollout. Any element tagged data-art-logo="<Item>" gets the
// verified D2IO_ART graphic injected as a leading logo chip via the artOr single-source
// helper (the same art the boss / material cards use), with the cell's data-art-glyph
// emoji kept as the never-broken fallback. ONLY decorates names that resolve in D2IO_ART,
// so an unregistered name is a silent no-op (no empty wrap, no regression). Idempotent —
// safe to call more than once. Existing onclick / openDrop routing is left untouched.
function decorateItemLogos() {
  if (typeof artOr !== 'function' || typeof artUrl !== 'function') return 0;
  let n = 0;
  document.querySelectorAll('[data-art-logo]').forEach((el) => {
    if (el.querySelector(':scope > .d2art-wrap')) return;
    const name = el.getAttribute('data-art-logo');
    if (!artUrl(name)) return; // only mapped names — no empty-wrap regression
    const glyph = el.getAttribute('data-art-glyph') || '';
    el.insertAdjacentHTML('afterbegin', artOr(name, glyph, 'sm') + ' ');
    el.classList.add('item-logo-cell');
    n++;
  });
  return n;
}
window.decorateItemLogos = decorateItemLogos;
_v39_whenReady(decorateItemLogos);
// v166 — delegated keyword routing: data-art-route opens an item/material card
// (openDrop), data-boss-route opens a boss card. Keeps data strings free of
// escaped-quote onclick handlers — enriched keywords stay plain HTML attributes.
document.addEventListener('click', function(e){
  var r = e.target.closest && e.target.closest('[data-art-route],[data-boss-route],[data-su-route]');
  if (!r) return;
  var item = r.getAttribute('data-art-route');
  var boss = r.getAttribute('data-boss-route');
  var suroute = r.getAttribute('data-su-route');
  if (item && typeof window.openDrop === 'function'){ e.stopPropagation(); window.openDrop(item); }
  else if (boss && typeof window.openBossDetail === 'function'){ e.stopPropagation(); window.openBossDetail(boss); }
  else if (suroute && typeof window.openBindSUByName === 'function'){ e.stopPropagation(); window.openBindSUByName(suroute); }
}, true);
// v166 — boss cards render enriched keyword spans too: re-run the logo decorator
// after every boss-card open (idempotent, cheap — only undecorated spans get touched).
if (typeof window.openBossDetail === 'function'){
  var __obd166 = window.openBossDetail;
  window.openBossDetail = function(){ var r = __obd166.apply(this, arguments); if (typeof decorateItemLogos === 'function') setTimeout(decorateItemLogos, 60); return r; };
}

