// Render the Field Manual into an open boss-detail-panel.
function _v40_renderBossFieldManual(bossId) {
  const fm = BOSS_FIELD_MANUAL[bossId];
  if (!fm) return;
  const panel = document.getElementById('boss-detail-panel');
  if (!panel || !panel.classList.contains('show')) return;
  // Don't double-inject
  if (panel.querySelector('.field-manual')) return;
  const html = `
    <div class="field-manual">
      <div class="field-manual-header">Field Manual · How to Farm</div>
      <div class="field-manual-body">
        <div class="fm-section">
          <div class="fm-section-label">🗺 Run Pattern</div>
          <div class="fm-section-body">${fm.run}</div>
        </div>
        <div class="fm-section">
          <div class="fm-section-label">🎯 Key Targets</div>
          <div class="fm-section-body">${fm.key_mobs}</div>
        </div>
        <div class="fm-section">
          <div class="fm-section-label">⚠ Pitfalls</div>
          <div class="fm-section-body">${fm.pitfalls}</div>
        </div>
        <div class="fm-section">
          <div class="fm-section-label">💎 Pro Tip</div>
          <div class="fm-section-body">${fm.pro_tip}</div>
        </div>
        <div class="fm-section" style="grid-column: 1 / -1; background: rgba(240,192,96,.05); border-color: rgba(240,192,96,.2);">
          <div class="fm-section-label">📜 Quest Note</div>
          <div class="fm-section-body">${fm.quest}</div>
        </div>
      </div>
    </div>`;
  // Inject before the close button if possible, otherwise at end
  const closeBtn = panel.querySelector('.gbc-close');
  if (closeBtn) {
    closeBtn.insertAdjacentHTML('beforebegin', html);
  } else {
    panel.insertAdjacentHTML('beforeend', html);
  }
}

// Wrap openBossDetail to inject Field Manual after render
const _v40_origOpenBossDetail = window.openBossDetail;
if (_v40_origOpenBossDetail) {
  window.openBossDetail = function(bossId, focusDiff) {
    _v40_origOpenBossDetail.apply(this, arguments);
    // v42 polish: record in recently-viewed
    try {
      if (bossId && typeof window._v42_pushRecent === 'function' && typeof BOSSES !== 'undefined') {
        const boss = BOSSES.find(b => b.id === bossId);
        const label = boss ? (boss.n || boss.name || bossId) : bossId;
        window._v42_pushRecent({ label, cat: 'boss' });
      }
    } catch(e) {}
    // Defer to let the original render finish
    setTimeout(() => _v40_renderBossFieldManual(bossId), 50);
  };
}

// Inject Tips & Wisdom + Methodology into the Reference tab
function _v40_renderRefExtras() {
  const refTab = document.getElementById('tab-ref');
  if (!refTab) return;
  if (refTab.querySelector('.v40-extras')) return; // dedupe

  // Tips bento
  const tipsHtml = TIPS_WISDOM.map(t => `
    <div class="tip-card">
      <span class="tip-card-label">${t.label}</span>
      ${t.body}
    </div>
  `).join('');

  // Methodology accordion
  const methodologyHtml = `
    <details class="methodology-block">
      <summary>ℹ How drop chances are calculated</summary>
      <div class="methodology-content">
        <p>Every chance in this bible is computed from D2R's atomic drop formula. The displayed value is <strong>1:N</strong> where N is the expected number of monster kills per drop of that specific item at the listed difficulty.</p>
        <div class="methodology-formula">
          chance = (TCprob × NoDropAdj × ItemRatio × QualityAdj × MFAdj)<sup>-1</sup>
        </div>
        <p>The formula factors:</p>
        <ul style="margin: 8px 0 8px 22px; line-height: 1.8;">
          <li><strong>TCprob</strong> — chance the monster's treasure class rolls the item's TC bucket (set during area init, mlvl-gated)</li>
          <li><strong>NoDropAdj</strong> — players-setting modifier; reduces "no drop" rolls in larger games</li>
          <li><strong>ItemRatio</strong> — base ratio between items in the same TC (Shako vs Tal's Mask in TC87 cluster)</li>
          <li><strong>QualityAdj</strong> — Unique vs Set vs Rare vs Magic split, gated by item-level</li>
          <li><strong>MFAdj</strong> — your MF% applied with the diminishing-return curve (effective MF = MF × 250 / (MF + 250) for uniques)</li>
        </ul>
        <p><strong>Verified anchors</strong> (cross-checked against d2.io, Silospen, and live PlugY tests):</p>
        <div class="methodology-formula" style="color: var(--verified); border-color: rgba(0,255,170,.3);">
          Hell Mephisto × Shako (Harlequin Crest) = 1:836<br>
          Hell TZ Mephisto × Shako = 1:1,287<br>
          NM TZ Mephisto × Shako = 1:2,812<br>
          Countess × Ist (all diffs) = 1:850 baseline
        </div>
        <p style="margin-top: 12px; font-size: 11.5px; color: var(--text-muted);">Routine L (data integrity drift detection, runs daily) validates these anchors against the data file. Any drift triggers a Telegram alert.</p>
      </div>
    </details>
  `;

  // Build the wrapper
  const wrapper = document.createElement('div');
  wrapper.className = 'v40-extras';
  wrapper.innerHTML = `
    <h2 class="sec-h collapsed" onclick="toggleSec(this)"><span class="sec-h-art">💡</span><span class="sec-h-t">Tips &amp; Wisdom</span><span class="sec-chev">▾</span></h2>
    <div class="sec-body" hidden>
      <div style="font-size:12px;color:var(--text-muted);margin-bottom:8px;">Curated D2R knowledge — verified, not folklore.</div>
      <div class="tips-bento">${tipsHtml}</div>
    </div>
    <h2 class="sec-h collapsed" onclick="toggleSec(this)"><span class="sec-h-art">🔬</span><span class="sec-h-t">Methodology</span><span class="sec-chev">▾</span></h2>
    <div class="sec-body" hidden>
      ${methodologyHtml}
    </div>
  `;
  refTab.appendChild(wrapper);
}

// Helper: run when ready
function _v40_whenReady(fn) {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', fn);
  } else {
    fn();
  }
}

_v40_whenReady(() => {
  _v40_renderRefExtras();
});

const _v41_STATUS_PATHS = [
  'routine_status.js',  // sibling to bible (Downloads)
  '/Users/konyo/Downloads/routine_status.js',  // absolute fallback
  '/Users/konyo/d2r_bible_routines/obsidian_data/routine_status.js',  // routines path
];

function _v41_loadStatusScript(idx, cb) {
  // routine_status.js only exists alongside the LOCAL file:// copies (Konyo's machine).
  // The deployed https site never serves it, so every path 404s to the SPA HTML
  // fallback and the browser logs a "Refused to execute script (MIME 'text/html')"
  // error that the script-tag onerror handler cannot suppress. Off of file://, skip
  // injection entirely — the routine widget simply shows its idle "— / —" state.
  if (location.protocol !== 'file:') { cb(null); return; }
  if (idx >= _v41_STATUS_PATHS.length) { cb(null); return; }
  const url = _v41_STATUS_PATHS[idx];
  // Use a fresh script tag so we can retry alternates if one fails
  const s = document.createElement('script');
  s.src = url + '?_=' + Date.now(); // cache-bust
  // v42 polish: remove the script tag after load/error to prevent <head> accumulation.
  // _v41_refreshStatus fires every 60s; without cleanup, ~3000 dead script tags
  // pile up per 24h of runtime.
  const cleanup = () => { try { s.remove(); } catch(e) {} };
  s.onload = () => { cb(window.ROUTINE_STATUS || null); cleanup(); };
  s.onerror = () => { cleanup(); _v41_loadStatusScript(idx + 1, cb); };
  document.head.appendChild(s);
}

function _v41_applyStatus(st) {
  if (!st) return;
  // Update each .routine-letter with data-status + tooltip
  document.querySelectorAll('.routine-letter').forEach(el => {
    const rid = el.getAttribute('data-r');
    if (!rid || !st.routines || !st.routines[rid]) {
      el.setAttribute('data-status', 'inactive');
      return;
    }
    const r = st.routines[rid];
    el.setAttribute('data-status', r.status);
    // Build tooltip
    const tip = [
      `Routine ${rid} · ${r.status.toUpperCase()}`,
      `Schedule: ${r.schedule}`,
      r.last_run ? `Last: ${r.last_run}` : `Last: (never)`,
      `Today: ${r.fires_today}/${r.expected_per_day} fires`,
      `Summary: ${r.summary || '—'}`
    ].join('\n');
    el.setAttribute('data-tooltip', tip);
  });
  // Update fires counter
  const counter = document.getElementById('routine-fires-counter');
  if (counter) {
    const rs = Object.values(st.routines || {});
    const fired = Number.isFinite(st.total_fires_today) ? st.total_fires_today
                : rs.reduce((n, r) => n + (Number(r.fires_today) || 0), 0);
    const expected = Number.isFinite(st.total_expected_today) ? st.total_expected_today
                   : rs.reduce((n, r) => n + (Number(r.expected_per_day) || 0), 0);
    counter.textContent = (rs.length && (fired || expected))
      ? `${fired}/${expected} fires today`
      : 'status offline';   // v642 — a permanent '— / —' read as broken; say what it is
    const anyRed = Object.values(st.routines || {}).some(r => r.status === 'red');
    counter.className = anyRed ? 'has-red' : (st.all_green ? 'all-green' : '');
    counter.title = st.generated_at ? `Status snapshot: ${st.generated_at}` : 'Routine status snapshot';
  }
}

function _v41_refreshStatus() {
  // Clear cached window.ROUTINE_STATUS to force fresh load
  try { delete window.ROUTINE_STATUS; } catch(e) {}
  _v41_loadStatusScript(0, st => {
    if (st) _v41_applyStatus(st);
  });
}

// Inject the fires counter + refresh button into the routine widget header
function _v41_findRoutineBar() {
  // Widget ID varies across bible versions. Try known IDs in order.
  return document.getElementById('routine-toggle-pulse')
      || document.getElementById('routine-status-bar')
      || document.getElementById('routine-bar')
      || document.querySelector('[id*="routine"][id*="bar"], [id*="routine"][id*="pulse"]');
}

function _v41_enhanceWidget() {
  const bar = _v41_findRoutineBar();
  if (!bar) return;
  if (bar.querySelector('#routine-fires-counter')) return; // already enhanced
  // Find the header line (containing the title or letters)
  // The widget structure varies — try to find a sensible insertion point
  // v642 — NEVER create a second header (the old fallback injected a duplicate '⚙ Routines' row
  // above the widget's own '🤖 ROUTINES' one — Konyo saw both). The widget's first flex row IS the
  // header: mount the counter + refresh there, before the × close button.
  let header = bar.querySelector('.routine-bar-header') || bar.firstElementChild;
  if (!header) return;
  const counter = document.createElement('span');
  counter.id = 'routine-fires-counter';
  counter.textContent = 'status…';
  counter.style.marginLeft = 'auto';
  const refreshBtn = document.createElement('button');
  refreshBtn.id = 'routine-refresh-btn';
  refreshBtn.textContent = '↻';
  refreshBtn.title = 'Refresh routine status now';
  refreshBtn.onclick = () => {
    refreshBtn.classList.add('spinning');
    setTimeout(() => refreshBtn.classList.remove('spinning'), 800);
    _v41_refreshStatus();
  };
  const closeBtn = header.querySelector('button');
  if (closeBtn){ header.insertBefore(counter, closeBtn); header.insertBefore(refreshBtn, closeBtn); }
  else { header.appendChild(counter); header.appendChild(refreshBtn); }
  counter.style.marginLeft = 'auto'; counter.style.fontSize = '9px';
}

// Helper: run when ready
function _v41_whenReady(fn) {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', fn);
  } else {
    fn();
  }
}

_v41_whenReady(() => {
  _v41_enhanceWidget();
  // Initial load
  _v41_refreshStatus();
  // Refresh every 60s so widget reflects new routine fires
  setInterval(_v41_refreshStatus, 60000);
  // Also re-enhance widget if it gets re-rendered (defensive)
  setTimeout(_v41_enhanceWidget, 500);
});

